#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

int initialize(long **offsets, int **keys, Record ***records, size_t size) {
    srand((unsigned int) time(NULL)); // seed the random number generator

    *offsets = (long*) malloc(sizeof(long) * size);
    if (*offsets == NULL) return -1;

    *keys = (int*) calloc(size, sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -2;
    }

    *records = (Record**) malloc(sizeof(Record*) * size);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -3;
    }

    for (size_t i = 0; i < size; ++i) {
        (*records)[i] = (Record*) malloc(sizeof(Record));
        if ((*records)[i] == NULL) {
            // clean up previously allocated memory on failure
            for (--i; i >= 0; --i) free((*records)[i]);
            free(*offsets);
            free(*keys);
            free(*records);
            return -4;
        }

        (*records)[i]->value = rand() % 100; // set value to a random integer within [0, 99] range
    }

    return verify(*offsets, *keys, *records, size);
}

int verify(long *offsets, int *keys, Record **records, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (records[i]->value < 0 || records[i]->value > 99) return -5; // check value is within range
    }

    return 0; // all checks passed
}
```
