['Here is a basic implementation in C using getopt_long for command line argument parsing and libcurl for logging service integration. This code does not include the actual file processing or compression logic, as these would be quite complex and depend on your specific requirements. 

```c
#include <stdio.h>
#include <getopt.h>
#include <time.h>
#include <curl/curl.h>
#include <json-c/json.h>

static const struct option long_options[] = {
    {"help", no_argument, NULL, 'h'},
    {"manpage", no_argument, NULL, 1},
    {"compress", required_argument, NULL, 'c'},
    {"output", required_argument, NULL, 'o'},
    {"max-chunk-size", required_argument, NULL, 'm'},
    {"log-level", required_argument, NULL, 'l'},
    {NULL, 0, NULL, 0}
};

void send_log(CURL *curl, struct json_object *json) {
    CURLcode res;
    char *payload = (char *)json_object_to_json_string(json);

    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
    res = curl_easy_perform(curl);

    if(res != CURLE_OK) {
        fprintf(stderr, "Failed to send log: %s\n", curl_easy_strerror(res));
    }
}

int main(int argc, char *argv[]) {
    int option_index = 0;
    int c;

    struct json_object *json = json_object_new_object();
    time_t start_time = time(NULL);
    json_object_object_add(json, "start_time", 
                           json_object_new_int64(start_time));

    CURL *curl = curl_easy_init();
    if(!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return -1;
    }

    while((c = getopt_long(argc, argv, "hc:o:m:l:", long_options, &option_index)) != -1) {
        switch (c) {
            case 'h':
                printf("Usage information\n");
                break;
            case 1:
                printf("Manpage information\n");
                break;
            case 'c':
                json_object_object_add(json, "compress", 
                                       json_object_new_string(optarg));
                break;
            case 'o':
                json_object_object_add(json, "output", 
                                       json_object_new_string(optarg));
                break;
            case 'm':
                json_object_object_add(json, "max_chunk_size", 
                                       json_object_new_int(atoi(optarg)));
                break;
            case 'l':
                json_object_object_add(json, "log_level", 
                                       json_object_new_string(optarg));
                break;
        }
    }

    time_t end_time = time(NULL);
    json_object_object_add(json, "end_time", 
                           json_object_new_int64(end_time));

    send_log(curl, json);

    curl_easy_cleanup(curl);
    return 0;
}
```
This code is a starting point and does not include the actual file processing or compression logic. It also doesn't handle errors that may occur during file reading/writing or libcurl operations, which you should add in a production environment. Also, this code assumes that the logging service accepts logs via HTTP POST requests with JSON payloads.
