```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char hostname[256];
    double performance;
} NetworkSetting;

NetworkSetting* read_config(const char* filename, int* count) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open the file.\n");
        exit(1);
    }

    NetworkSetting* settings = malloc(sizeof(NetworkSetting));
    *count = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        NetworkSetting setting;

        // Assuming the format is "hostname performance"
        sscanf(line, "%s %lf", setting.hostname, &setting.performance);

        settings = realloc(settings, (*count + 1) * sizeof(NetworkSetting));
        settings[*count] = setting;
        (*count)++;
    }

    fclose(file);
    return settings;
}

void calculate_average(const NetworkSetting* settings, int count) {
    for (int i = 0; i < count; i++) {
        double sum = 0.0;
        int num_entries = 0;

        // Calculate the average over the last three entries
        for (int j = i - 2; j <= i; j++) {
            if (j >= 0 && strcmp(settings[i].hostname, settings[j].hostname) == 0) {
                sum += settings[j].performance;
                num_entries++;
            }
        }

        double average = sum / num_entries;
        printf("%s, %.2lf\n", settings[i].hostname, average);
    }
}

int main() {
    int count = 0;
    NetworkSetting* settings = read_config("config.txt", &count);

    calculate_average(settings, count);

    free(settings);
    return 0;
}
```
This code reads a configuration file and calculates the average performance metric over the last three entries for each hostname. It uses dynamic memory allocation to store the settings from the file. The `read_config` function reads the file line by line, dynamically allocating more space as needed. The `calculate_average` function then iterates through the settings and calculates the average performance metric over the last three entries for each hostname.
