            .maximumSize(10_000)
            .expireAfterWrite(24, TimeUnit.HOURS)
            .build();

    public void generateReports(List<Pokemon> pokemons) {
        for (Pokemon pokemon : pokemons) {
            try {
                Pokemon cachedPokemon = cache.getIfPresent(pokemon.getName());

                if (cachedPokemon == null) {
                    // Call API to get details of the pokemon
                    // Handle potential exceptions and null values

                    // Add the fetched Pokemon to the cache
                    cache.put(pokemon.getName(), pokemon);
                } else {
                    pokemon = cachedPokemon;
                }

                System.out.println("Name: " + pokemon.getName());
                System.out.println("Type: " + pokemon.getType());
                // Print other details...
            } catch (Exception e) {
                System.err.println("Failed to generate report for Pokemon: " + pokemon.getName() + ". Reason: " + e.getMessage());
            }
        }
    }
}
```
