} NamedSemaphore;

NamedSemaphore semaphores[MAX_SEMAPHORES];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int num_semaphores = 0;

void *create_semaphore(char *name, int value) {
    pthread_mutex_lock(&mutex);

    if (num_semaphores >= MAX_SEMAPHORES) {
        // Handle overflow here. For example, you could queue requests or throttle.
        return NULL;
    }

    for (int i = 0; i < num_semaphores; ++i) {
        if (strcmp(name, semaphores[i].name) == 0) {
            // Handle naming conflict here. For example, you could append a number or return an error.
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    }

    NamedSemaphore *sem = &semaphores[num_semaphores++];
    sem->name = strdup(name);
    sem_init(&sem->sem, 0, value);

    pthread_mutex_unlock(&mutex);

    return sem;
}

void delete_semaphore(char *name) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_semaphores; ++i) {
        if (strcmp(name, semaphores[i].name) == 0) {
            free(semaphores[i].name);

            // Move the last semaphore to this position and decrement the count.
            semaphores[i] = semaphores[--num_semaphores];

            break;
        }
    }

    pthread_mutex_unlock(&mutex);
}

void *acquire_semaphore(char *name) {
    for (int i = 0; i < num_semaphores; ++i) {
        if (strcmp(name, semaphores[i].name) == 0) {
            // This operation is thread-safe.
            sem_wait(&semaphores[i].sem);

            return &semaphores[i];
        }
    }

    return NULL;
}

void release_semaphore(NamedSemaphore *sem) {
    // This operation is thread-safe.
    sem_post(&sem->sem);
}
```
This code does not handle all the constraints you mentioned, but it should give you a good starting point. You would need to add error handling and concurrency control for each function as needed. Also, this implementation assumes that the number of semaphores will never exceed 10. If this is not the case, you would need to implement a dynamic array or similar data structure to handle an arbitrary number of semaphores.
']

