['Here's a basic implementation of `insertAfterOrAppend` function in C++. This code assumes that you have a custom doubly-linked list class with nodes containing string and integer values, and an iterator to traverse through this list. 

```cpp
#include <iostream>
using namespace std;

// Assuming Node structure for the linked list
struct Node {
    string data;
    int value;
    Node* prev;
    Node* next;
};

// Assuming DoublyLinkedList class with insertAfterOrAppend function
class DoublyLinkedList {
public:
    Node* head; // head of list

    // Function to add a node at the end of the list
    void append(string new_data, int value) {
        Node* new_node = new Node();
        new_node->data = new_data;
        new_node->value = value;
        new_node->next = NULL;

        if (head == NULL) {
            new_node->prev = NULL;
            head = new_node;
            return;
        }

        Node* last = head;
        while (last->next != NULL)
            last = last->next;

        last->next = new_node;
        new_node->prev = last;
    }

    // Function to insert a node after the given iterator
    void insertAfterOrAppend(Node* prev_node, string new_data, int value) {
        if (prev_node == NULL) {
            cout << "The given previous node cannot be NULL";
            return;
        }

        Node* new_node = new Node();
        new_node->data = new_data;
        new_node->value = value;
        new_node->next = prev_node->next;
        prev_node->next = new_node;
        new_node->prev = prev_node;

        if (new_node->next != NULL)
            new_node->next->prev = new_node;
    }
};
```
This code does not handle external data sources or system dependencies. It's a basic implementation and doesn't include error handling for edge cases, such as inserting after the last node in an empty list. You would need to add these features based on your specific requirements. 

