#include <boost/asio.hpp>
#include <boost/beast.hpp>
#include <boost/log/trivial.hpp>
#include <boost/thread/executors/basic_thread_pool.hpp>
#include <nlohmann/json.hpp>

using json = nlohmann::json;
namespace net = boost::asio;                   
using tcp = net::ip::tcp;                       
namespace beast = boost::beast;                 
namespace http = beast::http;                    
namespace log = boost::log;                     
namespace sys = boost::system; 

class RestClient {
public:
    explicit RestClient(net::io_context& ioc) : resolver_(ioc), stream_(ioc) {}

    void fetchData() {
        beast::http::async_read(stream_, buffer_, res_, [this](sys::error_code ec, std::size_t bytesTransferred){
            if(!ec) {
                log::core::get()->set_filter (log::trivial::severity >= log::trivial::info);
                BOOST_LOG_TRIVIAL(info) << "Received data: " << res_.body();
                fetchData();
            } else if(ec != beast::http::error::end_of_stream){
                BOOST_LOG_TRIVIAL(error) << "Error reading response: " << ec.message();
            }
        });
    }

private:
    tcp::resolver resolver_;
    beast::tcp_stream stream_;
    beast::flat_buffer buffer_; 
    http::response<http::string_body> res_;
};

int main() {
    net::io_context ioc;
    boost::executors::basic_thread_pool pool(15); // limit to 15 concurrent requests
    net::post(ioc, [&](){
        RestClient client(ioc);
        client.fetchData();
    });
    ioc.run();
}
```
