['Here is a basic implementation of your requirements in C++ using the Mersenne Twister engine from the standard library for generating random numbers. This code does not include all the features you requested like integration with an external data source or handling large-scale load scenarios, but it should give you a good starting point:

```cpp
#include <random>
#include <mutex>
#include <vector>
#include <stdexcept>

namespace RandomService {
    enum class NumberType {
        Integer,
        Float
    };

    class RandomNumberGenerator {
    private:
        std::mt19937 mt;
        std::mutex mutex;

    public:
        RandomNumberGenerator() : mt(std::random_device{}()) {}

        explicit RandomNumberGenerator(unsigned int seed) : mt(seed) {}

        // Copy constructor
        RandomNumberGenerator(const RandomNumberGenerator& other) {
            std::lock_guard<std::mutex> lock(other.mutex);
            this->mt = other.mt;
        }

        // Move constructor
        RandomNumberGenerator(RandomNumberGenerator&& other) noexcept {
            std::lock_guard<std::mutex> lock(other.mutex);
            this->mt = std::move(other.mt);
        }

        // Copy assignment operator
        RandomNumberGenerator& operator=(const RandomNumberGenerator& other) {
            if (this != &other) {
                std::lock_guard<std::mutex> lock(other.mutex);
                this->mt = other.mt;
            }
            return *this;
        }

        // Move assignment operator
        RandomNumberGenerator& operator=(RandomNumberGenerator&& other) noexcept {
            if (this != &other) {
                std::lock_guard<std::mutex> lock(other.mutex);
                this->mt = std::move(other.mt);
            }
            return *this;
        }

        // Destructor
        ~RandomNumberGenerator() = default;

        void setSeed(unsigned int seed) {
            std::lock_guard<std::mutex> lock(mutex);
            mt.seed(seed);
        }

        int getInteger() {
            std::lock_guard<std::mutex> lock(mutex);
            return mt();
        }

        double getFloat() {
            std::lock_guard<std::mutex> lock(mutex);
            return static_cast<double>(mt()) / (static_cast<double>(mt.max()) + 1.0);
        }
    };
}
```
This code provides a thread-safe random number generator that can generate integers and floating point numbers. It uses the Mersenne Twister engine from the standard library, which is known for its high quality of randomness. The class also includes methods to set the seed externally, allowing for deterministic outcomes when necessary.
']

