public class DataIngestionService
{
    public async Task<BulkInsertSummary> BulkInsertAsync(List<string> serializedObjects, string connectionString, string targetTableName)
    {
        var summary = new BulkInsertSummary();
        using (var bulkCopy = new SqlBulkCopy(connectionString))
        {
            bulkCopy.DestinationTableName = targetTableName;
            try
            {
                // Assuming that serializedObjects are in JSON format and each object represents a row of data
                var dt = JsonConvert.DeserializeObject<DataTable>(serializedObjects[0]);
                foreach (var obj in serializedObjects.Skip(1))
                {
                    dt.Merge(JsonConvert.DeserializeObject<DataTable>(obj));
                }

                await bulkCopy.WriteToServerAsync(dt);
            }
            catch (Exception ex)
            {
                summary.Errors.Add(ex.ToString());
            }
        }

        return summary;
    }
}

public class BulkInsertSummary
{
