```javascript
const express = require('express');
const axios = require('axios');
const redis = require('redis');
const bodyParser = require('body-parser');

// Initialize Express app and Redis client
const app = express();
app.use(bodyParser.json());
const cache = redis.createClient({ host: 'localhost', port: 6379 });
cache.on('error', (err) => console.log('Redis Error: ', err));

// Fetch metadata from external service
async function fetchMetadata(id) {
    const response = await axios.get(`https://external-service/${id}`);
    return response.data;
}

// PUT endpoint for updating resource
app.put('/resource/:id', async (req, res) => {
    try {
        const id = req.params.id;
        // Update the resource in your database here...

        // Fetch metadata and update cache
        const metadata = await fetchMetadata(id);
        cache.setex(`resource:${id}`, 3600, JSON.stringify({ ...req.body, metadata }));

        res.status(200).json({ id, ...req.body, metadata });
    } catch (err) {
        console.error('Error updating resource: ', err);
        res.status(500).send();
    }
});

// DELETE endpoint for soft-deleting resource
app.delete('/resource/:id', async (req, res) => {
    try {
        const id = req.params.id;
        // Soft delete the resource in your database here...

        // Remove from cache and invalidate metadata
        cache.del(`resource:${id}`);
        await fetchMetadata(id);  // Fetch again to update cache

        res.status(204).send();
    } catch (err) {
        console.error('Error deleting resource: ', err);
        res.status(500).send();
    }
});

app.listen(3000, () => console.log('Server running on port 3000'));
```

This is a simplified example and doesn't include all the requirements you mentioned such as handling concurrent requests, operational constraints, data integrity, usability, logging and monitoring etc. You would need to add these features according to your specific needs. Also, this code assumes that you have Redis running locally on port 6379.
