use std::fs::{self, File};
use std::path::PathBuf;
use std::env;
use std::sync::OnceLock;
use std::io::Write;
use std::thread;
use std::time::Duration;

static ONCE: OnceLock = OnceLock::new();

pub fn EnsureDirectoryExistsAndConfigure(dir_path: &str, setting_name: &str, setting_value: &str) {
    let mut dir_path = PathBuf::from(dir_path);

    // Expand environment variables in the directory path
    dir_path = env::expand_vars(&dir_path).unwrap_or(dir_path);

    ONCE.call_once(|| {
        thread::sleep(Duration::from_millis(10));  // Avoid race conditions

        if !fs::metadata(&dir_path).is_ok() {
            fs::create_dir_all(&dir_path).unwrap();

            let mut config_file = File::create(dir_path.join("config")).unwrap();
            write_line(&mut config_file, format_args_1_0_293_nightly![setting_name "=" setting_value]).unwrap();
        }
    });
}
