const BlueSlip = require('blueslip'); // Assuming blueslip is a mocking library
const { performance } = require('perf_hooks');

async function runTests(label, f, maxConcurrency, reportService) {
  const tests = Array.from({ length: maxConcurrency }, () => f);

  try {
    await Promise.all(tests.map(async (test, i) => {
      const startTime = performance.now();

      try {
        console.log(`Running test ${i + 1} for module ${label}...`);

        // Execute the test function
        await test();

        const endTime = performance.now();
        const duration = (endTime - startTime).toFixed(2);

        console.log(`Test ${i + 1} for module ${label} passed in ${duration} ms.`);

        // Report the test result to the external service
        await reportService.report({
          label,
          test: `test${i + 1}`,
          duration,
          status: 'passed'
        });
      } catch (error) {
        console.log(`Test ${i + 1} for module ${label} failed with error: ${error.message}.`);

        // Report the test result to the external service
        await reportService.report({
          label,
          test: `test${i + 1}`,
          duration: 0,
          status: 'failed',
          errorMessage: error.message
        });
      } finally {
        // Reset blueslip after each test
        BlueSlip.reset();
      }
    }));

    console.log(`All tests for module ${label} have been executed.`);
  } catch (error) {
    console.log(`An error occurred while running the tests: ${error.message}.`);
  }
}
