let cache = new Map(); // Memoization cache

function traverseDOM(rootElement, selector) {
    if (cache.has(selector)) {
        return cache.get(selector);
    }

    let elements = Array.from(rootElement.querySelectorAll(selector));
    cache.set(selector, elements); // Store result in cache

    return elements;
}
```
This function uses a memoization strategy to store results of previous queries and reuse them when the same selector is used again. This reduces redundant traversals and improves performance for large DOM trees. 

