from sqlalchemy.orm import sessionmaker
from redis import Redis
import os
import time
import threading

app = Flask(__name__)
redis = Redis(host='localhost', port=6379)

class Theme(Base):
    __tablename__ = 'themes'

    id = Column(Integer, primary_key=True)
    name = Column(String)
    path = Column(String)

engine = create_engine('sqlite:///theme.db')
Session = sessionmaker(bind=engine)
session = Session()

class ThemeCache:
    def __init__(self):
        self.cache = redis

    def get(self, key):
        return self.cache.get(key)

    def set(self, key, value):
        self.cache.set(key, value)

class ThemeService:
    def __init__(self):
        self.theme_dir = os.path.join(app.root_path, 'themes')
        if not os.path.exists(self.theme_dir):
            os.makedirs(self.theme_dir)

    def get_all_themes(self):
        return session.query(Theme).all()

class ThemeBackgroundService:
    def __init__(self, interval=60):
        self.interval = interval
        self.cache = ThemeCache()
        self.service = ThemeService()
        thread = threading.Thread(target=self.run, args=())
        thread.daemon = True  # Daemonize thread
        thread.start()  # Start the execution

    def run(self):
        while True:
            themes = self.service.get_all_themes()
            for theme in themes:
                self.cache.set(theme.name, theme.path)
            time.sleep(self.interval)
```

