```rust
use std::process::{Command, Stdio};
use std::time::Instant;
use rustc_driver::catch_with_exit_code;
use std::mem::size_of_val;
use libc::{va_start, va_end, __va_list_tag};
use std::ffi::CString;
use std::os::unix::process::ExitStatusExt;

fn measure_compilation(rustc_args: Vec<&str>) -> Result<(), i32> {
    let before = Instant::now();
    let before_mem = get_resident_set_size();

    catch_with_exit_code(|| {
        Command::new("rustc")
            .args(&rustc_args)
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()?;

        Ok(())
    })?;

    let after = Instant::now();
    let after_mem = get_resident_set_size();

    println_metrics(after.duration_since(before).as_secs(), before_mem, after_mem);

    Ok(())
}

fn get_resident_set_size() -> usize {
    let output = Command::new("ps")
        .arg("-o")
        .arg("rss=")
        .arg(std::process::id().to_string())
        .output()
        .expect("failed to execute process");

    std::str::from_utf8(&output.stdout)
        .unwrap()
        .trim()
        .parse::<usize>()
        .unwrap()
}

fn print_metrics(duration: u64, before_mem: usize, after_mem: usize) {
    let mem_change = after_mem - before_mem;

    // Here you would call your C function to log the metrics. 
    // This is a placeholder for that call.
    unsafe {
        let fmt: *const __va_list_tag = std::ptr::null();
        let mut args: __va_list_tag = va_start(fmt);

        let c_str = CString::new("Memory change: %ld, Duration: %ld").unwrap();
        snprintf(c_str.as_ptr(), size_of_val(&mem_change) + size_of_val(&duration), c_str.as_ptr(), mem_change, duration);

        va_end(args);
    }
}
```
This code measures the time taken for compilation and the memory usage changes before and after the process using `std::time::Instant` and `/proc/<pid>/status`. It uses `rustc_driver::catch_with_exit_code` to handle errors robustly. The function `print_metrics` is a placeholder for calling your C component within the logging hook, which would involve using FFI (Foreign Function Interface) to call the C function from Rust.

