async function readConfigFileAsync($filePath) {
    $contents = [];
    if (is_readable($filePath)) {
        $handle = fopen($filePath, 'r');
        while (($line = fgets($handle)) !== false) {
            $parts = explode('=', $line);
            if (count($parts) === 2) {
                $contents[trim($parts[0])] = trim($parts[1]);
            }
        }
        fclose($handle);
    } else {
        throw new Exception("File not found or not readable: $filePath");
    }
    return $contents;
}

async function processAsync($length, $apiKey, $algorithm, $configDir) {
    $randomString = generateRandomString($length);
    $hashedApiKey = hashApiKey($apiKey, $algorithm);

    try {
        $files = scandir($configDir);
        foreach ($files as $file) {
            if (!is_dir("$configDir/$file")) {
                $contents[] = readConfigFileAsync("$configDir/$file");
            }
        }
    } catch (Exception $e) {
        $contents = $e->getMessage();
    }

    $result = [
        'randomString' => $randomString,
        'hashedApiKey' => $hashedApiKey,
        'configContents' => $contents
    ];

    return $result;
}
?>
