        $this->redis = $redis;
        $this->db = $db;
    }

    public function updatePassword($userId, $newPassword) {
        // Check password history and complexity here...

        // Lock the user record to prevent concurrent updates
        $lockKey = "user:{$userId}:lock";
        $acquiredLock = $this->redis->setnx($lockKey, 1);
        $this->redis->expire($lockKey, 5); // Lock expires after 5 seconds

        if ($acquiredLock) {
            try {
                // Update the password in the database
                $stmt = $this->db->prepare("UPDATE users SET password = ? WHERE id = ?");
                $stmt->execute([password_hash($newPassword, PASSWORD_DEFAULT), $userId]);

                // Invalidate any cached sessions for this user
                $sessionsKey = "user:{$userId}:sessions";
                $this->redis->del($sessionsKey);
            } catch (Exception $e) {
                // Handle exceptions, possibly by rolling back the transaction and alerting admins
            } finally {
                // Release the lock
                $this->redis->del($lockKey);
            }
        } else {
            // If we couldn't acquire a lock, throw an exception or handle it gracefully
        }
    }
}
