#include <iostream>
#include <chrono>
#include <thread>
#include <mutex>
#include <unordered_map>

// Define a struct to hold character's state
struct CharacterState {
    std::chrono::steady_clock::time_point lastActionTime;
};

std::unordered_map<int, CharacterState> charStates; // Map of characters and their states
std::mutex mtx; // Mutex for thread-safe operations

void selectAndPerformAction(int characterId) {
    std::lock_guard<std::mutex> lock(mtx); // Lock the mutex to ensure thread safety

    auto now = std::chrono::steady_clock::now(); // Get current time
    int cooldownPeriods[] = {8, 12, 16}; // Cooldown periods for each action
    int selectedAction = 0; // Default to Action A

    if (charStates.find(characterId) != charStates.end()) { // If character exists in map
        auto& state = charStates[characterId];

        // Calculate elapsed time since last action
        auto elapsedSeconds = std::chrono::duration_cast<std::chrono::seconds>(now - state.lastActionTime).count();

        for (int i = 0; i < 3; ++i) { // Find the first action that is ready
            if (elapsedSeconds >= cooldownPeriods[i]) {
                selectedAction = i + 1; // Action number is index plus one
                break;
            }
        }
    } else { // If character does not exist in map, initialize it
        charStates[characterId] = CharacterState{now};
    }

    std::cout << "Character " << characterId << " selected action: " << selectedAction << std::endl;

    // Update last action time for the character
    charStates[characterId].lastActionTime = now;
}
```
This code uses a `std::unordered_map` to store each character's state. The map is protected by a mutex, ensuring thread safety when accessing it from multiple threads. 

