function processNodeContent(node, sizeLimit, config) {
    let result = [];
    let textSize = 0;

    function traverse(node) {
        if (!node || node.nodeType !== Node.ELEMENT_NODE) return;

        // Apply filters based on configuration
        const classNameFilter = config.className ? `.${config.className}` : '';
        const idFilter = config.id ? `#${config.id}` : '';
        if (node.matches(`${classNameFilter}${idFilter}`)) {
            let textContent = node.textContent;

            // Apply callback function if provided
            if (typeof config.callback === 'function') {
                textContent = config.callback(textContent);
            }

            const length = textContent ? textContent.length : 0;
            if ((textSize + length) > sizeLimit) {
                result.push(null);
            } else {
                textSize += length;
                result.push(`${textContent}/`);
            }
        }

        // Recursively traverse child nodes
        for (let i = 0; i < node.childNodes.length; i++) {
            traverse(node.childNodes[i]);
        }
    }

    traverse(node);
    return result;
}
```
This function uses a depth-first search approach to traverse the DOM tree, which is efficient for large trees and avoids excessive resource consumption. It also handles edge cases such as empty nodes or non-text nodes by checking `nodeType` before processing. The function is designed to be easily extendable and maintainable with clear separation of concerns between different tasks (filtering, traversal, text content processing).
"]

