['Here is a basic implementation in C using libtiff library to parse TIFF files and OpenSSL library to compute MD5 hashes. This code does not include logging or concurrency handling due to the complexity of these topics. 

```c
#include <stdio.h>
#include <string.h>
#include <openssl/md5.h>
#include <tiffio.h>

typedef struct {
    uint16 bitsPerSample;
    uint16 samplePerPixel;
    int extraSamples;
    char md5Hash[MD5_DIGEST_LENGTH * 2 + 1]; // MD5 hash is 32 bytes long, each byte represented by two hex digits.
} ImageInfo;

ImageInfo parseTiff(const char* filename, const char* stringToHash) {
    TIFF* tif = TIFFOpen(filename, "r");
    if (tif == NULL) {
        fprintf(stderr, "Failed to open file %s\n", filename);
        exit(1);
    }

    ImageInfo info;
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &info.bitsPerSample);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &info.samplePerPixel);
    TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &info.extraSamples);

    if (info.bitsPerSample != 1 && info.bitsPerSample != 2 && info.bitsPerSample != 4 && 
        info.bitsPerSample != 8 && info.bitsPerSample != 16) {
        fprintf(stderr, "Unsupported bit depth: %d\n", info.bitsPerSample);
        exit(1);
    }

    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)stringToHash, strlen(stringToHash), md5);
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&info.md5Hash[i*2], "%02x", md5[i]);
    }

    TIFFClose(tif);
    return info;
}
```
This code does not handle errors for malformed files or unsupported bit depths, and it doesn't include logging. It also doesn't consider concurrency issues when used in a multi-threaded environment. For these features, you would need to add additional error checking and synchronization mechanisms. 

