void generate_filename(char *original, char *new) {
    // Constants for file types and buffer sizes
    const char *fileTypes[] = {".txt", ".log", ".csv"};
    const int MAX_FILENAME = 255;
    const int MAX_BASE = 240;  // Maximum length of base name (including count)

    // Check if original filename is not empty and does not contain only whitespace
    if(strlen(original) == 0 || strspn(original, " \t\r\n") == strlen(original)) {
        printf("Invalid filename.\n");
        return;
    }

    // Extract base name and extension from original filename
    char *base = strdup(original);
    char *extension = strrchr(base, '.');
    if (extension) *extension++ = '\0';  // Remove the dot

    // Replace non-alphanumeric characters in base name with underscores
    for(int i = 0; base[i]; i++) {
        if(!isalnum((unsigned char)base[i])) {
            base[i] = '_';
        }
    }

    // Calculate the number of characters in the base name (excluding extension)
    int count = strlen(base);

    // Randomly select a file type from predefined list and append it to new filename
    srand(time(NULL));
    char *fileType = (char *)fileTypes[rand() % 3];

    // Construct the new filename ensuring it does not exceed MAX_FILENAME characters in total length
    sprintf(new, "%s%d", base, count);
    int remainingLength = MAX_BASE - strlen(new);
    if (remainingLength > 0) {
        strncat(new, fileType, remainingLength);
    }

    // Check system dependencies: available disk space and file creation limits
    struct statvfs fs;
    if (statvfs(".", &fs) == 0 && ((fs.f_bavail * fs.f_bsize) < MAX_FILENAME)) {
        printf("Insufficient disk space.\n");
        return;
    }

    free(base);
}
```
This function follows the constraints you provided, but it's important to note that there are many other factors that could affect system performance and file creation limits. For example, the number of files in a directory can also be limited by the filesystem or operating system. Also, this code does not handle errors from `statvfs`, which might occur if the path is invalid or the user lacks permissions to access it.
']

