// Function to initialize AES-256-CBC cipher using OpenSSL library
EVP_CIPHER_CTX* init_cipher(const char *password) {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32]; // 256 bits = 32 bytes
    unsigned char iv[16]; // 128 bits = 16 bytes

    // Generate a secure random IV and Key using OpenSSL's RAND API
    if(!RAND_bytes(iv, sizeof(iv)) || !RAND_bytes(key, sizeof(key))) {
        return NULL; // Error generating IV or key
    }

    // Derive encryption key from password using a secure KDF (PBKDF2 in this case)
    if(!PKCS5_PBKDF2_HMAC_SHA1(password, strlen(password), NULL, 0, 32, key)) {
        return NULL; // Error deriving encryption key from password
    }

    // Initialize cipher context
    if(!(ctx = EVP_CIPHER_CTX_new())) {
        return NULL; // Couldn't create new cipher context
    }

    // Setup AES-256-CBC cipher with the key and IV
    if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        return NULL; // Couldn't initialize cipher context
    }

    return ctx;
}
```
This code initializes an AES-256-CBC cipher using a given password and the OpenSSL library. It generates a secure random IV and key, derives encryption key from the password using PBKDF2 (Password-Based Key Derivation Function 2), and then sets up the cipher context with these values.

