// Function to validate email format
bool isValidEmail(char *email) {
    regex_t regex;
    int reti = regcomp(&regex, "^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,6}$", REG_EXTENDED);
    if (reti) {
        fprintf(stderr, "Could not compile regex\n");
        return false;
    }
    reti = regexec(&regex, email, 0, NULL, 0);
    regfree(&regex);
    if (!reti) {
        return true;
    } else if (reti == REG_NOMATCH) {
        return false;
    } else {
        fprintf(stderr, "Regex match failed\n");
        return false;
    }
}

// Function to validate transaction request
bool isValidTransactionRequest(char *jsonPayload) {
    json_error_t error;
    json_t *root = json_loads(jsonPayload, 0, &error);

    if(!root) {
        fprintf(stderr, "Error parsing JSON: on line %d: %s\n", error.line, error.text);
        return false;
    }

    json_t *transactionId = json_object_get(root, "transaction_id");
    if(!json_is_string(transactionId) || strlen(json_string_value(transactionId)) > 64) {
        fprintf(stderr, "Invalid transaction id\n");
        return false;
    }

    json_t *amount = json_object_get(root, "amount");
    if(!json_is_real(amount) || json_real_value(amount) <= 0.0) {
        fprintf(stderr, "Invalid amount\n");
        return false;
    }

    json_t *currency = json_object_get(root, "currency");
    if(!json_is_string(currency)) {
        fprintf(stderr, "Invalid currency\n");
        return false;
    } else {
        char *curr = json_string_value(currency);
        if(strcmp(curr, "USD") && strcmp(curr, "EUR") && strcmp(curr, "GBP") && 
           strcmp(curr, "JPY") && strcmp(curr, "CAD")) {
            fprintf(stderr, "Unsupported currency\n");
            return false;
        }
    }

    json_t *payerEmail = json_object_get(root, "payer_email");
    if(!json_is_string(payerEmail) || !isValidEmail(json_string_value(payerEmail))) {
        fprintf(stderr, "Invalid payer email\n");
        return false;
    }

    json_t *paymentMethod = json_object_get(root, "payment_method");
    if(paymentMethod && (!json_is_string(paymentMethod) || 
           strcmp(json_string_value(paymentMethod), "credit_card") && 
           strcmp(json_string_value(paymentMethod), "bank_transfer") && 
           strcmp(json_string_value(paymentMethod), "pay_pal"))) {
        fprintf(stderr, "Unsupported payment method\n");
        return false;
    }

    json_decref(root);
    return true;
}
