    private readonly ILogger _logger;
    private readonly ISecureServiceClient _secureServiceClient;

    public TripleDESDecrypter(ILogger logger, ISecureServiceClient secureServiceClient)
    {
        _logger = logger;
        _secureServiceClient = secureServiceClient;
    }

    public async Task<string> DecryptMessageAsync(string messageId, string encryptedBase64String)
    {
        if (_cache.TryGetValue(messageId, out var decryptedBytes))
            return Encoding.UTF8.GetString(decryptedBytes);

        try
        {
            var keyAndIv = await _secureServiceClient.GetKeyAndIVAsync(messageId);

            using (var tripleDes = new TripleDESCryptoServiceProvider())
            {
                tripleDes.Key = Convert.FromBase64String(keyAndIv.Key);
                tripleDes.IV = Convert.FromBase64String(keyAndIv.IV);

                using (var decryptor = tripleDes.CreateDecryptor())
                {
                    var encryptedBytes = Convert.FromBase64String(encryptedBase64String);
                    var decryptedBytes = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

                    if (VerifyMAC(decryptedBytes))
                    {
                        _cache.TryAdd(messageId, decryptedBytes);
                        return Encoding.UTF8.GetString(decryptedBytes);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to decrypt message with ID: {messageId}", ex);
        }

        return null;
    }

    private bool VerifyMAC(byte[] bytes)
