```csharp
using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class UUIDGenerator
{
    private ConcurrentDictionary<string, string> existingIdentifiers = new ConcurrentDictionary<string, string>();

    public async Task<ConcurrentDictionary<string, string>> GenerateUUIDsAsync(IEnumerable<string> inputs)
    {
        var results = new ConcurrentDictionary<string, string>();

        await Parallel.ForEachAsync(inputs, async (input, _) =>
        {
            try
            {
                using (var md5 = MD5.Create())
                {
                    byte[] inputBytes = Encoding.ASCII.GetBytes(input);
                    byte[] hashBytes = md5.ComputeHash(inputBytes);

                    string uuid = new Guid(hashBytes).ToString();

                    if (existingIdentifiers.TryAdd(uuid, input))
                        results.TryAdd(input, uuid);
                }
            }
            catch (Exception ex)
            {
                // Log the exception here
                Console.WriteLine($"Error processing input: {input}. Exception: {ex}");
            }
        });

        return results;
    }

    public bool ValidateUUIDs(ConcurrentDictionary<string, string> identifiers)
    {
        foreach (var identifier in identifiers.Keys)
        {
            if (!existingIdentifiers.ContainsKey(identifier))
                return false;
        }

        return true;
    }
}
```
This class uses the MD5 hash of each input string to generate a UUID, which is then stored in a `ConcurrentDictionary` for efficient concurrency and memory management. The `GenerateUUIDsAsync` method processes inputs in parallel using `Parallel.ForEachAsync`, ensuring optimal resource utilization on multi-core systems.

The `ValidateUUIDs` method checks if all the provided UUIDs exist in the existing identifiers dictionary. If any of them do not exist, it returns false indicating that some or all of the inputs did not produce a unique identifier. 

Please note that this is a basic implementation and does not include logging configuration or custom sinks. You would need to add these features yourself based on your specific requirements. Also, error handling in this code is very basic and only logs exceptions to the console. Depending on your needs, you may want to implement more robust error handling, such as by throwing exceptions or using a logging framework.
