```csharp
using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.Win32.SafeHandles;
using System.IO.MemoryMappedFiles;

public class CustomDataStructure { /* ... */ }

public static async Task<CustomDataStructure> LoadAndDeserializeAsync(string filePath, string checksum)
{
    try
    {
        using (var mmf = MemoryMappedFile.CreateFromFile(filePath))
        {
            var formatter = new BinaryFormatter();

            // Use memory-mapped file access to deserialize data
            using (var stream = mmf.CreateViewStream())
            {
                return await Task.Run(() => (CustomDataStructure)formatter.Deserialize(stream));
            }
        }
    }
    catch (IOException ex)
    {
        Console.WriteLine("I/O Exception: " + ex.Message);
        throw;
    }
    catch (UnauthorizedAccessException ex)
    {
        Console.WriteLine("Access Exception: " + ex.Message);
        throw;
    }
}

public static bool VerifyChecksum(string filePath, string expectedChecksum)
{
    using (var sha256 = SHA256.Create())
    {
        using (var stream = File.OpenRead(filePath))
        {
            var hashBytes = sha256.ComputeHash(stream);
            var actualChecksum = BitConverter.ToString(hashBytes).Replace("-", string.Empty);

            return expectedChecksum == actualChecksum;
        }
    }
}
```

This code uses memory-mapped file access to deserialize data, which can be faster than reading the entire file into memory and then deserializing it. However, this approach requires that the entire file fit into physical memory, which could lead to out of memory errors for large files. 

MemoryMappedFiles class in .NET Core does not support async operations, so we use Task.Run to offload the work to a background thread. This is necessary because deserialization can be CPU-intensive and should not block the main UI thread.

The checksum verification uses SHA256 hash algorithm which is widely used for data integrity checking. It calculates the hash of the file content and compares it with the expected checksum. If they match, we consider the file as valid.

This code does not include any error handling or versioning mechanism to support future changes while maintaining backward compatibility. This would require a more complex design that includes a version field in the serialized data structure, and logic to handle different versions of the data format during deserialization. 

