const fetch = require('node-fetch');
const NodeCache = require("node-cache");
const myCache = new NodeCache();

async function getWeatherData(location) {
    const cacheKey = `weather_${location}`;
    let weatherData = myCache.get(cacheKey);

    if (weatherData === undefined) {
        try {
            const response = await fetch(`http://api.openweathermap.org/data/2.5/weather?q=${location}&appid=YOUR_API_KEY`);

            if (!response.ok) throw new Error('Network response was not ok');

            weatherData = await response.json();

            // Cache data for 10 minutes
            myCache.set(cacheKey, weatherData, 600);
        } catch (error) {
            console.log("Error: ", error);
            return null;
        }
    }

    return formatWeatherData(weatherData);
}

function formatWeatherData(data) {
    // Format data as needed for display in the user interface
    const formattedData = {
        location: data.name,
        temperature: data.main.temp,
        humidity: data.main.humidity,
        description: data.weather[0].description
    };

    return formattedData;
}
```
