            _ => printlnNonThreadSafe(CString::new("Invalid task type").unwrap().into_raw()),
        }
    }

    for task in tasks {
        let handle = task.await.unwrap();
        if let Err(e) = handle.await {
            log_message(&format_err("Task failed", e));
        } else {
            log_message("Task completed successfully");
        }
    }

    Ok(())
}
```
