use std::env;
use uuid::Uuid;
use log::{info, error};
use std::fs::create_dir;
use std::path::PathBuf;

pub fn initialize_directory(uuid: Uuid) -> Result<(), String> {
    let env_var = "WORKSPACE_DIR";

    // Check if environment variable is already set
    match env::var(env_var) {
        Ok(dir) => {
            info(&format![ "Environment variable {} is already set to: {}", env_var, dir]);
            return Ok(());
        },
        Err(_) => {
            // If not, create a new directory and update the environment variable
            let workspace_dir = PathBuf::from(uuid.to_string());

            match create_dir(&workspace_dir) {
                Ok(_) => {
                    info![ "Created directory: {}", &workspace_dir];

                    // Update environment variable
                    env::set_var(env_var, workspace_dir.to_str().unwrap());
                    info![ "Updated environment variable {} to: {}", env_var, dir];
                },
                Err(e) => {
                    error![ "Failed to create directory: {}", e];
                    return Err(format![ "Failed to create directory: {}", e]);
                }
            };
        }
    };

    Ok(())
}
```

