```python
import json
import logging
from typing import Callable, Dict, Any

class DataModelFactory:
    def __init__(self):
        self._factories = {}  # type: Dict[int, Callable[[Dict[str, Any]], 'DataModel']]

    def register_factory(self, id_: int, factory: Callable[[Dict[str, Any]], 'DataModel']) -> None:
        self._factories[id_] = factory

    def unregister_factory(self, id_: int) -> None:
        if id_ in self._factories:
            del self._factories[id_]

    def create_model(self, id_: int, json_str: str) -> 'DataModel':
        if id_ not in self._factories:
            raise ValueError('No factory registered for ID {}'.format(id_))

        try:
            data = json.loads(json_str)
        except json.JSONDecodeError as e:
            logging.error('Failed to decode JSON: %s', str(e))
            raise ValueError('Invalid JSON') from e

        return self._factories[id_](data)
```

This is a basic implementation of the factory pattern in Python, where each data model type has its own factory function. The `create_model` method takes an ID and a JSON string as input, validates the JSON, and uses the corresponding factory to create an instance of the data model. 

