typedef struct {
    ENB_RRC_CONFIG_DCI_T dci;
    RRC_CONNECTION_RECONFIGURATION_TAG tag;
} LTE_ENB_RRC_MESSAGE_T;

// Custom memory pool allocator
#define POOL_SIZE 1024 * 1024 // 1MB
static char memory_pool[POOL_SIZE];
static size_t offset = 0;

void* my_malloc(size_t size) {
    if (offset + size > POOL_SIZE) {
        return NULL; // out of memory
    }
    void* ptr = &memory_pool[offset];
    offset += size;
    return ptr;
}

void my_free(void* ptr) {
    // No-op for this simple allocator
}

// Dynamic array with thread safety
typedef struct {
    LTE_ENB_RRC_MESSAGE_T** data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} Array;

void init_array(Array* arr) {
    arr->data = NULL;
    arr->size = 0;
    arr->capacity = 0;
    pthread_mutex_init(&arr->lock, NULL);
}

void add_element(Array* arr, LTE_ENB_RRC_MESSAGE_T* element) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size == arr->capacity) {
        // Reallocate with more space
        size_t new_capacity = arr->capacity == 0 ? 1 : arr->capacity * 2;
        LTE_ENB_RRC_MESSAGE_T** new_data = my_malloc(new_capacity * sizeof(LTE_ENB_RRC_MESSAGE_T*));

        // Copy old data to new array
        memcpy(new_data, arr->data, arr->size * sizeof(LTE_ENB_RRC_MESSAGE_T*));

        // Free old data
        my_free(arr->data);

        arr->data = new_data;
        arr->capacity = new_capacity;
    }

    arr->data[arr->size] = element;
    arr->size++;

    pthread_mutex_unlock(&arr->lock);
}

// Similar functions for remove_element and iterate_elements
```

