#include <random>
#include <map>
#include <string>
#include <mutex>
#include <stdexcept>

class RandomGenerator {
public:
    virtual ~RandomGenerator() = default;
    virtual int getInt(int min, int max) = 0;
    virtual double getDouble(double min, double max) = 0;
};

template<typename GeneratorType>
class ConcreteRandomGenerator : public RandomGenerator {
public:
    explicit ConcreteRandomGenerator(unsigned seed = std::random_device{}()) 
        : generator_(seed) {}

    int getInt(int min, int max) override {
        std::lock_guard<std::mutex> lock(mutex_);
        return std::uniform_int_distribution<int>{min, max}(generator_);
    }

    double getDouble(double min, double max) override {
        std::lock_guard<std::mutex> lock(mutex_);
        return std::uniform_real_distribution<double>{min, max}(generator_);
    }
private:
    GeneratorType generator_;
    std::mutex mutex_;
};

class RandomGeneratorFactory {
public:
    static RandomGenerator* create(const std::string& name) {
        if (name == "mt19937") {
            return new ConcreteRandomGenerator<std::mt19937>();
        } else if (/* other generators */) {
            // ...
        } else {
            throw std::runtime_error("Unsupported generator: " + name);
        }
    }
};
```

For the C interface, you would need to use a dynamic library loading mechanism like `dlopen` on Unix-like systems or `LoadLibrary` on Windows. Here's an example of how it might look:

```c
#include <stdlib.h>
#include <dlfcn.h>

typedef struct RandomGenerator {
    void* handle;
    int (*getInt)(void*, int, int);
    double (*getDouble)(void*, double, double);
} RandomGenerator;

RandomGenerator* create_generator(const char* name) {
    RandomGenerator* generator = malloc(sizeof(RandomGenerator));
    if (!generator) return NULL;

    // Load the library.
    generator->handle = dlopen("librandomgenerators.so", RTLD_LAZY);
    if (!generator->handle) {
        free(generator);
        return NULL;
    }

    // Get function pointers to the methods we need.
    *(void**)&generator->getInt = dlsym(generator->handle, "create_int");
    *(void**)&generator->getDouble = dlsym(generator->handle, "create_double");

    if (!generator->getInt || !generator->getDouble) {
        dlclose(generator->handle);
        free(generator);
        return NULL;
    }

    return generator;
}
```

