using System.Threading.Tasks;

public class DynamicValueGenerator
{
    private double minValue, maxValue;
    private int precision;
    private string logFilePath = "log.txt"; // default log file path
    private Dictionary<string, bool> externalDataSourceCache = new Dictionary<string, bool>();

    public DynamicValueGenerator(double minValue, double maxValue, int precision)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
        this.precision = precision;
    }

    private async Task<bool> ValidateExternalDataSource()
    {
        string cacheKey = $"{minValue}-{maxValue}";

        if (externalDataSourceCache.ContainsKey(cacheKey))
            return externalDataSourceCache[cacheKey];

        try
        {
            // Simulate an asynchronous call to the external data source
            bool isValid = await Task.Run(() => minValue < maxValue); 

            externalDataSourceCache[cacheKey] = isValid;
            return isValid;
        }
        catch (Exception ex)
        {
            File.AppendAllText(logFilePath, $"Error validating range: {ex.Message}\n");
            return false;
        }
    }

    public async Task<double> GenerateRandomDouble(bool inclusive = true)
    {
        if (await ValidateExternalDataSource())
        {
            Random random = new Random();

            double range = maxValue - minValue;
            double sample = random.NextDouble();
            double scaled = sample * range;
            double shifted = inclusive ? scaled + minValue : scaled + minValue + 1; 

            return Math.Round(shifted, precision);
        }

        File.AppendAllText(logFilePath, $"Invalid range: {minValue} - {maxValue}\n");
        return double.NaN;
    }

    // Similar methods for GenerateRandomInt and GenerateRandomMatrix can be implemented here...

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}] Precision: {precision}";
    }
}
