```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} aes256gcm_context;

aes256gcm_context* init_cipher(const char *passphrase, const char *config_file) {
    // Load configuration from file (not implemented here)
    int pbkdf2_iterations = 10000;
    int iv_length = EVP_CIPHER_iv_length(EVP_aes_256_gcm());

    aes256gcm_context *ctx = malloc(sizeof(aes256gcm_context));
    if (!ctx) {
        return NULL;
    }

    // Generate random IV
    RAND_bytes(ctx->iv, iv_length);

    // Derive key from passphrase using PBKDF2
    PKCS5_PBKDF2_HMAC_SHA1(passphrase, strlen(passphrase), ctx->iv, iv_length, pbkdf2_iterations, EVP_MAX_KEY_LENGTH, ctx->key);

    // Initialize cipher context
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->key, ctx->iv)) {
        free(ctx);
        return NULL;
    }

    return ctx;
}

int encrypt(aes256gcm_context *ctx, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    // Encrypt data
    int len;
    if (!EVP_EncryptUpdate(ctx->ctx, ciphertext, &len, plaintext, plaintext_len)) {
        return -1;
    }

    // Finalize encryption and get tag
    unsigned char tag[EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_GET_TAG, 16, ciphertext + len))];
    if (!EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_TAG, sizeof(tag), tag)) {
        return -1;
    }

    return len + sizeof(tag);
}

int decrypt(aes256gcm_context *ctx, const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    // Get tag from end of ciphertext
    unsigned char tag[EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_GET_TAG, 16, &ciphertext[ciphertext_len - 16])];

    // Set expected tag
    if (!EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_TAG, sizeof(tag), tag)) {
        return -1;
    }

    // Decrypt data
    int len;
    if (!EVP_DecryptUpdate(ctx->ctx, plaintext, &len, ciphertext, ciphertext_len - 16)) {
        return -1;
    }

    return len;
}

void cleanup_cipher(aes256gcm_context *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
```
This code does not handle memory allocation limits or securely cleaning up the cipher context when it is no longer needed. It also doesn't include error handling and logging, which would require more complex code to implement correctly. 

