const { exec } = require('child_process');

function executeCommand(command) {
    return new Promise((resolve, reject) => {
        exec(command, (error, stdout, stderr) => {
            if (error) {
                console.warn(error);
                resolve({ status: 0 });
            } else {
                console.log(stdout);
                resolve({ status: 1 });
            }
        });
    });
}
```
2. **C Backend Service**: Use a C library like libcurl to make HTTP requests to an external API for command execution metadata retrieval and implement caching to improve performance. You can use pthreads in C to run the shell command asynchronously without blocking the JavaScript execution. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

void *executeCommand(void *command) {
    char *cmd = (char *)command;
    int status = system(cmd);

    // Return a status code without blocking the JavaScript execution
    return (void*)(status == 0 ? 1 : 0);
}

int main() {
    pthread_t thread;
    char *command = "ls -l";

    if(pthread_create(&thread, NULL, executeCommand, command)) {
        fprintf(stderr, "Error creating thread\n");
        return 1;
    }

    // Wait for the C function to finish executing asynchronously without blocking the JavaScript execution
    void *status;
    pthread_join(thread, &status);

    printf("Status: %ld\n", (long)status);

    return 0;
}
```
3. **Integration**: Use a RESTful API to communicate between the frontend and backend components. You can use Express.js in Node.js for this purpose.

```javascript
