public:
    MOCK_METHOD1(FindVmUuidFromMetadataIp, bool(const std::string&));
};

class SandeshClient {
private:
    boost::asio::io_service io_service_;
    tcp::resolver resolver_{io_service_};
    InterfaceTable* interface_table_;
    int successful_requests_ = 0;
    int proxy_sessions_ = 0;
    int internal_errors_ = 0;

public:
    SandeshClient(InterfaceTable* interface_table) : interface_table_(interface_table) {}

    void SendGetRequest(const std::string& server, const std::string& path) {
        try {
            tcp::resolver::query query(server, "http");
            tcp::resolver::iterator endpoint_iterator = resolver_.resolve(query);

            tcp::socket socket(io_service_);
            boost::asio::connect(socket, endpoint_iterator);

            boost::asio::streambuf request;
            std::ostream request_stream(&request);
            request_stream << "GET " << path << " HTTP/1.0\r\n";
            request_stream << "Host: " << server << "\r\n";
            request_stream << "Accept: */*\r\n";
            request_stream << "Connection: close\r\n\r\n";

            boost::asio::write(socket, request);

            boost::asio::streambuf response;
            boost::asio::read_until(socket, response, "\r\n");

            std::istream response_stream(&response);
            std::string http_version;
            response_stream >> http_version;

            unsigned int status_code;
            response_stream >> status_code;

            std::string status_message;
            std::getline(response_stream, status_message);

            if (!response_stream || http_version.substr(0, 5) != "HTTP/") {
                internal_errors_++;
                return;
            }

            if (status_code != 200) {
                successful_requests_++;
                proxy_sessions_++;
                return;
            }
        } catch (std::exception& e) {
            internal_errors_++;
            std::cerr << "Exception: " << e.what() << "\n";
        }
    }
};

