    if (arr->array == NULL) {
        free(arr);
        return NULL;
    }

    pthread_rwlock_init(&arr->lock, NULL);
    return arr;
}

void destroy_dynamic_array(DynamicArray* arr) {
    if (arr != NULL) {
        free(arr->array);
        pthread_rwlock_destroy(&arr->lock);
        free(arr);
    }
}

int add_element(DynamicArray* arr, LTE_ENB_RRC_MESSAGE_T element) {
    if (arr == NULL) return -1;

    pthread_rwlock_wrlock(&arr->lock);
    if (arr->size >= arr->capacity) {
        size_t newCapacity = arr->capacity * 2;
        LTE_ENB_RRC_MESSAGE_T* newArray = realloc(arr->array, newCapacity * sizeof(LTE_ENB_RRC_MESSAGE_T));
        if (newArray == NULL) {
            pthread_rwlock_unlock(&arr->lock);
            return -1;
        }

        arr->capacity = newCapacity;
        arr->array = newArray;
    }

    arr->array[arr->size++] = element;
    pthread_rwlock_unlock(&arr->lock);
    return 0;
}

