int findMax(int* array, long size) {
    if (size == 0 || array == NULL) return -1; // handle edge case

    int max = array[0];
    for (long i = 1; i < size; ++i) {
        if (array[i] > max) max = array[i];
    }
    return max;
}

int initialize(long* offsets, long offsetSize, int* keys, long keySize, Record** records, long recordSize, 
               int minVal, int maxVal, void (*logError)(const char*)) {

    if (offsetSize == 0 || keys == NULL || recordSize == 0 || records == NULL) return 0; // handle edge case

    srand(time(NULL)); // seed the random number generator

    *records = malloc(recordSize * sizeof(Record));
    if (*records == NULL) {
        logError("Memory allocation failed for records");
        return 0;
    }

    for (long i = 0; i < recordSize; ++i) {
        (*records)[i].value = rand() % (maxVal - minVal + 1) + minVal; // generate random number within range
    }

    return 1;
}

int main(void) {
    long offsetsSize = 5, keysSize = 5, recordsSize = 5;
    int minVal = 0, maxVal = 100;
    long* offsets = malloc(offsetsSize * sizeof(long));
    int* keys = malloc(keysSize * sizeof(int));
