typedef struct DynamicArray {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t size;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    if (da == NULL) return NULL;

    pthread_mutex_init(&da->lock, NULL);
    da->capacity = initial_capacity;
    da->array = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (da->array == NULL) {
        free(da);
        return NULL;
    }

    da->size = 0;
    return da;
}

void destroy_dynamic_array(DynamicArray* da) {
    pthread_mutex_destroy(&da->lock);
    free(da->array);
    free(da);
}

int resize_dynamic_array(DynamicArray* da, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array == NULL) return -1;

    da->array = new_array;
    da->capacity = new_capacity;
    return 0;
}

int add_element(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&da->lock);

    if (da->size == da->capacity) {
        size_t new_capacity = da->capacity * 2;
        if (new_capacity > 10000) new_capacity = 10000;

        int resized = resize_dynamic_array(da, new_capacity);
        if (resized != 0) {
            pthread_mutex_unlock(&da->lock);
            return -1;
        }
    }

    da->array[da->size] = element;
    da->size++;

    pthread_mutex_unlock(&da->lock);
    return 0;
}

int get_element(DynamicArray* da, size_t index, NFAPI_CRC_INDICATION_PDU_T* element) {
    if (index >= da->size) return -1;

    pthread_mutex_lock(&da->lock);
    memcpy(element, &da->array[index], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&da->lock);

    return 0;
}

size_t get_size(DynamicArray* da) {
    size_t size;
    pthread_mutex_lock(&da->lock);
    size = da->size;
    pthread_mutex_unlock(&da->lock);

    return size;
}
```
