    DataStore* store = malloc(sizeof(DataStore));
    if (!store) {
        // Log error and exit
        return NULL;
    }

    store->offsets = calloc(size, sizeof(long));
    store->keys = malloc(size * sizeof(int));
    store->records = malloc(size * sizeof(Record*));
    if (!store->offsets || !store->keys || !store->records) {
        // Log error and free allocated memory
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        store->records[i] = malloc(sizeof(Record));
        if (!store->records[i]) {
            // Log error and free allocated memory
            return NULL;
        }

        store->keys[i] = i;
        store->offsets[i] = i * sizeof(Record);
        store->records[i]->value = randomInRange(0, 100); // Set a random value in the range [0, 100]
    }

    store->size = size;
    pthread_mutex_init(&store->lock, NULL);
    return store;
}

void destroyDataStore(DataStore* store) {
