['Here's an example of how you might implement this in C using POSIX threads for concurrency and a simple logging framework. This is a complex task and would require a lot more code to fully implement all the requirements. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <arpa/inet.h>

#define MAX_IP 1000
#define DEFAULT_MAX_PROCESS 500

typedef struct {
    char *ip;
    int valid;
} IPAddress;

int totalValid = 0, totalInvalid = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void logInfo(const char* message) {
    pthread_mutex_lock(&lock);
    printf("[INFO]: %s\n", message);
    pthread_mutex_unlock(&lock);
}

void logError(const char* message) {
    pthread_mutex_lock(&lock);
    fprintf(stderr, "[ERROR]: %s\n", message);
    pthread_mutex_unlock(&lock);
}

int validateIPAddress(char *ipAddress) {
    struct sockaddr_in sa;
    return inet_pton(AF_INET, ipAddress, &(sa.sin_addr)) != 0;
}

void* processIPAddresses(void *arg) {
    IPAddress *address = (IPAddress*) arg;
    if (validateIPAddress(address->ip)) {
        pthread_mutex_lock(&lock);
        totalValid++;
        pthread_mutex_unlock(&lock);
        address->valid = 1;
    } else {
        pthread_mutex_lock(&lock);
        totalInvalid++;
        pthread_mutex_unlock(&lock);
        address->valid = 0;
    }
    return NULL;
}

void readAndProcessIPAddresses(char *filename, int maxToProcess) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        logError("Failed to open file.");
        exit(EXIT_FAILURE);
    }

    IPAddress addresses[MAX_IP];
    int count = 0;
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file) != NULL && count < maxToProcess) {
        buffer[strcspn(buffer, "\n")] = '\0';  // Remove trailing newline
        addresses[count].ip = strdup(buffer);
        pthread_t thread;
        if (pthread_create(&thread, NULL, processIPAddresses, &addresses[count]) != 0) {
            logError("Failed to create thread.");
            exit(EXIT_FAILURE);
        }
        count++;
    }

    for (int i = 0; i < count; i++) {
        pthread_join(addresses[i].valid, NULL);
    }

    fclose(file);
}

int main(int argc, char *argv[]) {
    int maxToProcess = DEFAULT_MAX_PROCESS;
    if (argc > 1) {
        maxToProcess = atoi(argv[1]);
        if (maxToProcess <= 0 || maxToProcess > MAX_IP) {
            logError("Invalid number of IP addresses to process.");
            exit(EXIT_FAILURE);
        }
    }

    readAndProcessIPAddresses("config.txt", maxToProcess);

    printf("Total valid: %d\n", totalValid);
    printf("Total invalid: %d\n", totalInvalid);

    return 0;
}
```
This code reads IP addresses from a file, validates them in separate threads, and counts the number of valid and invalid ones. It uses a simple logging framework that locks a mutex before printing to ensure thread safety. The maximum number of IP addresses to process is passed as a command-line argument with a default value of 500.
']

