    a->array = (LTE_ENB_RRC_MESSAGE_T *)malloc(initialSize * sizeof(LTE_ENB_RRC_MESSAGE_T));
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL);
}

void insertDynamicArray(DynamicArray *a, LTE_ENB_RRC_MESSAGE_T element) {
    pthread_mutex_lock(&a->lock);
    if (a->used == a->size) {
        a->size *= 2;
        a->array = (LTE_ENB_RRC_MESSAGE_T *)realloc(a->array, a->size * sizeof(LTE_ENB_RRC_MESSAGE_T));
    }
    a->array[a->used++] = element;
    pthread_mutex_unlock(&a->lock);
}

void deleteDynamicArray(DynamicArray *a, int cellId) {
    pthread_mutex_lock(&a->lock);
    for (int i = 0; i < a->used; ++i) {
        if (a->array[i].cellId == cellId) {
            a->array[i] = a->array[--a->used];
            break;
        }
    }
    pthread_mutex_unlock(&a->lock);
}

void iterateDynamicArray(DynamicArray *a, void (*func)(LTE_ENB_RRC_MESSAGE_T)) {
    pthread_mutex_lock(&a->lock);
    for (int i = 0; i < a->used; ++i) {
        func(a->array[i]);
    }
    pthread_mutex_unlock(&a->lock);
}
```
