// Implement the function
int adjust_file_descriptor_limit(pid_t pid, int new_limit) {
    struct rlimit limit;

    // Get the current resource limits for the process
    if (getrlimit(RLIMIT_NOFILE, &limit) == -1) {
        perror("Failed to get file descriptor limit");
        return -1;
    }

    printf("Current file descriptor limit: %ld\n", limit.rlim_cur);

    // Adjust the resource limits for the process
    limit.rlim_cur = new_limit;
    if (setrlimit(RLIMIT_NOFILE, &limit) == -1) {
        perror("Failed to set file descriptor limit");
        return -1;
    }

    printf("New file descriptor limit: %ld\n", limit.rlim_cur);

    return 0;
}
```
