['Here is an example of how you might implement this in C using pthreads for thread safety, and logging with syslog. This code does not include all the features mentioned as it would be quite complex and lengthy to explain fully here. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <syslog.h>

typedef struct {
    int id;
    long value;
    double data;
} Record;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    Record* records;
} Dataset;

Dataset* create_dataset(size_t initial_capacity) {
    Dataset* dataset = malloc(sizeof(Dataset));
    if (dataset == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for dataset");
        return NULL;
    }

    pthread_mutex_init(&dataset->lock, NULL);
    dataset->capacity = initial_capacity;
    dataset->size = 0;
    dataset->records = malloc(initial_capacity * sizeof(Record));
    if (dataset->records == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for records");
        free(dataset);
        return NULL;
    }

    return dataset;
}

void destroy_dataset(Dataset* dataset) {
    pthread_mutex_destroy(&dataset->lock);
    free(dataset->records);
    free(dataset);
}

int add_record(Dataset* dataset, Record record) {
    pthread_mutex_lock(&dataset->lock);

    if (dataset->size == dataset->capacity) {
        size_t new_capacity = dataset->capacity * 2;
        Record* new_records = realloc(dataset->records, new_capacity * sizeof(Record));
        if (new_records == NULL) {
            syslog(LOG_ERR, "Failed to resize records array");
            pthread_mutex_unlock(&dataset->lock);
            return -1;
        }

        dataset->capacity = new_capacity;
        dataset->records = new_records;
    }

    dataset->records[dataset->size++] = record;

    pthread_mutex_unlock(&dataset->lock);
    return 0;
}
```
This code creates a simple dynamic array data structure with thread safety. It uses `pthread_mutex_t` to ensure that only one thread can modify the dataset at a time, and it uses `realloc` to resize the records array when necessary. The function `add_record` is used to add new records to the dataset, which automatically resizes the array if necessary.

