void allocate_and_initialize(long **offsets, int **keys, record **records) {
    srand((unsigned int) time(NULL)); // seed the random number generator

    *offsets = malloc(10000 * sizeof(long));
    assert(*offsets != NULL);

    *keys = malloc(10000 * sizeof(int));
    assert(*keys != NULL);

    *records = malloc(10000 * sizeof(record));
    assert(*records != NULL);

    for (int i = 0; i < 10000; ++i) {
        (*offsets)[i] = rand(); // initialize offset with random value

        (*keys)[i] = rand() % 1000; // initialize key within a specified range

        (*records)[i].value = rand() % 1000; // initialize record's integer field with a random value within a specified range
    }
}
```

