```c
#include <stdlib.h>
#include <time.h>
#include <assert.h>

typedef struct {
    int value;
} record;

int initialize_records(size_t size, int range_start, int range_end, int* keys, long* offsets, record** records) {
    assert(keys != NULL);
    assert(offsets != NULL);
    assert(records != NULL);

    if (size == 0) {
        return 1; // Success status for zero-sized arrays
    }

    *keys = malloc(sizeof(int) * size);
    *offsets = malloc(sizeof(long) * size);
    *records = malloc(sizeof(record) * size);

    if (*keys == NULL || *offsets == NULL || *records == NULL) {
        // Log error message for memory allocation failures
        log_error("Memory allocation failed");

        // Free any previously allocated memory before returning a failure status
        free(*keys);
        free(*offsets);
        free(*records);

        return 0; // Failure status for memory allocation failures
    }

    srand(time(NULL)); // Seed the random number generator with the current time

    for (size_t i = 0; i < size; ++i) {
        (*keys)[i] = rand() % range_end + range_start;
        (*offsets)[i] = rand() % LONG_MAX;

        record rec;
        rec.value = (*keys)[i];
        (*records)[i] = rec;
    }

    // Verify the integrity of the data
    for (size_t i = 0; i < size; ++i) {
        if ((*records)[i].value < range_start || (*records)[i].value > range_end) {
            log_error("Record value out of range");

            // Free all allocated memory before returning a failure status
            free(*keys);
            free(*offsets);
            free(*records);

            return 0; // Failure status for data integrity issues
        }
    }

    return 1; // Success status indicating all operations were completed correctly
}
```

This function uses dynamic memory allocation to create the arrays of keys, offsets, and records. It also verifies the integrity of the data after initialization. If any discrepancies are found, it logs an error message and frees all allocated memory before returning a failure status. 

