public class MemoryManager {
    private static final Logger logger = Logger.getLogger(MemoryManager.class);
    private static final int MAX_MEMORY_USAGE = 75; // 75% of available system memory
    private static final String CONFIGURATION_FILE = "config.txt";
    private static final Random RANDOM = new SecureRandom();

    private long[] longArray;
    private int[] keyArray;
    private Record[] recordArray;
    private ExecutorService executorService;
    private PersistenceService persistenceService;

    public MemoryManager(int arraySize, int minValue, int maxValue) {
        deleteConfigurationFile();

        longArray = new long[arraySize];
        keyArray = new int[arraySize];
        recordArray = new Record[arraySize];

        for (int i = 0; i < arraySize; i++) {
            keyArray[i] = RANDOM.nextInt();
            recordArray[i] = new Record(RANDOM.nextInt((maxValue - minValue) + 1) + minValue);
        }

        executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        persistenceService = new PersistenceService();
    }

    private void deleteConfigurationFile() {
        try {
            Files.deleteIfExists(Paths.get(CONFIGURATION_FILE));
        } catch (IOException e) {
            logger.error("Failed to delete configuration file", e);
        }
    }

    public boolean initialize() {
        if (!isMemoryAvailable()) {
            logger.warn("Insufficient memory");
            return false;
        }

        try {
            persistenceService.initialize();

            for (int i = 0; i < recordArray.length; i++) {
                final int index = i;
                executorService.submit(() -> {
                    if (!recordArray[index].isInitialized()) {
                        recordArray[index].initialize();
                    }
                });
            }

            return true;
        } catch (Exception e) {
            logger.error("Failed to initialize", e);
            return false;
        }
    }

    private boolean isMemoryAvailable() {
        long maxMemory = Runtime.getRuntime().maxMemory();
        long usedMemory = (Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory());

        if ((usedMemory * 100 / maxMemory) > MAX_MEMORY_USAGE) {
            System.gc(); // Trigger garbage collection
            return false;
        }

        return true;
    }

    private class Record {
        private int value;

        public Record(int value) {
            this.value = value;
        }

        public boolean isInitialized() {
            return value != 0;
        }

        public void initialize() {
            // Initialize record with random value within specified range
        }
    }

    private class PersistenceService {
