        record->value = rand() % 10000; // set value within specified range
        if (record->value > max_value) {
            max_value = record->value;
        }

        pthread_mutex_lock(&nicbs[id].lock);
        nicbs[id].records = g_slist_append(nicbs[id].records, record);
        pthread_mutex_unlock(&nicbs[id].lock);
    }

    return NULL;
}

void verifyData() {
    for (int i = 0; i < 10000; i++) {
        pthread_mutex_lock(&nicbs[i].lock);

        for (GSList* node = nicbs[i].records; node != NULL; node = g_slist_next(node)) {
            Record* record = (Record*)node->data;

            if (record->value < 0 || record->value > 10000) {
                g_mutex_lock(&log_lock);
                g_critical("Data corruption detected in NICB %d: value out of range", i);
                g_mutex_unlock(&log_lock);
            }
        }

        pthread_mutex_unlock(&nicbs[i].lock);
    }
}
