#include <math.h>

typedef struct point {
    float x;
    float y;
} Point;

typedef struct transaction {
    double value;
    char* key;
    Point* location;
} Transaction;

double roundToTwoDecimalPlaces(float number) {
    return roundf(number * 100) / 100;
}

int initializeTransactionSystem(Point** points, size_t pointCount, char** keys, size_t keyCount, Transaction** transactions, size_t transactionCount) {
    if (pointCount == 0 || keyCount == 0 || transactionCount == 0) {
        return -1; // Edge case: zero-sized arrays
    }

    *points = malloc(sizeof(Point) * pointCount);
    if (*points == NULL) {
        return -2; // Memory allocation failure for points
    }

    *keys = malloc(sizeof(char*) * keyCount);
    if (*keys == NULL) {
        free(*points);
        return -3; // Memory allocation failure for keys
    }

    *transactions = calloc(transactionCount, sizeof(Transaction));
    if (*transactions == NULL) {
        free(*points);
        free(*keys);
        return -4; // Memory allocation failure for transactions
    }

    // Initialize points and calculate transaction values
    for (size_t i = 0; i < pointCount; ++i) {
        (*points)[i].x = rand() % 100;
        (*points)[i].y = rand() % 100;

        if (i < transactionCount) {
            (*transactions)[i].location = &(*points)[i];
            (*transactions)[i].value = roundToTwoDecimalPlaces(((*points)[i].x + (*points)[i].y) / 2);
        }
    }

    // Initialize keys
    for (size_t i = 0; i < keyCount; ++i) {
        if (i < transactionCount) {
            (*keys)[i] = malloc(16);
            if ((*keys)[i] == NULL) {
                free(*points);
                free(*keys);
                free(*transactions);
                return -5; // Memory allocation failure for key strings
            }

            sprintf((*keys)[i], "Key%zu", i + 1);
            (*transactions)[i].key = (*keys)[i];
        }
    }

    // Verify data integrity
    for (size_t i = 0; i < transactionCount; ++i) {
        double expectedValue = roundToTwoDecimalPlaces(((*points)[i].x + (*points)[i].y) / 2);

        if ((*transactions)[i].value != expectedValue || strcmp((*transactions)[i].key, (*keys)[i - transactionCount]) != 0) {
            return -6; // Data integrity check failed
        }
    }

    return 0; // Success
}
```
