#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/camellia.h>

typedef struct {
    int value;
} Record;

void generate_random_string(char *str, size_t size) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJK...";
    if (size) {
        --size;
        for (size_t n = 0; n < size; n++) {
            int key = rand() % (int) (sizeof charset - 1);
            str[n] = charset[key];
        }
        str[size] = '\0';
    }
}

char *hash_password(const char *password, const EVP_MD* (*get_digest)(void)) {
    EVP_MD_CTX *mdctx;
    const EVP_MD *md;
    unsigned char md_value[EVP_MAX_MD_SIZE];
    unsigned int md_len;

    OpenSSL_add_all_digests();
    md = get_digest();

    if(!(mdctx = EVP_MD_CTX_new())) {
        printf("Error creating hash context\n");
        return NULL;
    }

    if(1 != EVP_DigestInit_ex(mdctx, md, NULL)) {
        printf("Error initializing hash context\n");
        return NULL;
    }

    if(1 != EVP_DigestUpdate(mdctx, password, strlen(password))) {
        printf("Error updating hash with data\n");
        return NULL;
    }

    if((EVP_DigestFinal_ex(mdctx, md_value, &md_len)) <= 0) {
        printf("Error finalizing hash\n");
        return NULL;
    }

    EVP_MD_CTX_free(mdctx);

    char *hash = malloc((md_len*2)+1);
    for (int i = 0; i < md_len; ++i) {
        sprintf(&hash[i*2], "%02x", md_value[i]);
    }

    return hash;
}

Record *create_records(size_t count, int min, int max) {
    Record *records = malloc(count * sizeof(Record));
    if (!records) {
        printf("Error allocating memory for records\n");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        records[i].value = min + rand() % (( max + 1 ) - min);
    }

    return records;
}
```
