['Here is a basic implementation of the task in C language. This code does not include all the features mentioned in the problem statement due to its complexity, but it provides a good starting point for further development. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    float x;
    float y;
} Point;

typedef struct Transaction {
    double value;
    char* key;
    Point point;
    struct Transaction *next;
} Transaction;

Transaction *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

double roundToTwo(float n) {
    return (double)((int)(n*100 + 0.5))/100;
}

void addTransaction(char *key, Point point) {
    Transaction *newNode = malloc(sizeof(Transaction));

    if(!newNode) {
        printf("Memory allocation failed\n");
        return;
    }

    newNode->value = roundToTwo((point.x + point.y)/2);
    newNode->key = malloc(strlen(key) + 1);

    if(!newNode->key) {
        printf("Memory allocation failed\n");
        free(newNode);
        return;
    }

    strcpy(newNode->key, key);
    newNode->point = point;
    newNode->next = NULL;

    pthread_mutex_lock(&lock);

    if(!head) {
        head = newNode;
    } else {
        Transaction *last = head;

        while(last->next) {
            last = last->next;
        }

        last->next = newNode;
    }

    pthread_mutex_unlock(&lock);
}

void freeTransactions() {
    Transaction *current = head, *temp = NULL;

    while(current) {
        temp = current;
        current = current->next;

        free(temp->key);
        free(temp);
    }
}

int main() {
    atexit(freeTransactions);

    Point p1 = {3.5, 4.2};
    addTransaction("Key1", p1);

    Point p2 = {7.8, 9.0};
    addTransaction("Key2", p2);

    return 0;
}
```
This code creates a linked list of transactions with each transaction containing a key (string), value (calculated as average of point coordinates rounded to two decimal places) and a point structure. It uses a mutex for thread-safe operations. The `addTransaction` function adds new transactions at the end of the list, while `freeTransactions` frees all allocated memory upon program termination.
