typedef struct file_stats {
    time_t timestamp;
    off_t size;
    off_t offset;
} file_stats;

void *safeMalloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

file_stats* createFileStats() {
    file_stats *fs = safeMalloc(sizeof(file_stats));
    fs->timestamp = time(NULL);
    fs->size = 0;
    fs->offset = -1;
    return fs;
}

void processDirectoryContents(char* dirPath) {
    FILE *dirStream = popen("ls", "r");
    if (dirStream == NULL) {
        perror("popen failed");
        exit(EXIT_FAILURE);
    }

    char line[256];
    while (fgets(line, sizeof(line), dirStream)) {
        // Remove newline character from the end of the line
        line[strcspn(line, "\n")] = 0;

        struct stat st;
        if (stat(line, &st) == 0) {
            file_stats *fs = createFileStats();
            fs->size = st.st_size;

            // Process the file...
        } else {
            fprintf(stderr, "Failed to get stats for %s\n", line);
        }
    }

    pclose(dirStream);
}
