// Global variables for the dynamic array and its size
NFAPI_CRC_INDICATION_PDU_T* array = NULL;
size_t arraySize = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add an element to the dynamic array
void addElement(NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&mutex);
    ++arraySize;
    array = realloc(array, sizeof(*array) * arraySize);
    if (array == NULL) {
        --arraySize;
        return;
    }
    array[arraySize - 1] = element;
    pthread_mutex_unlock(&mutex);
}

// Function to remove an element from the dynamic array
void removeElement(int index) {
    if (index < 0 || index >= arraySize) return;
    pthread_mutex_lock(&mutex);
    --arraySize;
    for (size_t i = index; i < arraySize; ++i) {
        array[i] = array[i + 1];
    }
    array = realloc(array, sizeof(*array) * arraySize);
    pthread_mutex_unlock(&mutex);
}

// Function to iterate over the dynamic array
void iterateArray() {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < arraySize; ++i) {
        // Perform operation on each element
    }
    pthread_mutex_unlock(&mutex);
}

// Function to serialize the dynamic array to a file
void serializeArray(const char* filename) {
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) return;

    pthread_mutex_lock(&mutex);
    fwrite(&arraySize, sizeof(arraySize), 1, fp);
    fwrite(array, sizeof(*array), arraySize, fp);
    pthread_mutex_unlock(&mutex);

    fclose(fp);
}

// Function to deserialize the dynamic array from a file
void deserializeArray(const char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) return;

    pthread_mutex_lock(&mutex);
    size_t newSize;
    fread(&newSize, sizeof(newSize), 1, fp);
    array = realloc(array, sizeof(*array) * newSize);
    if (array == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }
    fread(array, sizeof(*array), newSize, fp);
    arraySize = newSize;
    pthread_mutex_unlock(&mutex);

    fclose(fp);
}
```
