```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <random>
#include <memory>

class Strategy {
public:
    virtual void execute() = 0;
};

class Context {
private:
    std::unique_ptr<Strategy> strategy_;
    int cooldownDuration_;
    std::chrono::time_point<std::chrono::system_clock> lastExecutionTime_;
public:
    Context(int cooldown = 10) : cooldownDuration_(cooldown), lastExecutionTime_(std::chrono::system_clock::now()) {}

    void setStrategy(std::unique_ptr<Strategy> strategy) {
        strategy_ = std::move(strategy);
    }

    bool execute() {
        auto currentTime = std::chrono::system_clock::now();
        if((currentTime - lastExecutionTime_) > std::chrono::seconds(cooldownDuration_)) {
            strategy_->execute();
            lastExecutionTime_ = currentTime;
            return true;
        }
        return false;
    }
};

void executeStrategy() {
    Context context;

    std::vector<int> params;
    int param;
    while(std::cin >> param) {
        params.push_back(param);
    }

    if(!std::cin.eof() && !std::cin.good()) {
        std::cerr << "Error reading parameters" << std::endl;
        return;
    }

    // Here you would select the strategy based on params and context state
    // For example:
    try {
        if(params.size() > 0 && params[0] % 2 == 0) {
            context.setStrategy(std::make_unique<EvenNumberStrategy>());
        } else {
            context.setStrategy(std::make_unique<OddNumberStrategy>());
        }
    } catch (const std::bad_alloc& e) {
        std::cerr << "Memory allocation failed: " << e.what() << std::endl;
        return;
    }

    if(context.execute()) {
        std::cout << "Strategy executed successfully" << std::endl;
    } else {
        std::cerr << "Cooldown not finished yet" << std::endl;
    }
}
```
This code uses the Strategy design pattern to select and execute a strategy based on some conditions. The `Context` class manages the cooldown period between executions of the selected strategy. 

