void add_message(DynamicArray *arr, LTE_ENB_RRC_MESSAGE_T message) {
    pthread_mutex_lock(&arr->lock);

    if (arr->count == arr->capacity) {
        // Resize the array when it's full
        arr->capacity *= 2;
        arr->messages = realloc(arr->messages, arr->capacity * sizeof(LTE_ENB_RRC_MESSAGE_T));
    }

    arr->messages[arr->count++] = message;

    pthread_mutex_unlock(&arr->lock);
}

