    private static int _memoryAllocations = 0;

    public void loadAndInitializeData(string filePath, Random random)
    {
        try
        {
            using (var stream = File.OpenRead(filePath))
            {
                var formatter = new BinaryFormatter();

                Interlocked.Increment(ref _memoryAllocations);
                var data = (CustomDataStructure)formatter.Deserialize(stream);

                // Verify the integrity of the data
                if (!data.IsValid())
                {
                    throw new Exception("Invalid data");
                }
            }
        }
        catch (Exception ex)
        {
            LogError(ex, "Failed to load and initialize data from file: " + filePath);

            // Deallocate memory if allocation failed or there was an error during deserialization
            Interlocked.Decrement(ref _memoryAllocations);
        }
    }

    private void LogError(Exception ex, string message)
    {
        // Interface with external logging system to log errors
        Console.WriteLine("Error: " + message + ". Exception: " + ex.Message);
    }
}
