['Here's a basic implementation in C using pthread for thread safety, glib for hash table and linked list, and sqlite3 for persistence. This is a complex task that requires careful design and testing to ensure correctness and efficiency. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <glib.h>
#include <sqlite3.h>

typedef struct {
    int value;
} Record;

GHashTable* hash_table;
GList* linked_list;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init(int num_records, int min_value, int max_value, unsigned int seed) {
    srand(seed);

    hash_table = g_hash_table_new(g_direct_hash, g_direct_equal);
    linked_list = NULL;

    for (int i = 0; i < num_records; ++i) {
        int key = rand();
        Record* record = malloc(sizeof(Record));
        record->value = min_value + rand() % (max_value - min_value + 1);

        pthread_mutex_lock(&lock);
        linked_list = g_list_prepend(linked_list, record);
        g_hash_table_insert(hash_table, GINT_TO_POINTER(key), record);
        pthread_mutex_unlock(&lock);
    }
}

void save_to_db() {
    sqlite3* db;
    if (sqlite3_open("data.db", &db) != SQLITE_OK) {
        // handle error
        return;
    }

    char* err_msg = 0;
    const char* sql = "CREATE TABLE Records(Key INT PRIMARY KEY, Value INT);";
    if (sqlite3_exec(db, sql, 0, 0, &err_msg) != SQLITE_OK ){
        // handle error
    }

    sqlite3_stmt* stmt;
    sql = "INSERT INTO Records VALUES(?, ?);";
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, 0) != SQLITE_OK) {
        // handle error
    }

    pthread_mutex_lock(&lock);
    for (GList* node = linked_list; node != NULL; node = node->next) {
        Record* record = node->data;
        int key = GPOINTER_TO_INT(g_hash_table_find(hash_table, &record));

        sqlite3_bind_int(stmt, 1, key);
        sqlite3_bind_int(stmt, 2, record->value);

        if (sqlite3_step(stmt) != SQLITE_DONE) {
            // handle error
        }

        sqlite3_reset(stmt);
    }
    pthread_mutex_unlock(&lock);

    sqlite3_finalize(stmt);
    sqlite3_close(db);
}
```
