CustomDataStructure** allocateMemory(int size, int defaultInt, const char* defaultString, float defaultFloat) {
    if (size > 10000 || size < 1) {
        printf("Invalid array size. It should be between 1 and 10000.\n");
        return NULL;
    }

    CustomDataStructure** array = malloc(size * sizeof(CustomDataStructure*));
    if (array == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        CustomDataStructure* data = malloc(sizeof(CustomDataStructure));
        if (data == NULL) {
            printf("Memory allocation failed.\n");
            // Free previously allocated memory and return NULL
            for (int j = 0; j < i; ++j) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }

        data->integer = defaultInt;
        strncpy(data->string, defaultString, sizeof(data->string));
        data->floating_point = defaultFloat;

        array[i] = data;
    }

    return array;
}

void deallocateMemory(CustomDataStructure** array, int size) {
    if (array == NULL) {
        printf("Array is null. Nothing to free.\n");
        return;
    }

    for (int i = 0; i < size; ++i) {
        if (array[i] != NULL) {
            free(array[i]);
        }
    }

    free(array);
}
