    int connectionID;
    std::time_t lastActivityTimestamp;
    bool statusFlag; // true for active, false for idle
};

class ServiceManager {
private:
    std::vector<TCPConnection> connections;
    std::mutex mtx;
public:
    void addConnection(int connectionID) {
        std::lock_guard<std::mutex> lock(mtx);
        TCPConnection conn{connectionID, std::time(nullptr), true};
        connections.push_back(conn);
    }

    bool removeConnection(int connectionID) {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto it = connections.begin(); it != connections.end(); ++it) {
            if (it->connectionID == connectionID) {
                connections.erase(it);
                return true;
            }
        }
        return false;
    }

    void exportConnectionsToFile(const std::string& filename) {
        std::lock_guard<std::mutex> lock(mtx);
        std::ofstream file(filename);
        if (file.is_open()) {
            for (auto &conn : connections) {
                file << conn.connectionID << "," 
                     << conn.lastActivityTimestamp << "," 
                     << (conn.statusFlag ? "active" : "idle") << std::endl;
            }
            file.close();
        } else {
            throw std::runtime_error("Unable to open file");
        }
    }
};
```
