['Here is an example of how you might implement this in C using POSIX threads for concurrency and asynchronous I/O. This code does not include the full application pipeline, but it provides a starting point for integrating DNS resolution and MD5 hashing into your larger application. 

```c
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <netdb.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <openssl/md5.h>
#include <pthread.h>
#include <unistd.h>

// Error codes
#define DNS_ERROR 1
#define FILE_OPEN_ERROR 2
#define MD5_HASH_ERROR 3

typedef struct {
    char *hostname;
    u_char ip[4];
} host_info;

void *get_ip(void *arg) {
    host_info *hi = (host_info *) arg;
    struct hostent *he;

    if ((he = gethostbyname(hi->hostname)) == NULL) {
        herror("gethostbyname");
        return (void *)DNS_ERROR;
    }

    memcpy(hi->ip, htonl(*((uint32_t *)he->h_addr_list[0])), 4);

    return NULL;
}

int get_md5_hash(const char *filename, unsigned char *digest) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("fopen");
        return FILE_OPEN_ERROR;
    }

    MD5_CTX context;
    int bytes;
    unsigned char data[1024];

    if(!MD5_Init(&context)) {
        fprintf(stderr, "Failed to initialize MD5\n");
        return MD5_HASH_ERROR;
    }

    while((bytes = fread(data, 1, sizeof(data), file))) {
        if(!MD5_Update(&context, data, bytes)) {
            fprintf(stderr, "Failed to update MD5\n");
            return MD5_HASH_ERROR;
        }
    }

    if (ferror(file)) {
        perror("fread");
        return FILE_OPEN_ERROR;
    }

    if(!MD5_Final(digest, &context)) {
        fprintf(stderr, "Failed to finalize MD5\n");
        return MD5_HASH_ERROR;
    }

    fclose(file);

    return 0;
}

int main() {
    pthread_t thread;
    host_info hi = {"www.example.com", {0}};

    if (pthread_create(&thread, NULL, get_ip, &hi)) {
        perror("pthread_create");
        return errno;
    }

    unsigned char digest[MD5_DIGEST_LENGTH];
    int error = get_md5_hash("/path/to/file", digest);

    if (error) {
        fprintf(stderr, "Failed to calculate MD5 hash\n");
        return error;
    }

    pthread_join(thread, NULL);

    printf("IP: %d.%d.%d.%d\n", hi.ip[0], hi.ip[1], hi.ip[2], hi.ip[3]);
    printf("MD5 hash: ");
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        printf("%02x", digest[i]);
    }
    printf("\n");

    return 0;
}
```
This code uses POSIX threads to perform DNS resolution in a separate thread. It also calculates the MD5 hash of a file using OpenSSL's MD5 functions, which are designed for high performance and memory efficiency. The main function creates a thread to resolve the IP address of a hostname, then it calculates the MD5 hash of a file. Finally, it prints out the resolved IP address and the MD5 hash.
']

