```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_LINE 1024
#define DNS_SERVER "8.8.8.8" // Google's public DNS server

typedef struct {
    char *hostname;
} ThreadArgs;

void *processFile(void *args) {
    ThreadArgs *threadArgs = (ThreadArgs *) args;
    FILE *file = fopen(threadArgs->hostname, "r");

    if (!file) {
        printf("Failed to open file: %s\n", threadArgs->hostname);
        return NULL;
    }

    char line[MAX_LINE];
    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, ",");
        int i = 0;
        double sum = 0.0;
        while (token != NULL) {
            if (i >= 2) { // we only care about the last two fields
                sum += atof(token);
            }

            token = strtok(NULL, ",");
            i++;
        }

        printf("Average of last two fields: %f\n", sum / 2.0);
    }

    fclose(file);
    return NULL;
}

int main() {
    char *hostnames[] = {"file1.txt", "file2.txt"}; // replace with your actual file names
    int numFiles = sizeof(hostnames) / sizeof(char*);

    pthread_t threads[numFiles];
    ThreadArgs threadArgs[numFiles];

    for (int i = 0; i < numFiles; i++) {
        threadArgs[i].hostname = hostnames[i];

        if (pthread_create(&threads[i], NULL, processFile, &threadArgs[i]) != 0) {
            printf("Failed to create thread for file: %s\n", hostnames[i]);
            return 1;
        }
    }

    for (int i = 0; i < numFiles; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
