} Transaction;

typedef struct Node {
    Transaction *transaction;
    struct Node *left, *right;
} Node;

Node* newNode(Transaction *transaction) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->transaction = transaction;
    node->left = node->right = NULL;
    return node;
}

Node* insert(Node* node, Transaction *transaction) {
    if (node == NULL) return newNode(transaction);
    if (difftime(transaction->timestamp, node->transaction->timestamp) < 0)
        node->left = insert(node->left, transaction);
    else if (difftime(transaction->timestamp, node->transaction->timestamp) > 0)
        node->right = insert(node->right, transaction);
    return node;
}

pthread_mutex_t lock;
Node* root = NULL;

void addTransaction(Transaction *transaction) {
    pthread_mutex_lock(&lock);
    if (root == NULL) root = newNode(transaction);
    else insert(root, transaction);
    pthread_mutex_unlock(&lock);
}

