typedef struct {
    int value;
} Record;

typedef struct Node {
    int key;
    long offset;
    Record record;
    time_t timestamp[10];
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addRecord(int key, Record record) {
    pthread_mutex_lock(&lock);

    Node* node = malloc(sizeof(Node));
    assert(node != NULL);

    node->key = key;
    node->record = record;
    node->next = head;
    head = node;

    pthread_mutex_unlock(&lock);
}

void removeRecord(int key) {
    pthread_mutex_lock(&lock);

    Node* prev = NULL;
    for (Node* curr = head; curr != NULL; prev = curr, curr = curr->next) {
        if (curr->key == key) {
            if (prev != NULL) {
                prev->next = curr->next;
            } else {
                head = curr->next;
            }

            free(curr);
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void updateRecord(int key, Record record) {
    pthread_mutex_lock(&lock);

    for (Node* curr = head; curr != NULL; curr = curr->next) {
        if (curr->key == key) {
            curr->record = record;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}
