#include <stdatomic.h>

typedef struct {
    int value;
} record;

atomic_int maxValue = ATOMIC_VAR_INIT(0);
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* readInputAndFindMax(void *arg) {
    FILE *file = fopen("input.txt", "r");
    if (file == NULL) {
        printf("Failed to open input file\n");
        return NULL;
    }

    int value;
    while (fscanf(file, "%d", &value) == 1) {
        pthread_mutex_lock(&mutex);
        if (value > atomic_load(&maxValue)) {
            atomic_store(&maxValue, value);
        }
        pthread_mutex_unlock(&mutex);
    }

    fclose(file);
    return NULL;
}

int main() {
    srand(1234567890); // seed for reproducibility

    long *offsets = malloc(sizeof(long) * 1000); // allocate memory for offsets
    if (offsets == NULL) {
        printf("Failed to allocate memory for offsets\n");
        return -1;
    }

    int *keys = calloc(1000, sizeof(int)); // allocate and initialize keys
    if (keys == NULL) {
        printf("Failed to allocate memory for keys\n");
        free(offsets);
        return -1;
    }

    record *records = malloc(sizeof(record) * 1000); // allocate records
    if (records == NULL) {
        printf("Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return -1;
    }

    for (int i = 0; i < 1000; ++i) { // initialize records with random integers
        records[i].value = rand();
    }

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, readInputAndFindMax, NULL);
    pthread_create(&thread2, NULL, readInputAndFindMax, NULL);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    FILE *file = fopen("output.txt", "w"); // write results to file
    if (file == NULL) {
        printf("Failed to create output file\n");
        free(offsets);
        free(keys);
        free(records);
        return -1;
    }

    fprintf(file, "Max value: %d\n", atomic_load(&maxValue));
    fclose(file);

    free(offsets); // release memory
    free(keys);
    free(records);

    return 0;
}
