#include <sys/stat.h>

// Define a struct to hold file information and data
typedef struct {
    char *filename;
    // Add other necessary fields
} FileInfo;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void *processFile(void *arg) {
    FileInfo *fileInfo = (FileInfo *) arg;

    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&lock);

    // Process file here...

    // Unlock the mutex when done
    pthread_mutex_unlock(&lock);
}

int main(int argc, char *argv[]) {
    DIR *dir;
    struct dirent *ent;
    FileInfo fileInfo;
    pthread_t threads[10]; // Adjust the size as needed

    if ((dir = opendir ("/path/to/directory")) != NULL) {
        int i = 0;

        while ((ent = readdir(dir)) != NULL) {
            fileInfo.filename = ent->d_name;

            // Create a new thread to process the file
            pthread_create(&threads[i], NULL, processFile, (void *) &fileInfo);

            i++;
        }

        closedir(dir);
    } else {
        perror("Could not open directory");
        return EXIT_FAILURE;
    }

    // Wait for all threads to finish
    for (int j = 0; j < i; j++) {
        pthread_join(threads[j], NULL);
    }

    return 0;
}
```
