['Here is an example of how you might implement such a function in C using a dynamic memory pool approach. This code does not include thread safety measures, as implementing them correctly can be complex and depends heavily on the specifics of your use case. 

```c
#include <stdlib.h>
#include <string.h>
#include <assert.h>

typedef struct {
    int value;
    long* key_ptr;
} Record;

typedef struct MemoryPool {
    size_t capacity;
    size_t size;
    void* memory;
} MemoryPool;

MemoryPool create_memory_pool(size_t initial_capacity) {
    MemoryPool pool = {0, 0, malloc(initial_capacity)};
    if (pool.memory == NULL) {
        fprintf(stderr, "Failed to allocate memory for the memory pool.\n");
        exit(EXIT_FAILURE);
    }
    return pool;
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    if (pool->size + size > pool->capacity) {
        // Double the capacity when we run out of space.
        pool->capacity = pool->capacity == 0 ? 1 : pool->capacity * 2;
        pool->memory = realloc(pool->memory, pool->capacity);
        if (pool->memory == NULL) {
            fprintf(stderr, "Failed to allocate memory for the memory pool.\n");
            exit(EXIT_FAILURE);
        }
    }
    void* ptr = (char*)pool->memory + pool->size;
    pool->size += size;
    return ptr;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->memory);
    pool->capacity = 0;
    pool->size = 0;
    pool->memory = NULL;
}

Record* initialize_records(int num_records, int value_range, MemoryPool* key_pool, MemoryPool* record_pool) {
    long* keys = allocate_from_pool(key_pool, sizeof(long) * num_records);
    Record* records = allocate_from_pool(record_pool, sizeof(Record) * num_records);

    for (int i = 0; i < num_records; ++i) {
        keys[i] = rand() % value_range;  // Assuming a positive range.
        records[i].value = rand() % value_range;
        records[i].key_ptr = &keys[i];
    }

    return records;
}
```
This code creates a `MemoryPool` struct to manage memory allocation and deallocation, with an initial capacity. The `allocate_from_pool` function allocates memory from the pool, doubling its size if necessary. 

The `initialize_records` function generates random keys and values for each record, ensuring that each record points to its corresponding key in the keys array. It uses the provided memory pools for both keys and records, which can significantly reduce the number of allocations and deallocations compared to using separate arrays or individual malloc/free calls.

Please note that this is a simplified example and does not include thread safety measures or error handling for all possible scenarios. For a production-level solution, you would need to consider these aspects in detail based on your specific requirements.
