typedef struct {
    int value;
    long* offset;
    int* key;
} record;

long* offsets = NULL;
int* keys = NULL;
record* records = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
atomic_int count = 0;

void allocateMemory(size_t size) {
    offsets = malloc(size * sizeof(long));
    keys = malloc(size * sizeof(int));
    records = calloc(size, sizeof(record));
}

void initializeArrays(size_t size, int min, int max) {
    srand((unsigned int) time(NULL));

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand() % (max - min + 1) + min;
        keys[i] = rand() % (max - min + 1) + min;

        record rec = { .value = rand() % (max - min + 1) + min, 
                      .offset = &offsets[i], 
                      .key = &keys[i] };

        records[i] = rec;
    }
}

void printRecords(size_t size) {
    for (size_t i = 0; i < size; ++i) {
        printf("Record %zu: Value=%d, Offset=%ld, Key=%d\n", 
               i, records[i].value, *records[i].offset, *records[i].key);
    }
}

void* threadFunction(void* arg) {
    pthread_mutex_lock(&mutex);
    ++count;
    printf("Thread %ld started. Count: %d\n", (long)arg, count);
    pthread_mutex_unlock(&mutex);

    // Perform some work here...

    pthread_mutex_lock(&mutex);
    --count;
    printf("Thread %ld finished. Count: %d\n", (long)arg, count);
    pthread_mutex_unlock(&mutex);

    return NULL;
}
```
This code provides a basic structure for allocating and initializing the arrays in a thread-safe manner. It also includes a simple print function for debugging purposes. The `threadFunction` is an example of how you might use this code in a multithreaded context, with each thread incrementing and decrementing a counter to simulate work being done.
