```c
#include <stdio.h>
#include <pthread.h>
#include <string.h>
#include <stdlib.h>

typedef struct Logger {
    char name[256];
    FILE *file;
    int log_level;
    pthread_mutex_t lock;
} Logger;

Logger loggers[10] = {0};
int logger_count = 0;
pthread_mutex_t count_lock = PTHREAD_MUTEX_INITIALIZER;

void create_logger(char *name, int log_level, char *filepath) {
    pthread_mutex_lock(&count_lock);
    if (logger_count >= 10) {
        printf("Maximum logger limit reached. Cannot create new logger.\n");
        return;
    }
    Logger *newLogger = &loggers[logger_count++];
    strncpy(newLogger->name, name, sizeof(newLogger->name));
    newLogger->file = fopen(filepath, "a+");
    if (newLogger->file == NULL) {
        printf("Failed to open file for logger %s\n", name);
        return;
    }
    newLogger->log_level = log_level;
    pthread_mutex_init(&(newLogger->lock), NULL);
    pthread_mutex_unlock(&count_lock);
}

void log_message(char *logger_name, int level, char *message) {
    for (int i = 0; i < logger_count; ++i) {
        if (strcmp(loggers[i].name, logger_name) == 0) {
            pthread_mutex_lock(&(loggers[i].lock));
            if (level >= loggers[i].log_level) {
                fprintf(loggers[i].file, "%s\n", message);
                fflush(loggers[i].file);
            }
            pthread_mutex_unlock(&(loggers[i].lock));
            break;
        }
    }
}

void list_loggers() {
    printf("Currently active loggers:\n");
    for (int i = 0; i < logger_count; ++i) {
        printf("%s, level: %d\n", loggers[i].name, loggers[i].log_level);
    }
}
```
This code creates a struct to represent a Logger and an array of 10 such loggers. The `create_logger` function is used to create new loggers with unique names and specified log levels. The `log_message` function logs messages from the appropriate logger, ensuring thread safety by locking the mutex before writing to the file.

