['Here is an example of how you might implement this task using C with pthreads library for thread safety. This code does not include error handling or edge cases as they would make the code too complex to be presented here, but it should give you a good starting point. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    int key;
    long offset;
} Record;

atomic_int recordCount = 0;
Record* records = NULL;
char* statusFlags = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initializeRecords(size_t count) {
    pthread_mutex_lock(&lock);

    if (records == NULL) {
        records = malloc(count * sizeof(Record));
        statusFlags = calloc(count, sizeof(char));

        for (int i = 0; i < count; ++i) {
            int key;

            do {
                key = rand() % INT_MAX;  // Generate a random unique integer.
            } while (!atomic_compare_exchange_strong(&recordCount, &key, recordCount + 1));

            records[i].key = key;
            records[i].offset = 0L;
            statusFlags[i] = 1;  // Mark as initialized successfully.
        }
    } else {
        size_t oldSize = atomic_load(&recordCount);

        if (count > oldSize) {
            records = realloc(records, count * sizeof(Record));
            statusFlags = realloc(statusFlags, count * sizeof(char));

            for (int i = oldSize; i < count; ++i) {
                int key;

                do {
                    key = rand() % INT_MAX;  // Generate a random unique integer.
                } while (!atomic_compare_exchange_strong(&recordCount, &key, recordCount + 1));

                records[i].key = key;
                records[i].offset = 0L;
                statusFlags[i] = 1;  // Mark as initialized successfully.
            }
        } else {
            for (int i = count; i < oldSize; ++i) {
                statusFlags[i] = 0;  // Mark as deinitialized.
            }

            atomic_store(&recordCount, count);
        }
    }

    pthread_mutex_unlock(&lock);
}
```
This code uses a mutex to ensure that only one thread can modify the records and statusFlags arrays at a time. It also uses an atomic integer to keep track of the number of initialized records, which is updated using compare-and-swap operations for thread safety. 

Please note that this is just a simple example and does not include all the considerations you mentioned such as error handling, edge cases, memory management under high loads etc. You would need to add these features according to your specific requirements.
']

