    int id;
    char* name;
    char* email;
    Role** roles;
    int roleCount;
} User;

User** users = NULL;
int userCount = 0;
int nextId = 1;

void addUser(char* name, char* email) {
    if (userCount >= 10000000) {
        printf("Maximum number of users reached.\n");
        return;
    }

    User* user = malloc(sizeof(User));
    user->id = nextId++;
    user->name = strdup(name);
    user->email = strdup(email);
    user->roles = NULL;
    user->roleCount = 0;

    users = realloc(users, sizeof(User*) * (userCount + 1));
    users[userCount++] = user;
}

void updateUser(int id, char* name, char* email) {
    for (int i = 0; i < userCount; ++i) {
        if (users[i]->id == id) {
            free(users[i]->name);
            free(users[i]->email);
            users[i]->name = strdup(name);
            users[i]->email = strdup(email);
            return;
        }
    }

    printf("User not found.\n");
}

User* getUserById(int id) {
    for (int i = 0; i < userCount; ++i) {
        if (users[i]->id == id) {
            return users[i];
        }
    }

    printf("User not found.\n");
    return NULL;
}
```
