#include <pthread.h>

typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    size_t max_records;
    size_t num_records;
    record* records;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* create_record_manager(size_t max_records) {
    RecordManager* manager = malloc(sizeof(RecordManager));
    if (manager == NULL) return NULL;

    manager->max_records = max_records;
    manager->num_records = 0;
    manager->records = calloc(max_records, sizeof(record));
    if (manager->records == NULL) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_record_manager(RecordManager* manager) {
    if (manager != NULL) {
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_record(RecordManager* manager, record rec) {
    pthread_mutex_lock(&manager->lock);

    if (manager->num_records >= manager->max_records) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: no space left
    }

    manager->records[manager->num_records++] = rec;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int delete_record(RecordManager* manager, size_t index) {
    pthread_mutex_lock(&manager->lock);

    if (index >= manager->num_records) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: invalid index
    }

    manager->records[index] = manager->records[--manager->num_records];

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}
```
