        return;
    }

    newNode->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data.RNTI = RNTI;
    newNode->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    newNode->next = head;
    head = newNode;
}

void freeList() {
    Node* current = head;
    while(current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    head = NULL;
}
