```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    time_t lastAccessedTime;
    unsigned long accessCount;
    char modificationFlags;
} Metadata;

typedef struct {
    long offset;
    int key;
    Record record;
    Metadata metadata;
} RecordStructure;

typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t count;
    RecordStructure *records;
} DynamicArray;

DynamicArray* createDynamicArray(size_t initialCapacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (array == NULL) return NULL;

    array->capacity = initialCapacity;
    array->count = 0;
    array->records = calloc(initialCapacity, sizeof(RecordStructure));
    if (array->records == NULL) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroyDynamicArray(DynamicArray *array) {
    if (array != NULL) {
        pthread_mutex_destroy(&array->mutex);
        free(array->records);
        free(array);
    }
}

int addRecord(DynamicArray *array, RecordStructure record) {
    pthread_mutex_lock(&array->mutex);

    if (array->count == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        RecordStructure *newRecords = realloc(array->records, newCapacity * sizeof(RecordStructure));
        if (newRecords == NULL) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }

        array->capacity = newCapacity;
        array->records = newRecords;
    }

    array->records[array->count++] = record;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}
```
This code provides a basic dynamic array with thread safety. It uses a mutex to ensure that only one thread can modify the array at a time, and it doubles the capacity of the array whenever it is full to minimize memory allocation calls. Note that this is a very simplified version and does not include all the features mentioned above such as logging, configuration management, garbage collection, extensibility, or external dependencies.
