            continue;
        }

        // Reallocate memory for users.
        UserRecord* tempUsers = realloc(users, (numUsers + 1) * sizeof(UserRecord));
        if (!tempUsers) {
            printf("Memory allocation failed.\n");
            free(users);
            return 0;
        }
        users = tempUsers;

        // Initialize user record.
        UserRecord* newUser = &users[numUsers];
        newUser->userID = strdup(userID);
        if (!newUser->userID) {
            printf("Memory allocation failed.\n");
            free(users);
            return 0;
        }
        newUser->count = 1;

        numUsers++;
    }

    // Initialize metadata.
    metadata = malloc(numUsers * sizeof(Metadata));
    if (!metadata) {
        printf("Memory allocation failed.\n");
        free(users);
        return 0;
    }

    for (int i = 0; i < numUsers; i++) {
        metadata[i].timestamp = time(NULL);
        metadata[i].size = 0; // Compute size of associated files.
        metadata[i].record = &users[i];
    }

    char filePath[256];
    size_t totalSize = 0;

    while (fgets(filePath, sizeof(filePath), stdin) != NULL) {
        // Remove trailing newline character.
        filePath[strcspn(filePath, "\n")] = 0;

        if (!validateFilePath(filePath)) {
            printf("Invalid file path: %s\n", filePath);
            continue;
        }

        size_t fileSize = getFileSize(filePath);
        totalSize += fileSize;
    }

    // Update metadata with total size.
    for (int i = 0; i < numUsers; i++) {
        metadata[i].size = totalSize;
    }

    printf("Memory allocation and initialization successful.\n");
    return 1;
}
