["Here is an example of how you might implement such a function in C using pthreads for thread safety and a simple garbage collection mechanism. This code does not include error handling for memory allocation failures or initialization errors, nor does it provide a mechanism to verify the integrity of the data after initialization. It also doesn't support adding new metadata fields in the future with minimal code changes.

```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int id;
    double value;
    time_t lastAccessedTime;
    unsigned long accessCount;
    bool modificationFlags;
    void* customAttributes;
} Record;

typedef struct {
    Record** records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

Record* createRecord(int id, double value) {
    Record* record = malloc(sizeof(Record));
    if (record == NULL) return NULL;

    record->id = id;
    record->value = value;
    record->lastAccessedTime = 0;
    record->accessCount = 0;
    record->modificationFlags = false;
    record->customAttributes = NULL;

    return record;
}

void addRecord(int id, double value) {
    Record* record = createRecord(id, value);
    if (record == NULL) return;

    pthread_mutex_lock(&pool.lock);

    if (pool.count >= pool.capacity) {
        size_t newCapacity = pool.capacity == 0 ? 1 : pool.capacity * 2;
        Record** newRecords = realloc(pool.records, sizeof(Record*) * newCapacity);

        if (newRecords == NULL) {
            free(record);
            pthread_mutex_unlock(&pool.lock);
            return;
        }

        pool.records = newRecords;
        pool.capacity = newCapacity;
    }

    pool.records[pool.count++] = record;

    pthread_mutex_unlock(&pool.lock);
}

void freeRecord(Record* record) {
    if (record == NULL) return;

    // Free custom attributes here...

    free(record);
}

void garbageCollect() {
    pthread_mutex_lock(&pool.lock);

    for (size_t i = 0; i < pool.count; ++i) {
        if (pool.records[i]->accessCount == 0 && !pool.records[i]->modificationFlags) {
            freeRecord(pool.records[i]);

            // Shift all records after the freed one to fill the gap...
            for (size_t j = i; j < pool.count - 1; ++j) {
                pool.records[j] = pool.records[j + 1];
            }

            --pool.count;
        }
    }

    pthread_mutex_unlock(&pool.lock);
}
```
This code is a simple example and does not cover all the requirements you specified, but it should give you a good starting point for building your own solution. It's important to note that C is a low-level language and doesn't have many built-in features for handling complex data structures or managing memory in an efficient way. Therefore, implementing such functionality can be quite challenging and requires careful design and testing.
