        // or it could involve creating a new data structure and copying all elements over.
    }

    store->offsets[store->count] = offset;
    store->keys[store->count] = key;
    store->records[store->count] = rec;
    store->count++;

    pthread_mutex_unlock(&store->lock);
}

record* get_record(data_store* store, int key) {
    pthread_mutex_lock(&store->lock);

    for (size_t i = 0; i < store->count; ++i) {
        if (store->keys[i] == key) {
            record* rec = store->records[i];

            pthread_mutex_unlock(&store->lock);
            return rec;
        }
    }

    pthread_mutex_unlock(&store->lock);
    return NULL;
}

void delete_record(data_store* store, int key) {
    pthread_mutex_lock(&store->lock);

    for (size_t i = 0; i < store->count; ++i) {
        if (store->keys[i] == key) {
            free(store->records[i]);

            // Shift all elements after the deleted one to fill the gap.
            for (size_t j = i; j < store->count - 1; ++j) {
                store->offsets[j] = store->offsets[j + 1];
                store->keys[j] = store->keys[j + 1];
                store->records[j] = store->records[j + 1];
            }

            store->count--;
            break;
        }
    }

    pthread_mutex_unlock(&store->lock);
}

void clear_data_store(data_store* store) {
    pthread_mutex_lock(&store->lock);

    for (size_t i = 0; i < store->count; ++i) {
        free(store->records[i]);
    }

    free(store->offsets);
    free(store->keys);
    free(store->records);
    pthread_mutex_destroy(&store->lock);
    free(store);
}
