#include <iostream>
#include <forward_list>
#include <vector>
#include <random>
#include <algorithm>
#include <cstdlib>

struct Record {
    int value;
};

void fillUniqueKeys(int* keys, size_t count) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(-1000, 1000);

    for (size_t i = 0; i < count; ++i) {
        int value;
        do {
            value = dis(gen);
        } while (std::find(keys, keys + i, value) != keys + i);

        keys[i] = value;
    }
}

void fillRecords(Record* records, size_t count) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(-1000, 1000);

    for (size_t i = 0; i < count; ++i) {
        int value = dis(gen);

        // Ensure uniqueness of the record values
        bool uniqueValueFound = false;
        while (!uniqueValueFound) {
            uniqueValueFound = true;

            for (size_t j = 0; j < i; ++j) {
                if (records[j].value == value) {
                    value = dis(gen); // Regenerate the value
                    uniqueValueFound = false;
                    break;
                }
            }
        }

        records[i].value = value;
    }
}

bool validateKeys(int* keys, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (keys[i] < -1000 || keys[i] > 1000) {
            return false; // Key out of range
        }

        for (size_t j = i + 1; j < count; ++j) {
            if (keys[i] == keys[j]) {
                return false; // Duplicate key found
            }
        }
    }

    return true;
}

void insertAfter(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert) {
