    if (pos != list.end()) {
        list.insert_after(pos, toInsert);
    } else {
        // Handle case where target is not found in the list
    }
}

int main() {
    const size_t count = 100;

    int* keys = new (std::nothrow) int[count];
    if (!keys) {
        std::cerr << "Memory allocation failed\n";
        return EXIT_FAILURE;
    }

    fillUniqueKeys(keys, count);
    if (!validateKeys(keys, count)) {
        std::cerr << "Key validation failed\n";
        delete[] keys;
        return EXIT_FAILURE;
    }

    Record* records = new (std::nothrow) Record[50];
    if (!records) {
        std::cerr << "Memory allocation failed\n";
        delete[] keys;
        return EXIT_FAILURE;
    }

    fillRecords(records, 50);

    // Use the allocated memory...

    delete[] keys;
    delete[] records;

    return EXIT_SUCCESS;
}
