        fprintf(stderr, "Invalid array size: %zu\n", arraySize);
        return NULL;
    }

    PipelineContext* context = malloc(sizeof(PipelineContext));
    if (context == NULL) {
        perror("Failed to allocate memory for pipeline context");
        return NULL;
    }

    srand(seed);
    context->arraySize = arraySize;
    context->offsetRecords = calloc(arraySize, sizeof(OffsetRecord));
    if (context->offsetRecords == NULL) {
        perror("Failed to allocate memory for offset records");
        free(context);
        return NULL;
    }

    context->records = malloc(arraySize * sizeof(Record));
    if (context->records == NULL) {
        perror("Failed to allocate memory for records");
        free(context->offsetRecords);
        free(context);
