#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

int allocate_memory(long **offsets, int **keys, record **records, size_t num_elements) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    *offsets = malloc(num_elements * sizeof(long));
    if (*offsets == NULL) return -1; // Memory allocation failed

    *keys = calloc(num_elements, sizeof(int));
    if (*keys == NULL) { 
        free(*offsets);
        return -2; // Memory allocation failed
    }

    *records = malloc(num_elements * sizeof(record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -3; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_elements; ++i) {
        (*offsets)[i] = rand() % MAX_OFFSET; // Assign a unique offset within range

        pthread_mutex_lock(&mutex);
        int key;
        do {
            key = rand() % MAX_KEY; // Generate a unique key within range
        } while ((*keys)[key] != 0);
        (*keys)[key] = 1;
        pthread_mutex_unlock(&mutex);

        (*records)[i].value = rand() % MAX_RECORD_VALUE; // Assign a unique value to the record
    }

    return 0; // Success
}
```
This function allocates memory for three arrays: an array of `long` offsets, an array of `int` keys, and an array of `record` structures. It uses a mutex to ensure thread safety when generating unique keys. If any allocation fails, it frees all previously allocated memory and returns an error code indicating the failure.

