int error = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void logError(const char *msg) {
    pthread_mutex_lock(&lock);
    fprintf(stderr, "ERROR: %s\n", msg);
    error = 1;
    pthread_mutex_unlock(&lock);
}

long generateUniqueOffset(RecordSet* recordSets[], size_t numOfSets, long max) {
    long offset = rand() % max;
    for (size_t i = 0; i < numOfSets; ++i) {
        RecordSet *recordSet = recordSets[i];
        for (size_t j = 0; j < recordSet->size; ++j) {
            if (offset == recordSet->offsets[j]) {
                return generateUniqueOffset(recordSets, numOfSets, max);
            }
        }
    }
    return offset;
}

int initializeRecordSet(RecordSet* recordSet, size_t size, long maxOffset, int minKey, int maxKey) {
    srand((unsigned int)time(NULL));

    recordSet->offsets = malloc(size * sizeof(long));
    if (recordSet->offsets == NULL) {
        logError("Failed to allocate memory for offsets");
        return 1;
    }

    recordSet->keys = malloc(size * sizeof(int));
    if (recordSet->keys == NULL) {
        logError("Failed to allocate memory for keys");
        free(recordSet->offsets);
        return 1;
    }

    recordSet->records = malloc(size * sizeof(record*));
    if (recordSet->records == NULL) {
        logError("Failed to allocate memory for records");
        free(recordSet->offsets);
        free(recordSet->keys);
        return 1;
    }

    recordSet->size = size;
    for (size_t i = 0; i < size; ++i) {
        recordSet->offsets[i] = generateUniqueOffset((RecordSet*[]){recordSet}, 1, maxOffset);
        recordSet->keys[i] = minKey + rand() % (maxKey - minKey + 1);

        record *rec = malloc(sizeof(record));
        if (rec == NULL) {
            logError("Failed to allocate memory for a record");
            free(recordSet->offsets);
            free(recordSet->keys);
            for (size_t j = 0; j < i; ++j) {
                free(recordSet->records[j]);
            }
            free(recordSet->records);
            return 1;
        }

        rec->offset = recordSet->offsets[i];
        rec->key = recordSet->keys[i];
        recordSet->records[i] = rec;
    }

    return 0;
}
```
