    *offsets = malloc(numRecords * sizeof(long));
    if (*offsets == NULL) return -1; // Memory allocation failed

    *keys = malloc(numRecords * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -1; // Memory allocation failed
    }

    *records = malloc(numRecords * sizeof(record*));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -1; // Memory allocation failed
    }

    *metas = malloc(numRecords * sizeof(meta*));
    if (*metas == NULL) {
        free(*offsets);
        free(*keys);
        free(*records);
        return -1; // Memory allocation failed
    }

    for (size_t i = 0; i < numRecords; ++i) {
        (*metas)[i] = malloc(sizeof(meta));
        if ((*metas)[i] == NULL) {
            // Free all previously allocated memory and return error code
            for (size_t j = 0; j < i; ++j) {
                free((*records)[j]);
                pthread_mutex_destroy(&(*metas)[j]->lock);
                free((*metas)[j]);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            free(*metas);
            return -1; // Memory allocation failed
        }

        (*metas)[i]->rec = malloc(sizeof(record));
        if ((*metas)[i]->rec == NULL) {
            // Free all previously allocated memory and return error code
            for (size_t j = 0; j <= i; ++j) {
                free((*records)[j]);
                pthread_mutex_destroy(&(*metas)[j]->lock);
                free((*metas)[j]);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            free(*metas);
            return -1; // Memory allocation failed
        }

        pthread_mutex_init(&(*metas)[i]->lock, NULL);
    }

    return 0; // Success
}
