['Here is an example of how you might implement this in C. This code does not include the external logging system or the hash table implementation as those would be quite complex to show here. Also, it's important to note that error handling and resource management are crucial for any production-level code. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <dirent.h>

typedef struct directory_entry {
    char *path;
    struct stat stats;
} directory_entry;

int populate_directory(const char *root, directory_entry **entries) {
    DIR *dir = opendir(root);
    if (dir == NULL) {
        return -1;
    }

    int count = 0;
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char path[PATH_MAX];
        snprintf(path, sizeof(path), "%s/%s", root, entry->d_name);

        if (entry->d_type == DT_DIR) {
            if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
                continue;

            count += populate_directory(path, entries);
        } else {
            struct stat stats;
            if (stat(path, &stats) != 0) {
                return -1;
            }

            directory_entry *new_entry = malloc(sizeof(directory_entry));
            new_entry->path = strdup(path);
            new_entry->stats = stats;

            entries[count++] = new_entry;
        }
    }

    closedir(dir);
    return count;
}

int main() {
    directory_entry **entries = malloc(sizeof(directory_entry *) * 1024); // Start with a reasonable size.
    int count = populate_directory("/", entries);

    if (count < 0) {
        fprintf(stderr, "Failed to populate directory\n");
        return EXIT_FAILURE;
    }

    // Print the paths and sizes of all files.
    for (int i = 0; i < count; ++i) {
        printf("%s: %ld bytes\n", entries[i]->path, entries[i]->stats.st_size);
    }

    // Free memory.
    for (int i = 0; i < count; ++i) {
        free(entries[i]->path);
        free(entries[i]);
    }
    free(entries);

    return EXIT_SUCCESS;
}
```
This code is a simple example and does not include all the features you requested. It only reads from the root directory, populates an array of `directory_entry` structs with file paths and stats, and then prints out the sizes of each file. The memory for these entries is allocated dynamically and must be freed when no longer needed to prevent a memory leak.
