['Here is an example of how you might implement this in C using pthreads for threading and atomic operations for reference counting. This code does not include all the requirements mentioned as they are quite complex to implement properly, but it should give a good starting point. 

```c
#include <pthread.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdlib.h>

typedef union {
    char* string;
    int integer;
} value_t;

typedef struct data_item {
    uint64_t id;
    atomic_uint_fast32_t refcount;
    pthread_mutex_t lock;
    value_t value;
} data_item_t;

data_item_t* create_data_item(uint64_t id, int type, void* val) {
    data_item_t* item = malloc(sizeof(data_item_t));
    if (!item) return NULL;

    item->id = id;
    atomic_init(&item->refcount, 1);
    pthread_mutex_init(&item->lock, NULL);

    // Initialize value based on type and val
    if (type == 0) {
        item->value.string = strdup((char*)val);
    } else {
        item->value.integer = *(int*)val;
    }

    return item;
}

void acquire_data_item(data_item_t* item) {
    atomic_fetch_add(&item->refcount, 1);
}

void release_data_item(data_item_t* item) {
    if (atomic_fetch_sub(&item->refcount, 1) == 1) {
        pthread_mutex_lock(&item->lock);
        // Free resources in value union
        free(item->value.string);
        pthread_mutex_unlock(&item->lock);

        pthread_mutex_destroy(&item->lock);
        free(item);
    }
}
```
This code creates a `data_item` structure that contains an identifier, a reference count, and a lock for synchronization. The value union can hold either a string or an integer. When creating a new `data_item`, the type of the value is specified along with its initial value. 

The `acquire_data_item` function increments the reference count, while the `release_data_item` function decrements it and frees resources when the count reaches zero. Note that this code does not handle concurrent access to the collection from multiple threads or potential race conditions during concurrent operations. You would need to add appropriate locking mechanisms for these scenarios.
