['Here is a simplified version of how you might approach this problem in C. This code does not include all the features mentioned such as thread safety or error handling, but it should give you an idea of how to start implementing these features. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

typedef struct {
    size_t capacity;
    size_t count;
    Record* records;
    pthread_mutex_t lock;
} RecordArray;

RecordArray* create_record_array() {
    RecordArray* array = malloc(sizeof(RecordArray));
    if (array == NULL) return NULL;

    array->capacity = 50000;
    array->count = 0;
    array->records = malloc(array->capacity * sizeof(Record));
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void add_record(RecordArray* array, Record record) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->records = realloc(array->records, array->capacity * sizeof(Record));
    }

    array->records[array->count++] = record;

    pthread_mutex_unlock(&array->lock);
}

void serialize_record_array(RecordArray* array, FILE* file) {
    fwrite(&array->count, sizeof(size_t), 1, file);
    fwrite(array->records, sizeof(Record), array->count, file);
}

void deserialize_record_array(RecordArray* array, FILE* file) {
    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < count; ++i) {
        Record record;
        fread(&record, sizeof(Record), 1, file);
        add_record(array, record);
    }
}
```
This code creates a `RecordArray` structure that manages an array of records. It uses dynamic memory allocation to resize the array when necessary. The `add_record` function is thread-safe by using a mutex lock. 

The `serialize_record_array` and `deserialize_record_array` functions write and read the record array to/from a file, respectively. This allows for streaming serialization and reduces memory usage during the serialization process.

Please note that this is a simplified version of the problem and does not include all the features mentioned such as error handling or thread safety. Also, it assumes that the `Record` structure only contains an integer value. If you need to add more fields or support different data types, you would need to modify the `Record` structure accordingly.
