["Here is a basic implementation of your requirements in C. This code doesn't cover all aspects you mentioned due to its complexity but it gives an idea about how you can start implementing such a system. 

```c
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>

typedef enum TaskType {
    DATA_ITEM,
    RESOURCE
} TaskType;

typedef enum TaskState {
    CREATED,
    RUNNING,
    FINISHED
} TaskState;

struct data_item {
    // ...
};

struct resource {
    // ...
};

typedef struct task {
    uint64_t id;
    int priority;
    enum TaskState state;
    enum TaskType type;
    atomic_int refcount;
    pthread_mutex_t lock;
    union {
        struct data_item *data;
        struct resource *res;
    } u;
} task;

task* create_task(uint64_t id, int priority, TaskType type) {
    task* new_task = malloc(sizeof(task));
    if (new_task == NULL) return NULL;

    new_task->id = id;
    new_task->priority = priority;
    new_task->state = CREATED;
    new_task->type = type;
    atomic_init(&new_task->refcount, 1);

    pthread_mutex_init(&new_task->lock, NULL);

    // Asynchronous resource allocation
    if (type == RESOURCE) {
        new_task->u.res = malloc(sizeof(struct resource));
        // Initialize resource asynchronously...
    } else {
        new_task->u.data = malloc(sizeof(struct data_item));
        // Initialize data item synchronously...
    }

    return new_task;
}

void task_get(task* t) {
    atomic_fetch_add(&t->refcount, 1);
}

void task_put(task* t) {
    if (atomic_fetch_sub(&t->refcount, 1) == 1) {
        pthread_mutex_lock(&t->lock);

        // Release resources...
        if (t->type == RESOURCE) free(t->u.res);
        else free(t->u.data);

        pthread_mutex_unlock(&t->lock);
        pthread_mutex_destroy(&t->lock);
        free(t);
    }
}
```
This code creates a task structure that encapsulates the unique identifier, priority level, state, and type of each task. It also includes an atomic reference count for managing the lifecycle of tasks and a mutex to ensure thread safety during concurrent operations. The `create_task` function initializes a new task with the given parameters, while the `task_get` and `task_put` functions manage the lifecycle of tasks by incrementing and decrementing the reference count respectively.

