```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <assert.h>
#include <string.h>

typedef struct {
    int value;
} record;

// Define a cache entry structure
typedef struct CacheEntry_t {
    long offset;
    int key;
    record* rec;
    struct CacheEntry_t *prev, *next;
} CacheEntry;

// Define the cache data structure
typedef struct {
    int capacity;
    int size;
    CacheEntry *head, *tail;
    pthread_mutex_t lock;
} LRUCache;

LRUCache* cache = NULL;
pthread_mutex_t resizeLock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the cache
void initCache(int capacity) {
    cache = (LRUCache*)malloc(sizeof(LRUCache));
    cache->capacity = capacity;
    cache->size = 0;
    cache->head = cache->tail = NULL;
    pthread_mutex_init(&cache->lock, NULL);
}

// Function to check if a key is in the cache
record* getFromCache(long offset, int key) {
    // Lock the cache for thread safety
    pthread_mutex_lock(&cache->lock);

    CacheEntry *node = cache->head;
    while (node != NULL) {
        if (node->offset == offset && node->key == key) {
            // Move the accessed entry to the head of the list
            if (cache->head != node) {
                if (node->prev != NULL) {
                    node->prev->next = node->next;
                }
                if (node->next != NULL) {
                    node->next->prev = node->prev;
                }
                node->next = cache->head;
                cache->head->prev = node;
                cache->head = node;
            }

            pthread_mutex_unlock(&cache->lock);
            return node->rec;
        }

        node = node->next;
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

// Function to add a key-value pair to the cache
void putInCache(long offset, int key, record* rec) {
    // Lock the cache for thread safety
    pthread_mutex_lock(&cache->lock);

    CacheEntry *node = (CacheEntry*)malloc(sizeof(CacheEntry));
    node->offset = offset;
    node->key = key;
    node->rec = rec;
    node->next = cache->head;
    node->prev = NULL;

    if (cache->head != NULL) {
        cache->head->prev = node;
    }
    cache->head = node;
    if (cache->tail == NULL) {
        cache->tail = node;
    }

    // If the cache is full, remove the least recently used entry
    if (cache->size >= cache->capacity) {
        CacheEntry *lastNode = cache->tail;
        cache->tail = lastNode->prev;
        if (cache->tail != NULL) {
            cache->tail->next = NULL;
        }

        free(lastNode);
    } else {
        cache->size++;
    }

    pthread_mutex_unlock(&cache->lock);
}

// Function to resize the arrays
void resizeArrays(long* offsets, int* keys, record** records, long oldSize, long newSize) {
    // Lock for thread safety
    pthread_mutex_lock(&resizeLock);

    offsets = (long*)realloc(offsets, newSize * sizeof(long));
    assert(offsets != NULL);

    keys = (int*)realloc(keys, newSize * sizeof(int));
    assert(keys != NULL);

    records = (record**)realloc(records, newSize * sizeof(record*));
    assert(records != NULL);

    // Initialize the new memory locations with random values
    srand((unsigned int)time(NULL));
    for (long i = oldSize; i < newSize; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % INT_MAX;
        records[i] = (record*)malloc(sizeof(record));
        assert(records[i] != NULL);
    }

    pthread_mutex_unlock(&resizeLock);
}

// Function to initialize the arrays and handle resizing if necessary
void initialize_records(long* offsets, int* keys, record** records, long size, bool resizeFlag) {
    // Allocate memory for the arrays
    offsets = (long*)malloc(size * sizeof(long));
    assert(offsets != NULL);

    keys = (int*)malloc(size * sizeof(int));
    assert(keys != NULL);

    records = (record**)malloc(size * sizeof(record*));
