int initRecordArray(RecordArray* array, size_t initialCapacity) {
    array->records = malloc(sizeof(record*) * initialCapacity);
    if (array->records == NULL) return -1;

    array->capacity = initialCapacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return 0;
}

int addRecord(RecordArray* array, record* rec) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        record** newRecords = realloc(array->records, sizeof(record*) * newCapacity);

        if (newRecords == NULL) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }

        array->capacity = newCapacity;
        array->records = newRecords;
    }

    array->records[array->count++] = rec;

    pthread_mutex_unlock(&array->lock);

    return 0;
}

void freeRecordArray(RecordArray* array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->records[i]->offset);
        free(array->records[i]);
    }

    pthread_mutex_destroy(&array->lock);
    free(array->records);
}
```
This is a simplified version of the function. In a real-world scenario, you would need to handle concurrency and error checking more carefully, as well as integrate with an existing memory management library. Also, this code does not include mechanisms for handling duplicate keys or offsets, which are complex topics in their own right.
