typedef struct {
    int key;
} Record;

typedef struct {
    long* offsets;
    Record** records;
    size_t capacity;
    size_t count;
} MemoryPool;

MemoryPool* createMemoryPool(size_t initialCapacity) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (pool == NULL) return NULL;

    pool->offsets = malloc(initialCapacity * sizeof(long));
    if (pool->offsets == NULL) {
        free(pool);
        return NULL;
    }

    pool->records = malloc(initialCapacity * sizeof(Record*));
    if (pool->records == NULL) {
        free(pool->offsets);
        free(pool);
        return NULL;
    }

    pool->capacity = initialCapacity;
    pool->count = 0;

    return pool;
}

void destroyMemoryPool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->records[i]);
    }
    free(pool->offsets);
    free(pool->records);
    free(pool);
}

int addRecord(MemoryPool* pool, int key) {
    if (pool->count == pool->capacity) {
        size_t newCapacity = pool->capacity * 2;

        long* newOffsets = realloc(pool->offsets, newCapacity * sizeof(long));
        if (newOffsets == NULL) return -1;
        pool->offsets = newOffsets;

        Record** newRecords = realloc(pool->records, newCapacity * sizeof(Record*));
        if (newRecords == NULL) return -1;
        pool->records = newRecords;

        pool->capacity = newCapacity;
    }

    Record* record = malloc(sizeof(Record));
    if (record == NULL) return -1;

    record->key = key;
    pool->records[pool->count] = record;
    pool->offsets[pool->count] = (long)(record);
    ++pool->count;

    return 0;
}

int compareRecords(const void* a, const void* b) {
    Record** recordA = (Record**)a;
    Record** recordB = (Record**)b;
    return (*recordA)->key - (*recordB)->key;
}

void sortRecordsByKey(MemoryPool* pool) {
    qsort(pool->records, pool->count, sizeof(Record*), compareRecords);
}
```
This code creates a `MemoryPool` structure that manages the memory for an array of 'record' structures. The `createMemoryPool` function allocates initial memory for the arrays and sets up the capacity and count variables. The `destroyMemoryPool` function frees all allocated memory when the pool is no longer needed.

The `addRecord` function adds a new record to the pool, resizing the arrays if necessary. It uses realloc to resize the arrays in place, which can be more efficient than allocating and copying the entire array each time it needs to grow.

Finally, the `sortRecordsByKey` function sorts the records by their 'int' value using the standard library qsort function. This function requires a comparison function that takes pointers to elements of the array being sorted, so we use a helper function `compareRecords` to do this. The sorting is done in-place, which can be more efficient than creating a new sorted copy of the array each time it needs to be accessed.
