['Here's an example implementation of such a function using JavaScript. This code uses Promises for script loading and dependency resolution, which allows for asynchronous execution and error handling. It also includes a simple mechanism for conditional script execution based on conditions. 

```javascript
class ScriptManager {
    constructor() {
        this.scripts = {};
        this.loadedScripts = new Set();
    }

    addScript(script) {
        if (!this.scripts[script.key]) {
            this.scripts[script.key] = script;
        } else {
            console.warn(`A script with key ${script.key} already exists. Skipping...`);
        }
    }

    loadScript(key) {
        if (this.loadedScripts.has(key)) {
            return Promise.resolve();
        }

        const script = this.scripts[key];
        if (!script) {
            return Promise.reject(`No script found with key ${key}`);
        }

        // Load dependencies first
        const dependencyPromises = (script.dependsOn || []).map(depKey => this.loadScript(depKey));
        return Promise.all(dependencyPromises)
            .then(() => {
                if (!this.loadedScripts.has(key)) {
                    return new Promise((resolve, reject) => {
                        const scriptElement = document.createElement('script');
                        scriptElement.innerHTML = script.innerHTML;
                        scriptElement.src = script.source;
                        scriptElement.onload = () => {
                            this.loadedScripts.add(key);
                            resolve();
                        };
                        scriptElement.onerror = reject;
                        document.body.appendChild(scriptElement);
                    });
                }
            })
            .catch((err) => {
                console.warn(`Failed to load script ${key}: ${err}`);
                return Promise.reject(err);
            });
    }

    executeScript(key, condition = true) {
        if (this.loadedScripts.has(key)) {
            const script = this.scripts[key];
            try {
                // Execute the script only if the provided condition is truthy
                if (condition && typeof window[script.innerHTML] === 'function') {
                    window[script.innerHTML]();
                } else {
                    console.warn(`Script ${key} did not meet execution conditions. Skipping...`);
                }
            } catch (err) {
                console.error(`Failed to execute script ${key}: ${err}`);
            }
        } else {
            console.warn(`No loaded script found with key ${key}. Loading and executing...`);
            this.loadScript(key).then(() => this.executeScript(key, condition));
        }
    }
}
```
This code can be used as follows:

```javascript
const manager = new ScriptManager();
manager.addScript({ key: 'script1', innerHTML: 'console.log("Hello, World!");' });
manager.executeScript('script1'); // Will log "Hello, World!" to the console
```

Please note that this is a basic implementation and may need further refinement based on your specific requirements and constraints. For instance, you might want to add support for different script types (inline scripts, external scripts), more robust error handling, or additional features like script removal or updating.
']

