["Here is a basic implementation of your requirements in C. This code does not cover all aspects you mentioned, but it provides a starting point for further development. 

```c
#include <stdlib.h>
#include <stdatomic.h>
#include <pthread.h>

typedef struct {
    long* offset;
    int value;
} record;

// Memory pool for reusing memory
static void* mem_pool = NULL;
static size_t mem_size = 0;

void* allocate(size_t size) {
    if (mem_size < size) {
        free(mem_pool);
        mem_pool = malloc(size);
        mem_size = size;
    }
    return mem_pool;
}

// Thread-safe key generation
static atomic_int next_key = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int get_next_key() {
    pthread_mutex_lock(&lock);
    int key = atomic_fetch_add(&next_key, 1);
    pthread_mutex_unlock(&lock);
    return key;
}

// Dynamic resizing of the record array
static size_t record_size = 0;
static size_t record_capacity = 0;

void resize_records(record** records, size_t new_capacity) {
    *records = realloc(*records, new_capacity * sizeof(record));
    if (new_capacity > record_capacity) {
        for (size_t i = record_capacity; i < new_capacity; ++i) {
            (*records)[i].offset = NULL;
            (*records)[i].value = 0;
        }
    }
    record_capacity = new_capacity;
}

// Populate records with random integers within a specified range
void populate_records(record* records, int min, int max) {
    for (size_t i = 0; i < record_size; ++i) {
        if (!records[i].offset) {
            records[i].offset = allocate(sizeof(long));
            *(records[i].offset) = get_next_key();
            records[i].value = rand() % (max - min + 1) + min;
        }
    }
}

// Integration with existing memory management library
void free_memory() {
    free(mem_pool);
}
```
