    int value;
} Record;

// Define the NICB structure
typedef struct {
    pthread_mutex_t lock;
    Record* records;
    size_t numRecords;
} NICB;

NICB* createNICBs(size_t numNICBs, size_t numRecords) {
    srand((unsigned int)time(NULL)); // Seed the random number generator

    NICB* nicbs = malloc(numNICBs * sizeof(NICB));
    if (nicbs == NULL) {
        fprintf(stderr, "Failed to allocate memory for NICBs: %s\n", strerror(errno));
        return NULL;
    }

    for (size_t i = 0; i < numNICBs; ++i) {
        nicbs[i].records = malloc(numRecords * sizeof(Record));
        if (nicbs[i].records == NULL) {
            fprintf(stderr, "Failed to allocate memory for records: %s\n", strerror(errno));
            return NULL;
        }

        nicbs[i].numRecords = numRecords;
        pthread_mutex_init(&nicbs[i].lock, NULL);

        // Initialize the records with random values
        for (size_t j = 0; j < numRecords; ++j) {
            nicbs[i].records[j].value = rand();
        }
    }

    return nicbs;
}

void destroyNICBs(NICB* nicbs, size_t numNICBs) {
    for (size_t i = 0; i < numNICBs; ++i) {
        pthread_mutex_destroy(&nicbs[i].lock);
        free(nicbs[i].records);
