clock_t start, end;
double cpu_time_used;
int seed = 0;

void init_nicb(NICB* nicb) {
    srand(seed);
    pthread_mutex_init(&nicb->lock, NULL);
    nicb->id = rand();
    nicb->records = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 1024); // Assuming each NICB has 1024 records.
    if (nicb->records == NULL) {
        printf("Memory allocation failed for NICB %d\n", nicb->id);
        exit(EXIT_FAILURE);
    }
    nicb->record_count = 1024; // Assuming each NICB has 1024 records.
}

void init_nicbs() {
    start = clock();
    for (int i = 0; i < 10000; ++i) {
        nicbs[i] = malloc(sizeof(NICB));
        if (nicbs[i] == NULL) {
            printf("Memory allocation failed for NICBs\n");
            exit(EXIT_FAILURE);
        }
        init_nicb(nicbs[i]);
    }
    end = clock();
    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Time taken to initialize 10,000 NICBs: %f\n", cpu_time_used);
}

void validate_nicb(NICB* nicb) {
    for (int i = 0; i < nicb->record_count; ++i) {
        if (nicb->records[i].RX_UE_INFORMATION_TAG < 0 || nicb->records[i].RNTI > 65535 || 
            nicb->records[i].CRC_INDICATION_REL8_TAG < 0) {
            printf("Data integrity check failed for NICB %d\n", nicb->id);
        }
    }
}

void validate_nicbs() {
    start = clock();
    for (int i = 0; i < 10000; ++i) {
        pthread_mutex_lock(&global_lock);
        validate_nicb(nicbs[i]);
        pthread_mutex_unlock(&global_lock);
    }
    end = clock();
    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Time taken to validate 10,000 NICBs: %f\n", cpu_time_used);
}

int main() {
    init_nicbs();
    validate_nicbs();

    int max = 0;
    for (int i = 0; i < 10000; ++i) {
        if (nicbs[i]->id > max) {
            max = nicbs[i]->id;
        }
    }
    printf("Largest ID: %d\n", max);

    return 0;
}
```
