Node* insert_node(Node** root, int key, int value, const char* str) {
    if (*root == NULL) {
        *root = new_node(key, value, str);
        return *root;
    }

    if (key < (*root)->key) {
        if ((*root)->left != NULL)
            return insert_node(&((*root)->left), key, value, str);
        else {
            Node* node = new_node(key, value, str);
            node->parent = *root;
            (*root)->left = node;
        }
    } 
    else if (key > (*root)->key) {
        if ((*root)->right != NULL)
            return insert_node(&((*root)->right), key, value, str);
        else {
            Node* node = new_node(key, value, str);
            node->parent = *root;
            (*root)->right = node;
        }
    }

    return NULL; // duplicate key
}

void delete_tree(Node** root) {
    if (*root != NULL) {
        delete_tree(&((*root)->left));
        delete_tree(&((*root)->right));
        free(*root);
        *root = NULL;
    }
}

void traverse(Node* root, void (*callback)(Node*)) {
    if (root != NULL) {
        traverse(root->left, callback);
        callback(root);
        traverse(root->right, callback);
    }
}

