```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    int value;
    char* string;
    struct record* next_record;
} Record;

typedef enum metadata {
    EMPTY,
    FULL
} Metadata;

typedef struct node {
    long offset;
    int key;
    Record* record;
    Metadata status;
    pthread_mutex_t lock;
} Node;

Node** collection = NULL;
int capacity = 0;
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void resize(int new_capacity) {
    if (new_capacity <= capacity) return;

    Node** new_collection = malloc(sizeof(Node*) * new_capacity);
    memcpy(new_collection, collection, sizeof(Node*) * capacity);
    free(collection);

    for (int i = capacity; i < new_capacity; ++i) {
        new_collection[i] = malloc(sizeof(Node));
        new_collection[i]->status = EMPTY;
        pthread_mutex_init(&new_collection[i]->lock, NULL);
    }

    capacity = new_capacity;
    collection = new_collection;
}

int hash(int key) {
    return key % capacity;
}

void insert(int key, Record* record) {
    int index = hash(key);
    pthread_mutex_lock(&global_lock);

    while (collection[index]->status == FULL && collection[index]->key != key) {
        index = (index + 1) % capacity;
    }

    if (collection[index]->status == EMPTY || collection[index]->key != key) {
        pthread_mutex_lock(&collection[index]->lock);

        if (collection[index]->status == EMPTY) resize(capacity * 2);

        collection[index]->key = key;
        collection[index]->record = record;
        collection[index]->status = FULL;

        pthread_mutex_unlock(&collection[index]->lock);
    }

    pthread_mutex_unlock(&global_lock);
}
```
This code implements a basic hash table with linear probing for collision resolution. It uses a global lock to ensure thread safety during resizing and insertion operations. The resize operation doubles the capacity of the collection when necessary, which is a simple strategy but may not be optimal in all cases. 

