            free(offsets);
            free(keys);
            return -1;
        }

        records[i]->value = rand(); // Set the record value to a random integer.
    }

    // Verify that all records are correctly populated and within the specified range.
    for (size_t i = 0; i < size; ++i) {
        if (records[i]->value < 0 || records[i]->value > RAND_MAX) return -1; // Record value out of range.
