typedef struct {
    LTE_ENB_RRC_MESSAGE_T **messages;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray *create_dynamic_array(size_t initial_capacity) {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    arr->messages = calloc(initial_capacity, sizeof(LTE_ENB_RRC_MESSAGE_T*));
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void add_message(DynamicArray *arr, LTE_ENB_RRC_MESSAGE_T *msg) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size == arr->capacity) {
        arr->messages = realloc(arr->messages, 2 * arr->capacity * sizeof(LTE_ENB_RRC_MESSAGE_T*));
        arr->capacity *= 2;
    }

    arr->messages[arr->size++] = msg;

    pthread_mutex_unlock(&arr->lock);
}

void remove_message(DynamicArray *arr, size_t index) {
    pthread_mutex_lock(&arr->lock);

    if (index >= arr->size) {
        return;
    }

    free(arr->messages[index]);

    for (size_t i = index; i < arr->size - 1; ++i) {
        arr->messages[i] = arr->messages[i + 1];
    }

    --arr->size;

    pthread_mutex_unlock(&arr->lock);
}

void iterate(DynamicArray *arr, void (*func)(LTE_ENB_RRC_MESSAGE_T*)) {
    for (size_t i = 0; i < arr->size; ++i) {
        func(arr->messages[i]);
    }
}
