['Here's a basic implementation in C using dynamic memory allocation for each collection. Note that this code does not handle the system dependencies, performance constraints, integration issues, scalability, or other real-world constraints mentioned in your problem statement. It also doesn't include error handling for failed memory allocations and it assumes that all keys and unique identifiers are positive integers.

```c
#include <stdlib.h>
#include <time.h>
#include <assert.h>

typedef struct {
    int value;
    long* offset;
    unsigned int* uid;
    int* key;
} Record;

Record** create_records(int size, int minKey, int maxKey) {
    srand(time(NULL));

    // Allocate memory for collections
    long* offsets = malloc(size * sizeof(long));
    unsigned int* uids = calloc(size, sizeof(unsigned int));
    int* keys = malloc(size * sizeof(int));
    Record** records = malloc(size * sizeof(Record*));

    // Check if memory allocation was successful
    assert(offsets != NULL && uids != NULL && keys != NULL && records != NULL);

    // Initialize collections with random values within a defined range
    for (int i = 0; i < size; ++i) {
        offsets[i] = rand();

        int attempts = 0;
        do {
            uids[i] = rand() % maxKey + 1; // Ensure unique identifier
            ++attempts;
        } while (attempts < 5 && is_duplicate(uids, i));

        attempts = 0;
        do {
            keys[i] = minKey + rand() % (maxKey - minKey + 1); // Ensure unique key
            ++attempts;
        } while (attempts < 5 && is_duplicate(keys, i));

        records[i] = malloc(sizeof(Record));
        assert(records[i] != NULL);

        // Initialize record with pointers to corresponding collections
        records[i]->value = rand();
        records[i]->offset = &offsets[i];
        records[i]->uid = &uids[i];
        records[i]->key = &keys[i];
    }

    return records;
}

int is_duplicate(int* array, int index) {
    for (int i = 0; i < index; ++i) {
        if (array[index] == array[i]) {
            return 1;
        }
    }

    return 0;
}

void print_records(Record** records, int size) {
    for (int i = 0; i < size; ++i) {
        printf("Record %d: Value = %d, Offset = %ld, Key = %d, Unique Identifier = %u\n", 
               i + 1, records[i]->value, *records[i]->offset, *records[i]->key, *records[i]->uid);
    }
}
```
This code creates a function `create_records` that allocates and initializes the collections. It then populates each collection with random values within a defined range, ensuring that no two records share the same key or unique identifier. The function also includes a helper function `is_duplicate` to check for duplicate keys and identifiers. Finally, it provides a function `print_records` to print the contents of the records for debugging purposes.
