    char* str;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    double* values;
    Record* records;
    size_t capacity;
    size_t size;
} DataStructures;

DataStructures* init(size_t initialCapacity) {
    DataStructures* ds = malloc(sizeof(DataStructures));
    if (ds == NULL) return NULL;

    ds->offsets = calloc(initialCapacity, sizeof(long));
    ds->keys = calloc(initialCapacity, sizeof(int));
    ds->values = calloc(initialCapacity, sizeof(double));
    ds->records = calloc(initialCapacity, sizeof(Record));

    if (ds->offsets == NULL || ds->keys == NULL || ds->values == NULL || ds->records == NULL) {
        freeDataStructures(ds);
        return NULL;
    }

    ds->capacity = initialCapacity;
    ds->size = 0;

    return ds;
}

void resize(DataStructures* ds, size_t newCapacity) {
    ds->offsets = realloc(ds->offsets, newCapacity * sizeof(long));
    ds->keys = realloc(ds->keys, newCapacity * sizeof(int));
    ds->values = realloc(ds->values, newCapacity * sizeof(double));
    ds->records = realloc(ds->records, newCapacity * sizeof(Record));

    if (newCapacity > ds->capacity) {
        memset(ds->offsets + ds->capacity, 0, (newCapacity - ds->capacity) * sizeof(long));
        memset(ds->keys + ds->capacity, 0, (newCapacity - ds->capacity) * sizeof(int));
        memset(ds->values + ds->capacity, 0, (newCapacity - ds->capacity) * sizeof(double));
    }

    ds->capacity = newCapacity;
}

void addRecord(DataStructures* ds, long offset, int key, double value, char* str) {
    if (ds->size == ds->capacity) resize(ds, ds->capacity * 2);

    ds->offsets[ds->size] = offset;
    ds->keys[ds->size] = key;
    ds->values[ds->size] = value;
    ds->records[ds->size].key = key;
    ds->records[ds->size].value = value;
    ds->records[ds->size].str = strdup(str);

    ds->size++;
}

void freeDataStructures(DataStructures* ds) {
    for (size_t i = 0; i < ds->capacity; ++i) {
        free(ds->records[i].str);
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->values);
    free(ds->records);
    free(ds);
}
```
