    int account_id;
    double total_transaction_amount;
} Report;

int initialize(Transaction **transactions, size_t num_transactions, 
                Report **reports, size_t num_accounts) {

    *transactions = malloc(num_transactions * sizeof(Transaction));
    if (*transactions == NULL) return -1; // Memory allocation failure

    srand((unsigned int)time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < num_transactions; ++i) {
        (*transactions)[i].account_id = rand() % num_accounts; // Random account ID
        (*transactions)[i].timestamp = time(NULL); // Current timestamp
        (*transactions)[i].transaction_amount = (double)(rand() % 10000) / 100.0; // Random transaction amount
    }

    *reports = calloc(num_accounts, sizeof(Report));
    if (*reports == NULL) {
        free(*transactions);
        return -2; // Memory allocation failure
    }

    for (size_t i = 0; i < num_transactions; ++i) {
        int account_id = (*transactions)[i].account_id;
        (*reports)[account_id].total_transaction_amount += (*transactions)[i].transaction_amount;
    }

    return 0; // Success
}
