SensorNode* create_sensor_node(size_t initialCapacity) {
    SensorNode* node = malloc(sizeof(SensorNode));
    if (node == NULL) return NULL;

    node->readings = malloc(initialCapacity * sizeof(SensorReading));
    if (node->readings == NULL) {
        free(node);
        return NULL;
    }

    node->capacity = initialCapacity;
    node->size = 0;

    return node;
}

int add_reading(SensorNode* node, SensorReading reading) {
    if (node->size >= node->capacity) {
        size_t newCapacity = node->capacity * 2;
        SensorReading* newReadings = realloc(node->readings, newCapacity * sizeof(SensorReading));
        if (newReadings == NULL) return -1;

        node->readings = newReadings;
        node->capacity = newCapacity;
    }

    node->readings[node->size++] = reading;
    return 0;
}

void reset_sensor_node(SensorNode* node) {
    free(node->readings);
    node->capacity = 0;
    node->size = 0;
}
