```javascript
const EventEmitter = require('events');
const request = require('request-promise');
const logger = require('./logger'); // Assuming you have a custom logger module

class DataStreamManager extends EventEmitter {
    constructor() {
        super();
        this.streams = {};
        this.maxThroughput = 100; // Default max throughput per stream
        this.retryDelay = 5000; // Initial retry delay in ms
        this.retryCount = 3; // Maximum number of retries before giving up
    }

    setMaxThroughput(max) {
        this.maxThroughput = max;
    }

    addStream(id, dataSource, messagingServiceUrl) {
        if (Object.keys(this.streams).length >= 50) {
            throw new Error('Cannot exceed 50 concurrent streams');
        }

        const stream = {
            id: id,
            source: dataSource,
            messagingServiceUrl: messagingServiceUrl,
            isPaused: false,
            throughput: this.maxThroughput, // Default to max throughput
            retryDelay: this.retryDelay,
            retryCount: this.retryCount
        };

        this.streams[id] = stream;
    }

    pauseStream(id) {
        if (this.streams[id]) {
            this.streams[id].isPaused = true;
        } else {
            throw new Error('No such stream');
        }
    }

    resumeStream(id) {
        if (this.streams[id]) {
            this.streams[id].isPaused = false;
        } else {
            throw new Error('No such stream');
        }
    }

    start() {
        for (let id in this.streams) {
            if (!this.streams[id].isPaused) {
                this._processStream(id);
            }
        }
    }

    stop() {
        // Stop all streams by pausing them
        for (let id in this.streams) {
            this.pauseStream(id);
        }
    }

    _processStream(id) {
        const stream = this.streams[id];

        if (!stream || stream.isPaused) return;

        // Simulate data collection and processing here...
        let data = stream.source.getData();

        request({
            uri: stream.messagingServiceUrl,
            body: JSON.stringify(data),
            headers: { 'Content-Type': 'application/json' },
            resolveWithFullResponse: true
        })
        .then((response) => {
            if (response.statusCode === 200) {
                logger.info('Data sent successfully');
            } else {
                throw new Error(`Failed to send data, status code ${response.statusCode}`);
            }
        })
        .catch((error) => {
            if (stream.retryCount > 0) {
                logger.warn('Data transmission failed, retrying...');
                stream.retryCount--;
                setTimeout(() => this._processStream(id), stream.retryDelay);
            } else {
                logger.error('Failed to send data after multiple retries');
            }
        });
    }
}
```
This is a simplified example and does not cover all your requirements, but it should give you a good starting point. You would need to implement the `dataSource` interface and integrate with your existing microservices architecture. Also, this code assumes that there's a logger module available which logs events at different levels (info, warn, error).
