        ds->timestamps = realloc(ds->timestamps, ds->capacity * sizeof(long));
        ds->readings = realloc(ds->readings, ds->capacity * sizeof(float));
        ds->events = realloc(ds->events, ds->capacity * sizeof(Event*));
