    int value;
} NICB;

NICB* nicbs[10000];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int findMax(NICB** array, size_t length) {
    int max = 0;
    for (size_t i = 0; i < length; ++i) {
        if (array[i]->value > max) {
            max = array[i]->value;
        }
    }
    return max;
}

void* processNICB(void* arg) {
    int value;
    while (scanf("%d", &value) == 1) {
        NICB* nicb = malloc(sizeof(NICB));
        if (!nicb) {
            fprintf(stderr, "Failed to allocate memory for NICB\n");
            continue;
        }
        nicb->value = value;

        pthread_mutex_lock(&lock);
        static size_t index = 0;
        nicbs[index++] = nicb;
        if (index == 10000) {
            printf("Maximum NICB value: %d\n", findMax(nicbs, 10000));
            for (size_t i = 0; i < 10000; ++i) {
                free(nicbs[i]);
            }
            index = 0;
        }
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

int main() {
