int init_arrays(long *offset, int *keys, Record **records, size_t size) {
    if (size == 0 || offset == NULL || keys == NULL || records == NULL) {
        return -1; // Invalid input
    }

    *offset = malloc(sizeof(long) * size);
    if (*offset == NULL) {
        return -2; // Memory allocation failed
    }

    *keys = malloc(sizeof(int) * size);
    if (*keys == NULL) {
        free(*offset);
        return -2; // Memory allocation failed
    }

    *records = malloc(sizeof(Record) * size);
    if (*records == NULL) {
        free(*offset);
        free(*keys);
        return -2; // Memory allocation failed
    }

    for (size_t i = 0; i < size; ++i) {
        (*offset)[i] = rand();
        (*keys)[i] = rand() % 100; // Random number between 0 and 99

        Record *record = &((*records)[i]);
        record->value = (*keys)[i];

        char name[256];
        sprintf(name, "%ld%d", (*offset)[i], (*keys)[i]);

        record->name = malloc(strlen(name) + 1);
        if (record->name == NULL) {
            // Free all previously allocated memory and return an error code
            for (size_t j = 0; j < i; ++j) {
                free((*records)[j].name);
            }
            free(*offset);
            free(*keys);
            free(*records);
            return -2; // Memory allocation failed
        }

        strcpy(record->name, name);
    }

    return 0; // Success
}
