```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct TempData {
    long timestamp;
    double temperature;
} TempData;

typedef struct Node {
    TempData data;
    struct Node *next, *prev;
} Node;

Node* create_node(long timestamp, double temperature) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        exit(1);
    }

    new_node->data.timestamp = timestamp;
    new_node->data.temperature = temperature;
    new_node->next = NULL;
    new_node->prev = NULL;

    return new_node;
}

Node* insert(Node** head, long timestamp, double temperature) {
    Node* new_node = create_node(timestamp, temperature);

    if (!(*head)) {
        *head = new_node;
        return new_node;
    }

    Node* current = *head;
    while (current->next && current->data.timestamp < timestamp) {
        current = current->next;
    }

    if (!current->prev) { // insert at head
        new_node->next = current;
        current->prev = new_node;
        *head = new_node;
    } else if (!current->next && current->data.timestamp < timestamp) { // insert at tail
        current->next = new_node;
        new_node->prev = current;
    } else { // insert in middle
        new_node->next = current;
        new_node->prev = current->prev;
        current->prev->next = new_node;
        current->prev = new_node;
    }

    return new_node;
}

double average(Node* head, long start, long end) {
    Node* current = head;
    double sum = 0.0;
    int count = 0;

    while (current && current->data.timestamp <= end) {
        if (current->data.timestamp >= start) {
            sum += current->data.temperature;
            count++;
        }

        current = current->next;
    }

    return count ? sum / count : 0.0;
}
```
