    if (arr->size >= arr->capacity) {
        arr->capacity *= 2;
        arr->elements = realloc(arr->elements, arr->capacity * sizeof(Data));
    }

    arr->elements[arr->size++] = element;

    pthread_mutex_unlock(&arr->lock);
}

double average(Array* arr) {
