['Here is an example implementation in C. This code does not include all the optimizations mentioned in your question (like using binary search for indexing or other performance enhancements), but it should give you a good starting point. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    size_t count;
    size_t capacity;
    int* index;
} DataStorage;

DataStorage* create_storage(size_t initial_capacity) {
    DataStorage* storage = malloc(sizeof(DataStorage));
    if (storage == NULL) return NULL;

    storage->offsets = calloc(initial_capacity, sizeof(long));
    storage->keys = malloc(initial_capacity * sizeof(int));
    storage->records = calloc(initial_capacity, sizeof(Record));
    if (storage->offsets == NULL || storage->keys == NULL || storage->records == NULL) {
        free(storage->offsets);
        free(storage->keys);
        free(storage->records);
        free(storage);
        return NULL;
    }

    storage->index = calloc(initial_capacity, sizeof(int));
    if (storage->index == NULL) {
        free(storage->offsets);
        free(storage->keys);
        free(storage->records);
        free(storage->index);
        free(storage);
        return NULL;
    }

    storage->count = 0;
    storage->capacity = initial_capacity;
    srand(time(NULL)); // seed the random number generator
    return storage;
}

void add_record(DataStorage* storage, int key) {
    if (storage->count == storage->capacity) {
        size_t new_capacity = storage->capacity * 2;
        long* new_offsets = realloc(storage->offsets, new_capacity * sizeof(long));
        int* new_keys = realloc(storage->keys, new_capacity * sizeof(int));
        Record* new_records = realloc(storage->records, new_capacity * sizeof(Record));
        if (new_offsets == NULL || new_keys == NULL || new_records == NULL) return; // handle allocation failure gracefully

        storage->offsets = new_offsets;
        storage->keys = new_keys;
        storage->records = new_records;
        storage->capacity = new_capacity;
    }

    storage->offsets[storage->count] = sizeof(Record); // assuming offset is the size of a record for simplicity
    storage->keys[storage->count] = key;
    storage->records[storage->count].value = rand() % 1000 + 1; // initialize to random value between 1 and 1000

    storage->index[key] = storage->count; // update index array
    storage->count++;
}

void serialize(DataStorage* storage, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) return; // handle file opening failure gracefully

    fwrite(&storage->count, sizeof(size_t), 1, file);
    fwrite(storage->offsets, sizeof(long), storage->count, file);
    fwrite(storage->keys, sizeof(int), storage->count, file);
    fwrite(storage->records, sizeof(Record), storage->count, file);

    fclose(file);
}

DataStorage* deserialize(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) return NULL; // handle file opening failure gracefully

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    DataStorage* storage = create_storage(count);
    if (storage == NULL) {
        fclose(file);
        return NULL; // handle allocation failure gracefully
    }

    fread(storage->offsets, sizeof(long), count, file);
    fread(storage->keys, sizeof(int), count, file);
    fread(storage->records, sizeof(Record), count, file);

    for (size_t i = 0; i < count; ++i) {
        storage->index[storage->keys[i]] = i; // update index array
    }

    fclose(file);
    return storage;
}

void free_storage(DataStorage* storage) {
    free(storage->offsets);
    free(storage->keys);
    free(storage->records);
    free(storage->index);
    free(storage);
}
```
This code creates a flexible data storage system that can handle a variable number of records. It uses dynamic memory allocation to store arrays of offsets, keys, and records. The 'add_record' function handles potential memory allocation failures gracefully by returning early if any allocation fails. 

The 'serialize' and 'deserialize' functions write the entire structure to a file in binary format for efficient saving and reconstruction. They also handle file opening failures gracefully by returning early if any file operation fails. 

Finally, the 'free_storage' function frees all allocated memory when the data storage system is no longer needed. This ensures that all memory is freed upon exit to prevent memory leaks.
']

