double roundToTwoDecimalPlaces(float number) {
    return roundf(number * 100) / 100;
}

void addTransaction(char* key, Point coordinates) {
    pthread_mutex_lock(&lock);

    if (size >= capacity) {
        capacity = capacity == 0 ? 1 : capacity * 2;
        transactions = realloc(transactions, sizeof(Transaction*) * capacity);

        if (!transactions) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    Transaction* transaction = malloc(sizeof(Transaction));

    if (!transaction) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        exit(EXIT_FAILURE);
    }

    transaction->key = strdup(key);

    if (!transaction->key) {
        fprintf(stderr, "Memory allocation failed\n");
        free(transaction);
        pthread_mutex_unlock(&lock);
        exit(EXIT_FAILURE);
    }

    transaction->coordinates = coordinates;
    transaction->value = roundToTwoDecimalPlaces((coordinates.x + coordinates.y) / 2);
    transactions[size++] = transaction;

    pthread_mutex_unlock(&lock);
}

void freeTransactions() {
    for (int i = 0; i < size; ++i) {
        free(transactions[i]->key);
        free(transactions[i]);
    }

    free(transactions);
}

int main() {
    // Add transactions here...

    atexit(freeTransactions);

    return 0;
}
```
This code implements a basic transaction system with thread-safe operations. It uses dynamic memory allocation to handle variable throughput and occasional data bursts, minimizing the risk of heap fragmentation. The `addTransaction` function is thread-safe and can be called from multiple threads concurrently without locking overhead. 

