    mgr->records = calloc(max_size, sizeof(record_t*));
    if (mgr->records == NULL) {
        free(mgr);
        return NULL;
    }

    mgr->max_size = max_size;
    mgr->curr_size = 0;
    pthread_mutex_init(&mgr->lock, NULL);

    return mgr;
}

void destroy_record_manager(record_manager_t *mgr) {
    if (mgr != NULL) {
        for (size_t i = 0; i < mgr->curr_size; ++i) {
            destroy_record(mgr->records[i]);
        }

        free(mgr->records);
        pthread_mutex_destroy(&mgr->lock);
        free(mgr);
    }
}

int add_record(record_manager_t *mgr, record_t *rec) {
    if (pthread_mutex_lock(&mgr->lock)) return -1;

    if (mgr->curr_size >= mgr->max_size) {
        pthread_mutex_unlock(&mgr->lock);
        return -2;
    }

    mgr->records[mgr->curr_size++] = rec;

    if (pthread_mutex_unlock(&mgr->lock)) return -3;

    return 0;
}
