typedef struct {
    char* data;
    time_t timestamp;
} CacheEntry;

static pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;
static CacheEntry cache[1024]; // Simple in-memory cache

size_t writeCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    char* data = (char*)malloc(realsize + 1);
    memcpy(data, contents, realsize);
    data[realsize] = 0; // Null-terminate the string

    CacheEntry entry;
    entry.data = data;
    entry.timestamp = time(NULL);

    pthread_mutex_lock(&cacheMutex);
    cache[hash(url)] = entry; // Simple hash function for demonstration purposes
    pthread_mutex_unlock(&cacheMutex);

    return realsize;
}

CacheEntry fetchAndCacheData(char* url) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        // Handle error
    }

    pthread_mutex_lock(&cacheMutex);
    CacheEntry entry = cache[hash(url)]; // Check the cache first
    pthread_mutex_unlock(&cacheMutex);

    if (entry.data && time(NULL) - entry.timestamp < 3600) { // If data is fresh, return it
        return entry;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
    CURLcode res = curl_easy_perform(curl);

    if (res != CURLE_OK) {
        // Handle error
    }

    curl_easy_cleanup(curl);

    return cache[hash(url)]; // Return the cached data
}
