void initializeDataRecords(char* ciphertext, byte* key, byte* iv, int lowerBound, bool debug) {
    // Decrypt the ciphertext using AES-CBC with provided key and IV
    AES_KEY aesKey;
    AES_set_decrypt_key(key, 128, &aesKey);

    byte* plaintext = malloc(strlen(ciphertext));
    if (debug) printf("Memory allocated for plaintext\n");

    int len = 0;
    while (*ciphertext != '\0') {
        AES_cbc_encrypt((byte*) ciphertext, plaintext, 16, &aesKey, iv, AES_DECRYPT);
        ciphertext += 16;
        len += 16;
    }

    // Allocate memory for and initialize two arrays: one for long offset values and one for int keys
    long* offsets = malloc(sizeof(long) * len / sizeof(int));
    if (debug) printf("Memory allocated for offsets\n");

    int* keys = malloc(sizeof(int) * len);
    if (debug) printf("Memory allocated for keys\n");

    // Allocate memory for and initialize an array of record structures
    record* records = malloc(sizeof(record) * len / sizeof(int));
    if (debug) printf("Memory allocated for records\n");

    // Set the value of each record's int field to a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < len / sizeof(int); i++) {
        records[i].value = rand() % (lowerBound * 2 + 1) - lowerBound;
    }

    // Free memory to prevent leaks
    free(plaintext);
    if (debug) printf("Memory deallocated for plaintext\n");

    free(offsets);
    if (debug) printf("Memory deallocated for offsets\n");

    free(keys);
    if (debug) printf("Memory deallocated for keys\n");

    free(records);
    if (debug) printf("Memory deallocated for records\n");
}
