    profiles = calloc(10000000, sizeof(UserProfile));
    if (profiles == NULL) {
        logToMonitoringSystem("Failed to allocate memory for user profiles.");
        return -1;
    }

    profileCount = 10000000;
    for (size_t i = 0; i < profileCount; ++i) {
        pthread_mutex_init(&profiles[i].lock, NULL);
    }

    return 0;
}

void freeProfiles() {
    if (profiles != NULL) {
        for (size_t i = 0; i < profileCount; ++i) {
            pthread_mutex_destroy(&profiles[i].lock]);

            // Free memory allocated for activity entries.
            free(profiles[i].entries);
        }

        free(profiles);
    }
}

void addActivityEntry(int userId, const ActivityEntry* entry) {
    pthread_rwlock_rdlock(&rwLock);

    if (userId < 0 || userId >= profileCount) {
        logToMonitoringSystem("Invalid user ID.");
        return;
    }

    UserProfile* profile = &profiles[userId];
    pthread_mutex_lock(&profile->lock);

    // Reallocate memory for activity entries.
    ActivityEntry* newEntries = realloc(profile->entries, (profile->count + 1) * sizeof(ActivityEntry));
    if (newEntries == NULL) {
        logToMonitoringSystem("Failed to allocate memory for activity entry.");
        pthread_mutex_unlock(&profile->lock);
        return;
    }

    profile->entries = newEntries;
    memcpy(&profile->entries[profile->count], entry, sizeof(ActivityEntry));
    profile->count++;

    pthread_mutex_unlock(&profile->lock);
    pthread_rwlock_unlock(&rwLock);
}
