        nicb_pool[i].key = rand();

        records_pool[i] = (record*) malloc(sizeof(record));
        if (!records_pool[i]) {
            printf("Memory allocation failed\n");
            exit(1); // Exit the program in case of failure
        }

        records_pool[i]->value = rand();
    }

    pool_size = size;
}

void destroy_nicbs() {
    for (int i = 0; i < pool_size; ++i) {
        free(records_pool[i]);
    }

    free(nicb_pool);
    free(records_pool);
}

// Helper function to find the largest integer in an array
int find_largest(int* arr, int size) {
    int max = arr[0];

    for (int i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    return max;
}

// Thread function to read integers from standard input and find the largest one
void* thread_func(void* arg) {
    int size = 1000; // Assuming a fixed size of 1000 for simplicity
    int* arr = (int*) malloc(size * sizeof(int));

    if (!arr) {
        printf("Memory allocation failed\n");
        pthread_exit(NULL); // Exit the thread in case of failure
    }

    for (int i = 0; i < size; ++i) {
        scanf("%d", &arr[i]);
    }

    int max = find_largest(arr, size);

    printf("Largest integer: %d\n", max);

    free(arr);

    pthread_exit(NULL);
}

int main() {
    init_nicbs(10000); // Initialize 10,000 NICBs

    pthread_t thread;
    if (pthread_create(&thread, NULL, &thread_func, NULL)) {
        printf("Thread creation failed\n");
        return 1; // Exit the program in case of failure
    }

    pthread_join(thread, NULL);

    destroy_nicbs(); // Clean up memory

    return 0;
}
```
