```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

typedef struct LTE_ENB_RRC_MESSAGE_T {
    long offset;
    int key;
    int value;
} LTE_ENB_RRC_MESSAGE_T;

typedef struct DynamicArray {
    LTE_ENB_RRC_MESSAGE_T *array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray *a, size_t initialSize) {
    a->array = (LTE_ENB_RRC_MESSAGE_T *)malloc(initialSize * sizeof(LTE_ENB_RRC_MESSAGE_T));
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL);
}

void insertDynamicArray(DynamicArray *a, LTE_ENB_RRC_MESSAGE_T element) {
    pthread_mutex_lock(&a->lock);
    if (a->used == a->size) {
        a->size *= 2;
        a->array = (LTE_ENB_RRC_MESSAGE_T *)realloc(a->array, a->size * sizeof(LTE_ENB_RRC_MESSAGE_T));
    }
    a->array[a->used++] = element;
    pthread_mutex_unlock(&a->lock);
}

void freeDynamicArray(DynamicArray *a) {
    free(a->array);
    a->array = NULL;
    a->used = a->size = 0;
    pthread_mutex_destroy(&a->lock);
}

int customRandomNumberGenerator() {
    static unsigned int seed = 1234567890;
    srand(seed++);
    return rand();
}
```
This code provides a basic dynamic array with thread safety. It uses the `pthread_mutex_t` to ensure that only one thread can modify the array at a time, preventing race conditions and data corruption. The custom random number generator is used to initialize the 'value' field in the LTE_ENB_RRC_MESSAGE_T structure.

