transaction* create_transaction(char* id, size_t num_items) {
    if (num_items == 0) return NULL;

    transaction* new_trans = malloc(sizeof(transaction));
    if (!new_trans) return NULL;

    new_trans->timestamp = time(NULL);
    new_trans->transaction_id = strdup(id);
    new_trans->num_items = num_items;
    new_trans->items = calloc(num_items, sizeof(item));

    if (!new_trans->items || !new_trans->transaction_id) {
        free(new_trans->items);
        free(new_trans->transaction_id);
        free(new_trans);
        return NULL;
