        new_trans->items[i].product_id = rand();  // Replace with your hash function.
        new_trans->items[i].quantity = rand() % 10 + 1;  // Random quantity between 1 and 10.
    }

    return new_trans;
}

void destroy_transaction(transaction* trans) {
    if (!trans) return;

    free(trans->items);
    free(trans->transaction_id);
    free(trans);
}

int main() {
    pthread_mutex_lock(&lock);  // Lock to ensure thread safety.

    transaction* trans = create_transaction("12345", 5);
    if (!trans) {
