    double amount;
} Transaction;

typedef struct {
    size_t capacity;
    size_t count;
    Transaction* transactions;
    long* timestamps;
    int* ids;
} TransactionsManager;

TransactionsManager* create_transactions_manager(size_t initial_capacity) {
    TransactionsManager* manager = malloc(sizeof(TransactionsManager));
    if (manager == NULL) return NULL;

    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->transactions = calloc(initial_capacity, sizeof(Transaction));
    manager->timestamps = malloc(sizeof(long) * initial_capacity);
    manager->ids = malloc(sizeof(int) * initial_capacity);

    if (manager->transactions == NULL || manager->timestamps == NULL || manager->ids == NULL) {
        free(manager->transactions);
        free(manager->timestamps);
        free(manager->ids);
        free(manager);
        return NULL;
    }

    srand((unsigned int) time(NULL));

    return manager;
}

int add_transaction(TransactionsManager* manager, long timestamp, double amount) {
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Transaction* new_transactions = realloc(manager->transactions, sizeof(Transaction) * new_capacity);
        long* new_timestamps = realloc(manager->timestamps, sizeof(long) * new_capacity);
        int* new_ids = realloc(manager->ids, sizeof(int) * new_capacity);

        if (new_transactions == NULL || new_timestamps == NULL || new_ids == NULL) {
            return -1; // Error code for memory allocation failure
        }

        manager->transactions = new_transactions;
        manager->timestamps = new_timestamps;
        manager->ids = new_ids;
        manager->capacity = new_capacity;
    }

    int transaction_id = rand(); // Generate a random transaction ID
    while (transaction_exists(manager, transaction_id)) {
        transaction_id = rand();
    }

    size_t index = manager->count++;
    manager->transactions[index].timestamp = timestamp;
    manager->timestamps[index] = timestamp;
    manager->ids[index] = transaction_id;
    manager->transactions[index].transaction_id = transaction_id;
    manager->transactions[index].amount = amount;

    return 0; // Success code
}

int delete_transaction(TransactionsManager* manager, int transaction_id) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->transactions[i].transaction_id == transaction_id) {
            // Shift all elements after the deleted one to fill the gap
            memmove(&manager->transactions[i], &manager->transactions[i + 1], 
                    sizeof(Transaction) * (manager->count - i - 1));
            memmove(&manager->timestamps[i], &manager->timestamps[i + 1], 
                    sizeof(long) * (manager->count - i - 1));
            memmove(&manager->ids[i], &manager->ids[i + 1], 
                    sizeof(int) * (manager->count - i - 1));

            --manager->count;
            return 0; // Success code
        }
    }

    return -2; // Error code for transaction not found
}

// Helper function to check if a transaction with the given ID exists in the manager
int transaction_exists(TransactionsManager* manager, int transaction_id) {
