typedef struct {
    char *line;
    int length;
} LineData;

void* processFile(void *arg) {
    FILE *file = fopen((char*) arg, "r");
    if (file == NULL) {
        printf("Failed to open file: %s\n", (char*) arg);
        return NULL;
    }

    char buffer[256];
    while(fgets(buffer, sizeof(buffer), file)) {
        LineData *data = malloc(sizeof(LineData));
        data->length = strlen(buffer);
        data->line = malloc(data->length + 1);
        strcpy(data->line, buffer);

        // Process line here...
    }

    fclose(file);
    return NULL;
}

int main() {
    const char *filenames[] = {"file1.txt", "file2.txt"};
    int numFiles = sizeof(filenames) / sizeof(char*);

    pthread_t threads[numFiles];
    for (int i = 0; i < numFiles; ++i) {
        if (pthread_create(&threads[i], NULL, processFile, (void*) filenames[i])) {
            printf("Failed to create thread\n");
            return 1;
        }
    }

    for (int i = 0; i < numFiles; ++i) {
        if (pthread_join(threads[i], NULL)) {
            printf("Failed to join thread\n");
            return 1;
        }
    }

    return 0;
}
