["Here's a basic implementation of your requirements using C language. This code does not include all the features you requested, but it provides a starting point and shows how to handle some of the complexities you mentioned. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
} record;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    record* records;
    long* offsets;
    int* keys;
} RecordCollection;

RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection* collection = malloc(sizeof(RecordCollection));
    if (collection == NULL) return NULL;

    pthread_mutex_init(&collection->lock, NULL);
    collection->records = calloc(initial_capacity, sizeof(record));
    collection->offsets = malloc(sizeof(long) * initial_capacity);
    collection->keys = malloc(sizeof(int) * initial_capacity);

    if (collection->records == NULL || collection->offsets == NULL || collection->keys == NULL) {
        free(collection->records);
        free(collection->offsets);
        free(collection->keys);
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    srand(time(NULL)); // seed the random number generator

    return collection;
}

int add_record(RecordCollection* collection, long offset, int key) {
    if (collection == NULL) return -1;

    pthread_mutex_lock(&collection->lock);

    // check if we need to resize the array
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        record* new_records = realloc(collection->records, sizeof(record) * new_capacity);
        long* new_offsets = realloc(collection->offsets, sizeof(long) * new_capacity);
        int* new_keys = realloc(collection->keys, sizeof(int) * new_capacity);

        if (new_records == NULL || new_offsets == NULL || new_keys == NULL) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // failed to resize the array
        }

        collection->records = new_records;
        collection->offsets = new_offsets;
        collection->keys = new_keys;
        collection->capacity = new_capacity;
    }

    // add the record
    collection->records[collection->count].offset = offset;
    collection->offsets[collection->count] = offset;
    collection->records[collection->count].key = key;
    collection->keys[collection->count] = key;
    collection->records[collection->count].value = rand(); // set a random value
    ++collection->count;

    pthread_mutex_unlock(&collection->lock);

    return 0; // success
}

// similar to add_record, but with deletion logic
int delete_record(RecordCollection* collection, long offset) {
    if (collection == NULL) return -1;

    pthread_mutex_lock(&collection->lock);

    // find the record and shift all records after it to fill the gap
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->offsets[i] == offset) {
            --collection->count;

            for (size_t j = i; j < collection->count; ++j) {
                collection->records[j] = collection->records[j + 1];
                collection->offsets[j] = collection->offsets[j + 1];
                collection->keys[j] = collection->keys[j + 1];
            }

            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);

    return 0; // success
}
```
This code provides a basic implementation of the record collection with thread safety and dynamic resizing. It does not include persistent storage, data compression, error recovery or concurrency management for multiple threads. You would need to add these features yourself based on your specific requirements.
"]

