#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NICB {
    int data;
    pthread_mutex_t lock;
} NICB;

NICB* allocate_nicb(int size) {
    NICB* nicbs = malloc(size * sizeof(NICB));
    if (nicbs == NULL) {
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        pthread_mutex_init(&nicbs[i].lock, NULL);
    }

    return nicbs;
}

void deallocate_nicb(NICB* nicbs, int size) {
    for (int i = 0; i < size; ++i) {
        pthread_mutex_destroy(&nicbs[i].lock);
    }

    free(nicbs);
}

void read_data(NICB* nicb, int data) {
    pthread_mutex_lock(&nicb->lock);
    nicb->data = data;
    pthread_mutex_unlock(&nicb->lock);
}

int find_largest(NICB* nicbs, int size) {
    int largest = nicbs[0].data;

    for (int i = 1; i < size; ++i) {
        pthread_mutex_lock(&nicbs[i].lock);
        if (nicbs[i].data > largest) {
            largest = nicbs[i].data;
        }
        pthread_mutex_unlock(&nicbs[i].lock);
    }

    return largest;
}

int main() {
    srand(time(NULL));

    NICB* nicbs = allocate_nicb(10000);
    if (nicbs == NULL) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    for (int i = 0; i < 10000; ++i) {
        read_data(&nicbs[i], rand() % 100);
    }

    int largest = find_largest(nicbs, 10000);
    printf("Largest number: %d\n", largest);

    deallocate_nicb(nicbs, 10000);

    return 0;
}
```
