['Here is a basic implementation of your task in C language. This code does not include all the features you mentioned, but it provides a starting point for further development. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    double data;
    struct Node* next;
} Node;

typedef struct Measure {
    double value;
    char status;
} Measure;

Node* create_node(double data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

int append(Node** head, double data) {
    Node* new_node = create_node(data);
    if (!new_node) {
        return 0;
    }

    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    return 1;
}

double average(Node* head, int count) {
    double sum = 0.0;
    Node* current = head;
    while (current != NULL) {
        sum += current->data;
        current = current->next;
    }

    return sum / count;
}

int main(int argc, char** argv) {
    Node* head = NULL;
    Measure measures[argc - 1];

    for (int i = 0; i < argc - 1; ++i) {
        double data = atof(argv[i + 1]);

        if (!append(&head, data)) {
            printf("Failed to append node.\n");
            return EXIT_FAILURE;
        }

        measures[i].value = data;
        measures[i].status = 'V';  // Valid status
    }

    double avg = average(head, argc - 1);
    printf("Average: %f\n", avg);

    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    return EXIT_SUCCESS;
}
```
This code reads floating point numbers from the command line arguments, stores them in a linked list and an array of 'measure' structures. It then calculates and prints their average. The memory allocated for the linked list is deallocated at the end to prevent leaks. 

