typedef struct {
    const char* hostname;
    const char* password;
    const char* charset;
    const char* configDirPath;
} FetchConfigAndHashParams;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* fetchConfig(void* params) {
    FetchConfigAndHashParams* p = (FetchConfigAndHashParams*)params;

    // Read the configuration file asynchronously.
    char configPath[256];
    snprintf(configPath, sizeof(configPath), "%s/config", p->configDirPath);

    FILE* fp = fopen(configPath, "r");
    if (fp == NULL) {
        perror("Failed to open configuration file");
        return NULL;
    }

    // Parse the configuration file.
    char algorithm[256];
    int res = fscanf(fp, "algorithm=%s", algorithm);
    if (res != 1) {
        perror("Failed to parse configuration file");
        return NULL;
    }

    // Release the lock and return the hashing algorithm.
    pthread_mutex_unlock(&lock);
    char* result = malloc(strlen(algorithm) + 1);
    strcpy(result, algorithm);
    fclose(fp);
    return result;
}

int fetchConfigAndHash(const char* hostname, const char* password, const char* charset, const char* configDirPath) {
    FetchConfigAndHashParams params = {hostname, password, charset, configDirPath};

    // Perform DNS resolution.
    struct hostent *he;
    if ((he=gethostbyname(hostname)) == NULL) {
        herror("Failed to resolve hostname");
        return -1;
    }

    u_char* ip = malloc(sizeof(u_char)*4);
    memcpy(ip, he->h_addr_list[0], 4);

    // Generate a random string.
    srand(time(NULL));
    int len = strlen(hostname) + strlen(password);
    char* randStr = malloc(len + 1);
    for (int i = 0; i < len; ++i) {
        randStr[i] = charset[rand() % strlen(charset)];
    }
    randStr[len] = '\0';

    // Hash the password.
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)password, strlen(password), hash);

    // Fetch the configuration file asynchronously.
    pthread_t thread;
    if (pthread_create(&thread, NULL, fetchConfig, &params) != 0) {
        perror("Failed to create thread");
        return -1;
    }

    // Wait for the configuration file retrieval to complete.
    pthread_mutex_lock(&lock);
    pthread_join(thread, NULL);

    free(ip);
    free(randStr);
    return 0;
}
```
