    indexmap->entries = calloc(indexmap->capacity, sizeof(Entry*));
    if (indexmap->entries == NULL) {
        free(indexmap);
        return NULL;
    }

    pthread_mutex_init(&indexmap->lock, NULL);

    return indexmap;
}

