    free(indexmap->entries);
    pthread_mutex_destroy(&indexmap->lock);
    free(indexmap);
}

void insert_entry(IndexMap* indexmap, Entry* entry) {
    pthread_mutex_lock(&indexmap->lock);

    if (indexmap->count == indexmap->capacity) {
        // reallocate entries array with double capacity
        size_t new_capacity = indexmap->capacity * 2;
        Entry** new_entries = calloc(new_capacity, sizeof(Entry*));

        if (new_entries == NULL) {
            pthread_mutex_unlock(&indexmap->lock);
            return;
        }

        memcpy(new_entries, indexmap->entries, indexmap->capacity * sizeof(Entry*));
        free(indexmap->entries);
        indexmap->entries = new_entries;
        indexmap->capacity = new_capacity;
    }

    indexmap->entries[indexmap->count++] = entry;

    pthread_mutex_unlock(&indexmap->lock);
}
