IndexMap* create_indexmap() {
    IndexMap* map = malloc(sizeof(IndexMap));
    if (map == NULL) return NULL;

    pthread_mutex_init(&map->lock, NULL);
    map->count = 0;
    map->capacity = 16; // initial capacity
    map->entries = malloc(sizeof(Entry*) * map->capacity);

    return map;
