void destroy_indexmap(IndexMap* map) {
    for (size_t i = 0; i < map->count; ++i) {
        free(map->entries[i]->str);
        free(map->entries[i]);
    }

    pthread_mutex_destroy(&map->lock);
    free(map->entries);
    free(map);
}

void resize_indexmap(IndexMap* map, size_t new_capacity) {
    Entry** new_entries = malloc(sizeof(Entry*) * new_capacity);

    memcpy(new_entries, map->entries, sizeof(Entry*) * map->count);

    free(map->entries);
    map->entries = new_entries;
    map->capacity = new_capacity;
}

void add_entry(IndexMap* map, Entry* entry) {
    pthread_mutex_lock(&map->lock);

    if (map->count == map->capacity) {
        resize_indexmap(map, map->capacity * 2); // double capacity when full
    }

    map->entries[map->count++] = entry;

    pthread_mutex_unlock(&map->lock);
}

Entry* get_entry(IndexMap* map, int key) {
    pthread_mutex_lock(&map->lock);

    for (size_t i = 0; i < map->count; ++i) {
        if (map->entries[i]->key == key) {
            ++(map->entries[i]->refcount); // increment reference count
            pthread_mutex_unlock(&map->lock);
            return map->entries[i];
        }
    }

    pthread_mutex_unlock(&map->lock);
    return NULL; // entry not found
}

void remove_entry(IndexMap* map, int key) {
    pthread_mutex_lock(&map->lock);

    for (size_t i = 0; i < map->count; ++i) {
        if (map->entries[i]->key == key && --(map->entries[i]->refcount) == 0) { // decrement reference count and check if zero
            free(map->entries[i]->str);

            // move last entry to the removed position to keep array contiguous
            map->entries[i] = map->entries[--map->count]; 

            break;
        }
    }

    if (map->count < map->capacity / 4) {
        resize_indexmap(map, map->capacity / 2); // halve capacity when using less than a quarter of the array
    }

    pthread_mutex_unlock(&map->lock);
}
