['Here's a basic implementation of your task using C language. This code is quite complex and requires a good understanding of C programming, pointers, threads, memory management, error handling, etc. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct measure {
    double value;
    char status;
    int index;
} Measure;

typedef struct node {
    double number;
    time_t insertionTime;
    struct node *next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node *head = NULL;
Measure *measures = NULL;
int measureCount = 0;

void* readFile(void *arg) {
    char *filename = (char*) arg;
    FILE *file = fopen(filename, "r");

    if (file == NULL) {
        printf("Failed to open file %s\n", filename);
        return NULL;
    }

    double number;
    while (fscanf(file, "%lf", &number) == 1) {
        Node *newNode = malloc(sizeof(Node));

        if (newNode == NULL) {
            printf("Failed to allocate memory for new node\n");
            fclose(file);
            return NULL;
        }

        newNode->number = number;
        time(&newNode->insertionTime);

        pthread_mutex_lock(&lock);
        newNode->next = head;
        head = newNode;
        pthread_mutex_unlock(&lock);
    }

    fclose(file);
    return NULL;
}

int verifyData() {
    Node *current = head;
    while (current != NULL) {
        if (current->number < 0 || current->insertionTime == 0) {
            printf("Invalid data in linked list\n");
            return 1;
        }

        current = current->next;
    }

    for (int i = 0; i < measureCount; ++i) {
        if (measures[i].value < 0 || measures[i].status == 0 || measures[i].index < 0) {
            printf("Invalid data in array of measures\n");
            return 1;
        }
    }

    return 0;
}

double calculateAverage(int count, char **numbers) {
    double sum = 0.0;

    for (int i = 0; i < count; ++i) {
        sum += atof(numbers[i]);
    }

    return sum / count;
}

void cleanup() {
    Node *current = head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }

    if (measures != NULL) {
        free(measures);
    }
}

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("Usage: %s <file1> <file2> ...\n", argv[0]);
        return 1;
    }

    measureCount = argc - 2;
    measures = malloc(measureCount * sizeof(Measure));

    if (measures == NULL) {
        printf("Failed to allocate memory for array of measures\n");
        cleanup();
        return 1;
    }

    pthread_t threads[argc - 2];
    int threadCount = 0;

    for (int i = 0; i < measureCount; ++i) {
        if (pthread_create(&threads[threadCount], NULL, readFile, argv[i + 1]) == 0) {
            ++threadCount;
        } else {
            printf("Failed to create thread for file %s\n", argv[i + 1]);
        }
    }

    for (int i = 0; i < threadCount; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (verifyData() != 0) {
        cleanup();
        return 1;
    }

    double average = calculateAverage(argc - 2, argv + 2);
    printf("The average of the numbers is: %.2lf\n", average);

    cleanup();
    return 0;
}
```
This code does not include logging or error handling for file access failures and memory allocation failures. It also doesn't handle edge cases such as empty files or files with invalid data. You would need to add these features yourself, depending on your specific requirements.
']

['Here is an example of how you might implement this in C++. This code does not cover all the requirements, but it provides a starting point for your implementation. 

```cpp
#include <random>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <spdlog/spdlog.h>

namespace RandomService {
    class RandomGeneratorPool {
        public:
            RandomGeneratorPool(size_t size) : generators_(size), nextIndex_(0) {}
            ~RandomGeneratorPool() = default;

            void resize(size_t newSize) {
                std::lock_guard<std::mutex> lock(mtx_);
                generators_.resize(newSize);
            }

            int getNextNumber() {
                std::unique_lock<std::mutex> lock(mtx_);
                condVar_.wait(lock, [this] { return !generators_.empty(); });

                auto index = nextIndex_;
                nextIndex_ = (nextIndex_ + 1) % generators_.size();

                lock.unlock();
                int number = generators_[index].getNextNumber();
                spdlog::info("Generated number: {}", number);
                return number;
            }

        private:
            class Generator {
                public:
                    Generator() : gen_(std::random_device{}()) {}
                    ~Generator() = default;

                    int getNextNumber() {
                        std::uniform_int_distribution<> dis(0, 100);
                        return dis(gen_);
                    }
                private:
                    std::mt19937 gen_;
            };

            std::vector<Generator> generators_;
            size_t nextIndex_;
            std::mutex mtx_;
            std::condition_variable condVar_;
    };
}
```
This code creates a pool of random number generators that can be resized dynamically. Each generator is initialized with a unique seed value, ensuring thread safety and efficiency under high concurrency. The `getNextNumber` method retrieves the next random number from the pool in a round-robin fashion. 

