```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Node {
    double value;
    struct Node* next;
} Node;

typedef struct Measure {
    double value;
    char status;
} Measure;

Node* head = NULL;
Measure* measures = NULL;
int measure_count = 0;
pthread_mutex_t lock;

void addToList(double val) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if(newNode == NULL) exit(-1); // error handling

    newNode->value = val;
    newNode->next = head;

    pthread_mutex_lock(&lock);
    head = newNode;
    pthread_mutex_unlock(&lock);
}

void addToMeasures(double val, char status) {
    measures[measure_count].value = val;
    measures[measure_count].status = status;

    measure_count++;
}

int readFileAndFilterData(char* filename, double min, double max) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) return -1; // error handling

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        double val = atof(line);

        pthread_mutex_lock(&lock);
        if(val >= min && val <= max) {
            addToList(val);
            addToMeasures(val, 'V'); // valid data
        } else {
            addToMeasures(val, 'I'); // invalid data
        }
        pthread_mutex_unlock(&lock);
    }

    fclose(file);
    return 0;
}

double calculateAverage() {
    double sum = 0.0;
    int count = 0;

    Node* node = head;
    while (node != NULL) {
        sum += node->value;
        count++;
        node = node->next;
    }

    return sum / count;
}

int main(int argc, char *argv[]) {
    if (pthread_mutex_init(&lock, NULL) != 0) exit(-1); // error handling

    measures = malloc(sizeof(Measure) * 1000); // assuming max 1000 data points for now
    if(measures == NULL) exit(-1); // error handling

    double min = 0.0, max = 100.0; // example thresholds

    int ret = readFileAndFilterData("data.txt", min, max);
    if (ret != 0) return -1; // error handling

    printf("Average: %f\n", calculateAverage());

    pthread_mutex_destroy(&lock);
    free(measures);

    Node* node = head;
    while (node != NULL) {
        Node* temp = node;
        node = node->next;
        free(temp);
    }

    return 0;
}
```
