        return 0; // invalid
    }

    for (size_t i = 0; i < fieldCount; ++i) {
        if (record->dynamicField[i] < 0) {
            return 0; // invalid
        }
    }

    return 1; // valid
}

int processRecords(size_t recordCount, size_t fieldCount) {
    Record* records = malloc(recordCount * sizeof(Record));
    if (records == NULL) {
        return 0; // allocation failure
    }

    for (size_t i = 0; i < recordCount; ++i) {
        records[i].timestamp = time(NULL);
        records[i].statusFlag = 1;

        records[i].dynamicField = malloc(fieldCount * sizeof(char));
        if (records[i].dynamicField == NULL) {
            // Free any previously allocated memory and return failure.
            for (size_t j = 0; j < i; ++j) {
                free(records[j].dynamicField);
            }
            free(records);
            return 0; // allocation failure
        }

        if (!validateRecord(&records[i], fieldCount)) {
            // Free any previously allocated memory and return failure.
            for (size_t j = 0; j <= i; ++j) {
                free(records[j].dynamicField);
            }
            free(records);
            return 0; // initialization error
        }
    }

    int* array = malloc(recordCount * sizeof(int));
    if (array == NULL) {
        // Free any previously allocated memory and return failure.
        for (size_t i = 0; i < recordCount; ++i) {
            free(records[i].dynamicField);
        }
        free(records);
        return 0; // allocation failure
    }

    for (size_t i = 0; i < recordCount; ++i) {
        array[i] = records[i].statusFlag;
    }

    int largest = findLargest(array, recordCount);
    printf("The largest integer is: %d\n", largest);

    free(array);
    for (size_t i = 0; i < recordCount; ++i) {
        free(records[i].dynamicField);
    }
    free(records);

    return 1; // success
