    time_t modification_time;
    mode_t permissions;
} file_metadata;

typedef struct record {
    char* filename;
    long filesize;
} record;

int initialize(double** doubleArray, char*** stringArray, file_metadata*** metadataArray, 
               record*** recordsArray, int size, int maxFilenameLength) {

    srand((unsigned int)time(NULL)); // seed the random number generator

    *doubleArray = (double*)malloc(sizeof(double)*size);
    if (*doubleArray == NULL) return -1;

    *stringArray = (char**)malloc(sizeof(char*)*size);
    if (*stringArray == NULL) { free(*doubleArray); return -1; }

    *metadataArray = (file_metadata**)malloc(sizeof(file_metadata*)*size);
    if (*metadataArray == NULL) { free(*doubleArray); free(*stringArray); return -1; }

    *recordsArray = (record**)malloc(sizeof(record*)*size);
    if (*recordsArray == NULL) { free(*doubleArray); free(*stringArray); free(*metadataArray); return -1; }

    for (int i = 0; i < size; ++i) {
        (*doubleArray)[i] = rand() % 100 + 1; // random double precision number between 1 and 100

        (*stringArray)[i] = (char*)malloc(sizeof(char)*maxFilenameLength);
        if ((*stringArray)[i] == NULL) { free(*doubleArray); free(*stringArray); free(*metadataArray); free(*recordsArray); return -1; }

        // generate a unique filename for each record
        sprintf((*stringArray)[i], "file_%d", i); 

        (*metadataArray)[i] = (file_metadata*)malloc(sizeof(file_metadata));
        if ((*metadataArray)[i] == NULL) { free(*doubleArray); free(*stringArray); free(*metadataArray); free(*recordsArray); return -1; }

        (*metadataArray)[i]->size = rand() % 1024 + 1; // random file size between 1 and 1024
        (*metadataArray)[i]->modification_time = time(NULL); // current timestamp
        (*metadataArray)[i]->permissions = 0644; // default permissions

        (*recordsArray)[i] = (record*)malloc(sizeof(record));
        if ((*recordsArray)[i] == NULL) { free(*doubleArray); free(*stringArray); free(*metadataArray); free(*recordsArray); return -1; }

        (*recordsArray)[i]->filename = (char*)malloc(sizeof(char)*maxFilenameLength);
        if ((*recordsArray)[i]->filename == NULL) { free(*doubleArray); free(*stringArray); free(*metadataArray); free(*recordsArray); return -1; }

        strcpy((*recordsArray)[i]->filename, (*stringArray)[i]); // copy filename to record
        (*recordsArray)[i]->filesize = (*metadataArray)[i]->size; // set filesize in record
    }

    return 0;
}
