    size_t imageSize = metadata->width * metadata->height;
    if (imageSize > MAX_IMAGE_SIZE) {
        printf("Image size exceeds maximum limit\n");
        free(metadata);
        return;
    }

    pixel** pixels = malloc(sizeof(pixel*) * metadata->height);
    for (int i = 0; i < metadata->height; ++i) {
        pixels[i] = malloc(sizeof(pixel) * metadata->width);
    }

    // Assuming each pixel is stored as 3 bytes: red, green, blue
    for (int y = 0; y < metadata->height; ++y) {
        fread(pixels[y], sizeof(pixel), metadata->width, file);
    }

    // Logging metadata and a preview of the first few pixels
    printf("Image dimensions: %dx%d\n", metadata->width, metadata->height);
    printf("File format: %s\n", metadata->format);
    printf("Creation date: %ld\n", (long)metadata->creationDate);

    for (int y = 0; y < metadata->height && y < 5; ++y) {
        for (int x = 0; x < metadata->width && x < 5; ++x) {
            printf("Pixel at (%d, %d): R=%u G=%u B=%u\n", 
                   x, y, pixels[y][x].red, pixels[y][x].green, pixels[y][x].blue);
        }
    }

    // Free memory
    for (int i = 0; i < metadata->height; ++i) {
        free(pixels[i]);
    }
    free(pixels);
    free(metadata);
}
```
