['Here is a basic implementation of your requirements using C language. This code does not include all the features you requested but it provides a good starting point for further development and optimization. 

```c
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    int key;
    long offset;
    double value;
} Record;

typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

Node *head = NULL;
int size = 0;

void insert(Record *record) {
    Node *node = (Node *) malloc(sizeof(Node));
    node->record = record;
    node->next = head;
    head = node;
    size++;
}

void delete(int key) {
    if (head == NULL) return;

    Node *temp = head, *prev = NULL;
    while (temp != NULL && temp->record->key != key) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;

    if (prev != NULL)
        prev->next = temp->next;

    if (temp == head)
        head = head->next;

    free(temp);
    size--;
}

Record *query(int key) {
    Node *node = head;

    while (node != NULL) {
        if (node->record->key == key)
            return node->record;

        node = node->next;
    }

    return NULL;
}

void batchInsert(Record **records, int count) {
    for (int i = 0; i < count; i++) {
        insert(records[i]);
    }
}

void batchDelete(int *keys, int count) {
    for (int i = 0; i < count; i++) {
        delete(keys[i]);
    }
}
```
This code uses a linked list to store the records. Each node in the list contains a pointer to a `Record` struct which holds the key, offset and value of each record. The `insert()` function adds a new record at the beginning of the list, while the `delete()` function removes a record by its key. The `query()` function retrieves a record by its key.

The `batchInsert()` and `batchDelete()` functions allow for efficient insertion or deletion of multiple records at once. These functions take arrays of pointers to `Record` structs and integers as arguments, respectively.

