import org.apache.commons.codec.digest.DigestUtils;

public class ObjectProcessor {
    private static final int MAX_OBJECT_SIZE = 1024 * 1024; // 1MB

    public static List<Object> processByteArray(byte[] compressedBytes) throws IOException, ClassNotFoundException {
        Inflater decompresser = new Inflater();
        ByteArrayOutputStream bos = new ByteArrayOutputStream(compressedBytes.length);

        decompresser.setInput(compressedBytes);
        byte[] buffer = new byte[MAX_OBJECT_SIZE];
        List<Object> objects = new ArrayList<>();
        int resultLength;

        while (!decompresser.finished()) {
            try {
                resultLength = decompresser.inflate(buffer);

                if (resultLength == 0) {
                    break;
                } else {
                    ByteArrayInputStream bis = new ByteArrayInputStream(buffer, 0, resultLength);

                    ObjectInputStream ois = new ObjectInputStream(bis);
                    Object obj = ois.readObject();

                    // Verify object integrity here if needed

                    objects.add(obj);
                }
            } catch (IOException | ClassNotFoundException e) {
                System.out.println("Failed to deserialize an object: " + e.getMessage());
            }
        }

        decompresser.end();
        return objects;
    }
}
```
