void add_record(DynamicArray* array, Record record) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t newCapacity = array->capacity == 0 ? 1 : array->capacity * 2;
        Record* newRecords = realloc(array->records, sizeof(Record) * newCapacity);

        if (newRecords == NULL) {
            pthread_mutex_unlock(&array->lock);
            return;
        }

        array->records = newRecords;
        array->capacity = newCapacity;
    }

    array->records[array->count++] = record;

    pthread_mutex_unlock(&array->lock);
}

