['Here is a high level implementation of your requirements using Python, Redis as a distributed caching system, and json library for JSON serialization. 

```python
import threading
import time
import random
import string
import json
from collections import Counter
import redis

class Cache:
    def __init__(self):
        self.redis = redis.Redis(host='localhost', port=6379, db=0)
        self.lock = threading.Lock()

    def generate_key(self):
        with self.lock:
            return ''.join(random.choices(string.ascii_uppercase + string.digits, k=16))

    def generate_value(self):
        value = {
            "timestamp": time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
            "id": self.generate_key(),
            "tags": [self.generate_key() for _ in range(random.randint(1, 5))],
        }
        return json.dumps(value)

    def generate_keys_and_values(self):
        num_keys = random.randint(1000, 10000)
        keys = [self.generate_key() for _ in range(num_keys)]
        values = {key: self.generate_value() for key in keys}
        return keys, values

    def add_to_cache(self, keys, values):
        with self.lock:
            pipe = self.redis.pipeline()
            for key, value in zip(keys, values.values()):
                pipe.setnx(key, value)  # set if not exists
            result = pipe.execute()
            return sum(result)

    def report(self, keys, values):
        total_keys = len(keys)
        versions = [json.loads(value).get('version', 0) for value in values.values()]
        average_version = sum(versions) / len(versions)
        key_types = Counter([key[:4] for key in keys])
        return {
            "total_keys": total_keys,
            "average_version": average_version,
            "key_type_distribution": dict(key_types),
        }
```
