```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::fs;
use std::path::PathBuf;
use std::thread;
use std::time::Instant;
use log::LevelFilter;
use env_logger;

struct ConfigManager {
    configs: Arc<Mutex<HashMap<String, String>>>,
}

impl ConfigManager {
    fn new() -> Self {
        let configs = Arc::new(Mutex::new(HashMap::new()));
        env_logger::builder().filter_level(LevelFilter::Info).init();

        Self { configs }
    }

    fn load(&self, path: PathBuf) -> Option<String> {
        if let Ok(contents) = fs::read_to_string(path) {
            Some(contents)
        } else {
            None
        }
    }

    fn update(&self, path: PathBuf, contents: String) -> bool {
        if let Ok(_) = fs::write(path, contents) {
            true
        } else {
            false
        }
    }

    fn get_config(&self, key: &str) -> Option<String> {
        let configs = self.configs.lock().unwrap();
        configs.get(key).cloned()
    }

    fn set_config(&self, key: String, value: String) {
        let mut configs = self.configs.lock().unwrap();
        configs.insert(key, value);
    }
}

fn main() {
    let manager = ConfigManager::new();

    // Simulate multiple threads updating the same file concurrently
    let path = PathBuf::from("config.txt");
    let start = Instant::now();
    for _ in 0..10_000 {
        let thread = manager.clone();
        thread::spawn(move || {
            if let Some(contents) = thread.load(path.clone()) {
                // Modify the contents here...

                thread.update(path, contents);
            }
        });
    }

    println_timing("Concurrent updates", start);
}

fn print_timing(name: &str, start: Instant) {
    let duration = start.elapsed();
    println_log(&format_args_timing(name, duration));
}

fn format_args_timing(name: &str, duration: std::time::Duration) -> String {
    format_args_log(&format_args_log("{} took {}ms", name, duration.as_millis()))
}
```
