void initialize_data(long* offsets, int* keys, record** records, size_t size, int min, int max) {
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = i * sizeof(int);
        keys[i] = seed_function(time(NULL));
        records[i]->value = min + rand() % (max - min + 1);
    }
}

void free_data(long* offsets, int* keys, record** records, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}

int find_max(int* array, size_t size) {
    assert(size > 0);

    int max = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

int main() {
    size_t size = 10;

    long* offsets = malloc(size * sizeof(long));
    int* keys = malloc(size * sizeof(int));
    record** records = malloc(size * sizeof(record*));
    for (size_t i = 0; i < size; ++i) {
