    if (!data->offsets || !data->keys || !data->records) {
        freeDataStructures(data);
        return NULL;
    }

    seedFunction(seed);
    for (size_t i = 0; i < size; ++i) {
        data->offsets[i] = randomIntInRange(1, 100);
        data->keys[i] = randomIntInRange(1, 100);

        Record* record = malloc(sizeof(Record));
        if (!record) {
            freeDataStructures(data);
            return NULL;
        }

        record->value = randomIntInRange(1, 100);
        data->records[i] = record;
    }

    pthread_mutex_init(&data->lock, NULL);
    data->size = size;
    return data;
}

void freeDataStructures(DataStructures* data) {
    if (!data) {
        return;
    }

    for (size_t i = 0; i < data->size; ++i) {
        free(data->records[i]);
    }

    free(data->offsets);
    free(data->keys);
    free(data->records);
    pthread_mutex_destroy(&data->lock);
    free(data);
}
