#include <stdlib.h>
#include <pthread.h>
#include <syslog.h>

typedef struct Record {
    int *key;
    long *offset;
    size_t refCount;
} Record;

Record **records = NULL;
size_t recordCount = 0;
pthread_mutex_t lock;

int init() {
    srand(time(NULL));
    if (pthread_mutex_init(&lock, NULL) != 0) {
        syslog(LOG_ERR, "Failed to initialize mutex");
        return -1;
    }

    openlog("RecordManager", LOG_PID | LOG_CONS, LOG_USER);
    return 0;
}

int createRecord() {
    pthread_mutex_lock(&lock);

    Record *record = malloc(sizeof(Record));
    if (record == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for record");
        return -1;
    }

    int keyVal = rand() % 1000 + 1; // Random value between 1 and 1000
    long offsetVal = rand();

    record->key = malloc(sizeof(int));
    if (record->key == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for key");
        return -1;
    }

    *(record->key) = keyVal;
    record->offset = malloc(sizeof(long));
    if (record->offset == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for offset");
        return -1;
    }

    *(record->offset) = offsetVal;
    record->refCount = 0;

    records = realloc(records, sizeof(Record *) * (recordCount + 1));
    if (records == NULL) {
        syslog(LOG_ERR, "Failed to reallocate memory for records");
        return -1;
    }

    records[recordCount++] = record;

    syslog(LOG_INFO, "Record created with key %d and offset %ld", keyVal, offsetVal);

    pthread_mutex_unlock(&lock);
    return 0;
}

// Similar functions for deleteRecord, updateRecord etc.
