int addToCollection(Collection* collection, Record* record) {
    pthread_mutex_lock(&collection->lock);

    Record** newRecords = realloc(collection->records, (collection->count + 1) * sizeof(Record*));
    if (!newRecords) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&collection->lock);
        return -ENOMEM;
    }

    collection->records = newRecords;
    collection->records[collection->count] = record;
    collection->count++;

    pthread_mutex_unlock(&collection->lock);

    return 0;
}

Record* getFromCollection(Collection* collection, size_t index) {
    if (index >= collection->count) {
        // Handle out of bounds access
        return NULL;
    }

    pthread_mutex_lock(&collection->lock);

