            fclose(fp);
            return NULL;
        }

        pthread_mutex_init(&(monitors[i]->lock), NULL);

        // Read data from CSV file and initialize monitor
        CsvRow *row = CsvGetRow(fp);
        if (row == NULL) {
            printf("Failed to read row from CSV\n");
            // Free all previously allocated memory and return
            for (int j = 0; j <= i; j++) {
