    char* destIP;
    int bytesTransferred;
} TCP_CONNECTION_STATS;

typedef struct node {
    int key;
    struct node *next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* seedFunction(int seed) {
    srand(seed);
}

double findMedian(int a[], int n) { 
    sort(a, a+n); 

    if (n % 2 != 0) 
        return (double)a[n/2]; 

    return (double)(a[(n-1)/2] + a[n/2])/2.0; 
} 

gboolean initializeMemory(int numEntities, int minKey, int maxKey) {
    TCP_CONNECTION_STATS* connections = malloc(numEntities * sizeof(TCP_CONNECTION_STATS));
    if (connections == NULL) return FALSE;

    Node* head = NULL;
    for (int i = 0; i < numEntities; ++i) {
        pthread_mutex_lock(&lock);

        connections[i].sourceIP = malloc(16 * sizeof(char)); // Assuming IPV4
        connections[i].destIP = malloc(16 * sizeof(char)); 
        if (connections[i].sourceIP == NULL || connections[i].destIP == NULL) {
            pthread_mutex_unlock(&lock);
            return FALSE;
        }

        Node* newNode = malloc(sizeof(Node));
        if (newNode == NULL) {
            pthread_mutex_unlock(&lock);
            return FALSE;
        }
        newNode->key = minKey + rand() % (( maxKey + 1 ) - minKey); // Random key generation

        pthread_mutex_unlock(&lock);

        newNode->next = head; 
        head = newNode; 
    }

    return TRUE;
}
