["Here is a basic implementation of your requirements using AngularJS and JavaScript. This code assumes you have an external API for fetching refresh data. 

```javascript
app.factory('refreshService', ['$http', '$q', '$window', function($http, $q, $window) {
    var debounce = {};

    return {
        refreshFields: function(fieldsToRefresh, resourceId, url, timeout = 5000) {
            fieldsToRefresh.forEach((fieldName) => {
                if (debounce[fieldName]) {
                    $window.clearTimeout(debounce[fieldName]);
                }

                debounce[fieldName] = $window.setTimeout(() => {
                    var parentWindow = getParentWindow();

                    if (!parentWindow) {
                        console.error('No parent window found');
                        return;
                    }

                    $http({
                        method: 'POST',
                        url: url,
                        data: { resourceId },
                        timeout: timeout
                    })
                    .then((response) => {
                        $window.parent.postMessage({ fieldName, status: 'success' }, '*');

                        // Update the dialog field with the refreshed data
                        updateDialogField(fieldName, response.data);
                    })
                    .catch(() => {
                        $window.parent.postMessage({ fieldName, status: 'failure' }, '*');

                        // Retry after 1 second if parent window does not respond within timeout period
                        $window.setTimeout(() => this.refreshFields([fieldName], resourceId, url), 1000);
                    });
                }, timeout);
            });
        }
    };
}]);
```
This code uses AngularJS's $http service to send a POST request to the external API for fetching refresh data. It also uses JavaScript's setTimeout and clearTimeout functions to implement a debounce mechanism, limiting the frequency of refresh attempts. 

