pthread_mutex_t mutexMemoryAllocation = PTHREAD_MUTEX_INITIALIZER;

// Custom seed function for reproducibility
unsigned int customSeed(unsigned int seed) {
    return (seed * 1103515245 + 12345) % (1 << 31);
}

int findLargestInteger(int* array, size_t length) {
    int max = array[0];
    for (size_t i = 1; i < length; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

// Memory allocation and data processing function
int processData(long* offsets, int* keys, record* records, size_t length, unsigned int seed, int minValue, int maxValue) {
    // Initialize memory pool
    pthread_mutex_lock(&mutexMemoryAllocation);
    if (memoryPool == NULL) {
        memoryPool = malloc(length * sizeof(record));
        if (memoryPool == NULL) {
            fprintf(stderr, "Failed to allocate memory pool\n");
            pthread_mutex_unlock(&mutexMemoryAllocation);
            return 0;
        }
    }
    atomic_store(&memoryPoolSize, length * sizeof(record));
    pthread_mutex_unlock(&mutexMemoryAllocation);

    // Populate records array with random integer values within a specified range
    for (size_t i = 0; i < length; ++i) {
        seed = customSeed(seed);
        int value = minValue + (seed % (maxValue - minValue + 1));
