Record* createSession(int limit, int minOffset, int maxOffset, int minKey, int maxKey) {
    srand(time(NULL));
    Record* session = malloc(limit * sizeof(Record));
    if (session == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
