void print_largest(Record* arr, size_t n) {
    if (n == 0) return;

    int max = arr[0].value;
    for (size_t i = 1; i < n; ++i) {
        if (arr[i].value > max) {
            max = arr[i].value;
        }
    }

    printf("Largest integer: %d\n", max);
}

Record* read_and_randomize(size_t n, int min, int max, size_t* out_len) {
    if (min > max || n == 0) return NULL;

    Record* arr = malloc(n * sizeof(Record));
    if (!arr) return NULL;

    srand(time(NULL));
    for (size_t i = 0; i < n; ++i) {
        arr[i].value = rand() % (max - min + 1) + min;

        // Periodically validate the randomness distribution
        if ((double)rand() / RAND_MAX < 0.01) {
            int count[max-min+1] = { 0 };
            for (size_t j = 0; j <= i; ++j) {
                ++count[arr[j].value - min];
            }

            // Check if the distribution is uniform
            double expected = ((double)(i + 1)) / (max - min + 1);
            for (int k = min; k <= max; ++k) {
                double actual = count[k - min] / (double)(i + 1);
                if (actual < expected * 0.9 || actual > expected * 1.1) {
                    printf("Randomness distribution is not uniform!\n");
                    break;
                }
            }
        }
    }

    clock_t start = clock();
    print_largest(arr, n);
    clock_t end = clock();
    double time_spent = (double)(end - start) / CLOCKS_PER_SEC;
    printf("Execution time: %f seconds\n", time_spent);

    *out_len = n;
    return arr;
}
```
