class Character {
public:
    enum AttackType { ATTACK1, ATTACK2, ATTACK3 };

    Character(int id) : id_(id), lastAttackTime_(0), attackType_(ATTACK1) {}

    void selectAttack() {
        std::lock_guard<std::mutex> lock(mtx_);

        auto currentTime = time(nullptr);
        if (currentTime - lastAttackTime_ < 9) return;

        switch (attackType_) {
            case ATTACK1:
                std::cout << "Character " << id_ << " selected Attack 1" << std::endl;
                logSelection(1);
                lastAttackTime_ = currentTime;
                attackType_ = ATTACK2;
                break;
            case ATTACK2:
                if (currentTime - lastAttackTime_ < 6) return;

                std::cout << "Character " << id_ << " selected Attack 2" << std::endl;
                logSelection(2);
                lastAttackTime_ = currentTime;
                attackType_ = ATTACK3;
                break;
            case ATTACK3:
                if (currentTime - lastAttackTime_ < 11) return;

                std::cout << "Character " << id_ << " selected Attack 3" << std::endl;
                logSelection(3);
                lastAttackTime_ = currentTime;
                attackType_ = ATTACK1;
                break;
        }
    }

private:
    void logSelection(int attack) {
        std::ofstream logFile("log.txt", std::ios_base::app);
        if (logFile.is_open()) {
            logFile << "Character " << id_ << " selected Attack " << attack << std::endl;
            logFile.close();
        } else {
            std::cerr << "Unable to open log file" << std::endl;
        }
    }

    int id_;
    time_t lastAttackTime_;
    AttackType attackType_;
    std::mutex mtx_;
};

std::unordered_map<int, Character> characters;

void selectAttack(int characterId) {
    if (characters.find(characterId) == characters.end()) {
        characters[characterId] = Character(characterId);
    }

    characters[characterId].selectAttack();
}
```
This code creates a `Character` class that manages its own cooldown state and attack selection, ensuring thread safety with a std::mutex. The `selectAttack` function is used to select an attack for a character, creating the character if it doesn't exist yet. This function also ensures thread safety by locking the mutex before accessing the character's data.
