    srand(seed);
    Record **records = malloc(num_records * sizeof(Record*));
    if (records == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i] = malloc(sizeof(Record));
        if (records[i] == NULL) {
            printf("Memory allocation failed\n");
            return NULL;  // Handle memory allocation failure
        }

        records[i]->value = 10.0 * ((double)rand() / RAND_MAX);  // Random double between 0 and 10
        sprintf(records[i]->id, "Record%d", i+1);
        records[i]->list_head = NULL;
    }

    return records;
}

Node* insert(Node *node, int key) {
    if (node == NULL) {
        node = malloc(sizeof(Node));
        if (node == NULL) {
            printf("Memory allocation failed\n");
            return NULL;  // Handle memory allocation failure
        }

        node->key = key;
        node->left = node->right = NULL;
    } else if (key < node->key) {
        node->left = insert(node->left, key);
    } else if (key > node->key) {
        node->right = insert(node->right, key);
    }

    return node;
}

void traverse(Node *node) {
    if (node != NULL) {
        traverse(node->left);
        printf("%d ", node->key);
        traverse(node->right);
    }
}

int main() {
    Record **records = initialize(5, 1234);

    for (int i = 0; i < 5; ++i) {
        records[i]->list_head = insert(records[i]->list_head, i*10);
    }

    traverse(records[0]->list_head);  // Traversal of the first record's list

    for (int i = 0; i < 5; ++i) {
        free(records[i]);  // Free each record
    }
    free(records);  // Free records array

    return 0;
}
```
