static pthread_mutex_t *lockarray;

void load_crypto(char* config_file) {
    FILE *file = fopen(config_file, "r");
    if (file == NULL) {
        printf("Failed to open configuration file\n");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Parse the line and get cipher/digest name
        char *name = strtok(line, " ");

        pthread_mutex_lock(&lockarray[0]);  // Use a mutex to prevent race conditions
        const EVP_CIPHER *cipher = EVP_get_cipherbyname(name);
        if (cipher != NULL) {
            printf("Adding cipher: %s\n", name);
            EVP_add_cipher(cipher);
        } else {
            const EVP_MD *digest = EVP_get_digestbyname(name);
            if (digest != NULL) {
                printf("Adding digest: %s\n", name);
                EVP_add_digest(digest);
            } else {
                printf("Failed to find cipher or digest by name: %s\n", name);
            }
        }
        pthread_mutex_unlock(&lockarray[0]);  // Release the lock
    }

    fclose(file);
}
```
