typedef struct {
    int value;
} Record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void seed_random() {
    srand((unsigned int)time(NULL));
}

int get_random_number(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void initialize_records(Record** records, long* offsets, int* keys, size_t num_records, int value_range) {
    *records = safe_malloc(num_records * sizeof(Record));
    *offsets = safe_malloc(num_records * sizeof(long));
    *keys = safe_malloc(num_records * sizeof(int));

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = get_random_number(1, value_range);
        (*offsets)[i] = i;
        (*keys)[i] = i;
    }
}

void serialize_data(const char* filename, Record* records, long* offsets, int* keys, size_t num_records) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        exit(EXIT_FAILURE);
    }

    fwrite(&num_records, sizeof(size_t), 1, file);
    fwrite(offsets, sizeof(long), num_records, file);
    fwrite(keys, sizeof(int), num_records, file);
    fwrite(records, sizeof(Record), num_records, file);

    fclose(file);
}

void deserialize_data(const char* filename, Record** records, long** offsets, int** keys, size_t* num_records) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading\n");
        exit(EXIT_FAILURE);
    }

    fread(num_records, sizeof(size_t), 1, file);
    *offsets = safe_malloc(*num_records * sizeof(long));
    *keys = safe_malloc(*num_records * sizeof(int));
    *records = safe_malloc(*num_records * sizeof(Record));

    fread(*offsets, sizeof(long), *num_records, file);
    fread(*keys, sizeof(int), *num_records, file);
    fread(*records, sizeof(Record), *num_records, file);

    fclose(file);
}
```
