['Here is a basic implementation of the task using C language. This is a simplified version and does not include all the features mentioned like logging mechanism, caching strategy etc. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    char identifier;
    short status_code;
} record;

typedef struct {
    int key;
    pthread_mutex_t mutex;
    size_t capacity;
    size_t size;
    long* offsets;
    int* keys;
    record* records;
} RecordStorage;

RecordStorage* create_storage(size_t initial_capacity) {
    RecordStorage* storage = malloc(sizeof(RecordStorage));
    if (storage == NULL) return NULL;

    storage->offsets = malloc(initial_capacity * sizeof(long));
    storage->keys = malloc(initial_capacity * sizeof(int));
    storage->records = malloc(initial_capacity * sizeof(record));

    if (storage->offsets == NULL || storage->keys == NULL || storage->records == NULL) {
        free(storage->offsets);
        free(storage->keys);
        free(storage->records);
        free(storage);
        return NULL;
    }

    storage->capacity = initial_capacity;
    storage->size = 0;
    pthread_mutex_init(&storage->mutex, NULL);

    return storage;
}

void add_record(RecordStorage* storage, int key, record rec) {
    pthread_mutex_lock(&storage->mutex);

    if (storage->size == storage->capacity) {
        size_t new_capacity = storage->capacity * 2;

        long* new_offsets = realloc(storage->offsets, new_capacity * sizeof(long));
        int* new_keys = realloc(storage->keys, new_capacity * sizeof(int));
        record* new_records = realloc(storage->records, new_capacity * sizeof(record));

        if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
            pthread_mutex_unlock(&storage->mutex);
            return;
        }

        storage->offsets = new_offsets;
        storage->keys = new_keys;
        storage->records = new_records;
        storage->capacity = new_capacity;
    }

    storage->keys[storage->size] = key;
    storage->records[storage->size] = rec;
    storage->offsets[storage->size] = (long)&(storage->records[storage->size]);
    storage->size++;

    pthread_mutex_unlock(&storage->mutex);
}

void free_storage(RecordStorage* storage) {
    pthread_mutex_destroy(&storage->mutex);
    free(storage->offsets);
    free(storage->keys);
    free(storage->records);
    free(storage);
}
```
This code creates a dynamic record storage system with mutex for thread safety. It uses realloc to dynamically allocate and reallocate memory as needed, ensuring that the system can scale efficiently with increasing numbers of records. 

