```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Event {
    int key;
    long timestamp;
    char* message;
    struct Event* next;
} Event;

typedef struct HashTable {
    Event** table;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_table(size_t size) {
    HashTable* ht = malloc(sizeof(HashTable));
    if (ht == NULL) return NULL;

    ht->table = calloc(size, sizeof(Event*));
    if (ht->table == NULL) {
        free(ht);
        return NULL;
    }

    ht->size = size;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

int hash(HashTable* ht, int key) {
    return key % ht->size;
}

void insert(HashTable* ht, Event* event) {
    pthread_mutex_lock(&ht->lock);

    int index = hash(ht, event->key);
    event->next = ht->table[index];
    ht->table[index] = event;

    pthread_mutex_unlock(&ht->lock);
}

Event* lookup(HashTable* ht, int key) {
    pthread_mutex_lock(&ht->lock);

    int index = hash(ht, key);
    Event* event = ht->table[index];
    while (event != NULL && event->key != key) {
        event = event->next;
    }

    pthread_mutex_unlock(&ht->lock);
    return event;
}

void delete(HashTable* ht, int key) {
    pthread_mutex_lock(&ht->lock);

    int index = hash(ht, key);
    Event** link = &ht->table[index];
    while (*link != NULL && (*link)->key != key) {
        link = &(*link)->next;
    }

    if (*link != NULL) {
        Event* temp = *link;
        *link = temp->next;
        free(temp->message);
        free(temp);
    }

    pthread_mutex_unlock(&ht->lock);
}
```
This code does not include the unique key generation, message length configuration, hash table resizing thresholds and memory leak detection mechanisms. It also doesn't handle edge cases like high collision rates or near-maximum memory usage. These features would require a more complex implementation and might need to be adjusted based on specific requirements and constraints.
