['Here is a basic implementation of such a function in C using pthreads for synchronization. This code does not include all the error checking you would want in a production environment, but it should give you an idea of how to approach this problem. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

typedef struct Dataset {
    long* offsets;
    int* keys;
    Record* records;
    size_t size;
    unsigned seed;
    int id;
    struct Dataset* next;
} Dataset;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Dataset* head = NULL;
int counter = 0;

void* initialize(void* arg) {
    Dataset* dataset = (Dataset*)arg;

    srand(dataset->seed);
    for (size_t i = 0; i < dataset->size; ++i) {
        dataset->records[i].value = rand() % 100 + 1; // Set value to a random integer within the specified range.
    }

    pthread_mutex_lock(&lock);
    Dataset* current = head;
    while (current != NULL) {
        if (current->id == dataset->id) {
            printf("Error: Duplicate dataset ID.\n");
            exit(1);
        }
        current = current->next;
    }

    dataset->next = head;
    head = dataset;
    pthread_mutex_unlock(&lock);
}

Dataset* create_dataset(size_t size, unsigned seed) {
    Dataset* dataset = malloc(sizeof(Dataset));
    if (dataset == NULL) {
        printf("Error: Failed to allocate memory for dataset.\n");
        exit(1);
    }

    dataset->offsets = calloc(size, sizeof(long));
    dataset->keys = malloc(size * sizeof(int));
    dataset->records = calloc(size, sizeof(Record));

    if (dataset->offsets == NULL || dataset->keys == NULL || dataset->records == NULL) {
        printf("Error: Failed to allocate memory for arrays.\n");
        exit(1);
    }

    dataset->size = size;
    dataset->seed = seed;
    pthread_mutex_lock(&lock);
    dataset->id = counter++;
    pthread_mutex_unlock(&lock);

    return dataset;
}

void remove_dataset(int id) {
    pthread_mutex_lock(&lock);
    Dataset* current = head;
    Dataset* prev = NULL;
    while (current != NULL) {
        if (current->id == id) {
            if (prev == NULL) {
                head = current->next;
            } else {
                prev->next = current->next;
            }

            free(current->offsets);
            free(current->keys);
            free(current->records);
            free(current);
            break;
        }

        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}
```
This code uses a linked list to manage the datasets. Each dataset is allocated with three arrays: one for offsets, one for keys, and one for records. The `initialize` function initializes each record's value to a random integer within the specified range. It also checks for duplicate IDs when adding new datasets.

The `create_dataset` function creates a new dataset with the given size and seed, allocating memory for the arrays and setting the ID. The `remove_dataset` function removes a dataset from the list by its ID, freeing all allocated memory. 

Please note that this is a basic implementation and does not include many features you would want in a production environment such as error checking, logging, or thread safety for concurrent access. Also, it doesn't handle zero-sized arrays or duplicate identifiers gracefully. You should add these features according to your requirements.
