    MemoryPool pool = {PTHREAD_MUTEX_INITIALIZER, size, malloc(sizeof(PoolEntry) * size)};
    return pool;
}

void destroy_pool(MemoryPool* pool) {
    pthread_mutex_destroy(&pool->mutex);
    free(pool->entries);
}

// Custom hash function to map keys to offsets efficiently.
size_t custom_hash(int key, size_t size) {
    return (size_t)(key % size);
}

void insert_into_pool(MemoryPool* pool, int key, Record record) {
    pthread_mutex_lock(&pool->mutex);
    size_t index = custom_hash(key, pool->size);
    pool->entries[index].offset = (long)&pool->entries[index];
    pool->entries[index].key = key;
    pool->entries[index].record = record;
    pthread_mutex_unlock(&pool->mutex);
}

// ... similar functions for other operations (e.g., lookup, delete)

int main() {
    MemoryPool pool = create_pool(1024);

    // Insert some data into the pool
    Record record = {5};
    insert_into_pool(&pool, 123, record);

    destroy_pool(&pool);
}
