}

// Resize arrays when full
void resizeArrays() {
    size_t newCapacity = data.capacity * growthFactor;

    // Reallocate memory for arrays
    data.offsets = customRealloc(data.offsets, newCapacity * sizeof(long));
    data.keys = customRealloc(data.keys, newCapacity * sizeof(int));
    data.records = customRealloc(data.records, newCapacity * sizeof(Record));

