    // Method to handle session expiration and automatic re-authentication
    public void manageSession(String userId, String sessionId) {
        if (redisTemplate.hasKey(userId)) {
            Object existingSessionId = redisTemplate.opsForValue().get(userId);

            // If the session is expired or different from the current one, re-authenticate
            if (!existingSessionId.equals(sessionId)) {
                reAuthenticateUser(userId);
            }
        } else {
            // If there's no existing session for this user, create a new one
            redisTemplate.opsForValue().set(userId, sessionId);
        }
    }

