```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unordered_map>

typedef struct {
    time_t timestamp;
    int key;
    char* description;
} Record;

class RecordCollection {
private:
    std::unordered_map<int, Record> records;
public:
    void addRecord(int key, const char* description) {
        Record record = {time(NULL), key, strdup(description)};
        records[key] = record;
        printf("Added record with key %d\n", key);
    }

    Record getRecord(int key) {
        if (records.find(key) != records.end()) {
            printf("Retrieved record with key %d\n", key);
            return records[key];
        } else {
            printf("No record found with key %d\n", key);
            // Return a default record or throw an exception based on your needs
        }
    }

    void deleteRecord(int key) {
        if (records.find(key) != records.end()) {
            free(records[key].description);
            records.erase(key);
            printf("Deleted record with key %d\n", key);
        } else {
            printf("No record found with key %d to delete\n", key);
        }
    }

    ~RecordCollection() {
        for (auto& pair : records) {
            free(pair.second.description);
        }
    }
};
```

