Record** records = NULL;
int recordCount = 0;

void addToHash(long offset) {
    int index = abs((int)offset % OFFSET_COUNT_MAX);
    Node* node = malloc(sizeof(Node));
    node->key = offset;
    node->next = hashTable[index];
    hashTable[index] = node;
}

int isInHash(long offset) {
    int index = abs((int)offset % OFFSET_COUNT_MAX);
    Node* node = hashTable[index];
    while (node != NULL) {
        if (node->key == offset) return 1;
        node = node->next;
