int insert_person(PersonsCollection* collection, const char* name, int age, double salary) {
    if (collection->length == collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        Person** newArray = realloc(collection->persons, newCapacity * sizeof(Person*));

        if (newArray == NULL) return -1; // Failed to allocate memory

        collection->persons = newArray;
        collection->capacity = newCapacity;
    }

    Person* person = malloc(sizeof(Person));
