typedef struct List {
    pthread_mutex_t lock;
    Record** records;
    size_t count;
    size_t capacity;
} List;

List* create_list(size_t initial_capacity) {
    List* list = malloc(sizeof(List));
    assert(list != NULL);

    pthread_mutex_init(&list->lock, NULL);
    list->records = calloc(initial_capacity, sizeof(Record*));
    assert(list->records != NULL);

    list->count = 0;
    list->capacity = initial_capacity;

    return list;
}

void add_record(List* list, Record* record) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        list->records = realloc(list->records, 2 * list->capacity * sizeof(Record*));
        assert(list->records != NULL);

        list->capacity *= 2;
    }

    list->records[list->count++] = record;

    pthread_mutex_unlock(&list->lock);
}

void destroy_record(Record* record) {
    free(record->identifier);
    free(record);
}

void destroy_list(List* list) {
    for (size_t i = 0; i < list->count; ++i) {
        destroy_record(list->records[i]);
    }

    pthread_mutex_destroy(&list->lock);
    free(list->records);
    free(list);
}
