["Here's a basic implementation in C that meets your requirements. It uses dynamic memory allocation for resource pool management, mutexes for thread safety, and atomic operations to manage reference counts. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    int* id;
    long* offset;
} resource;

typedef struct {
    atomic_int refcount;
    resource res;
} managed_resource;

managed_resource** pool = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_pool(size_t size) {
    pthread_mutex_lock(&mutex);

    if (pool == NULL) {
        pool = malloc(size * sizeof(managed_resource*));

        for (size_t i = 0; i < size; ++i) {
            managed_resource* res = malloc(sizeof(managed_resource));

            // Initialize resource with data from external source
            init_resource(&res->res);

            atomic_init(&res->refcount, 1);
            pool[i] = res;
        }
    }

    pthread_mutex_unlock(&mutex);
}

managed_resource* get_resource(size_t index) {
    if (index >= size || pool == NULL) {
        return NULL;
    }

    managed_resource* res = pool[index];

    if (res != NULL) {
        atomic_fetch_add(&res->refcount, 1);
    }

    return res;
}

void release_resource(managed_resource* res) {
    if (res == NULL) {
        return;
    }

    int count = atomic_fetch_sub(&res->refcount, 1);

    if (count == 1) {
        free(res->res.id);
        free(res->res.offset);
        free(res);

        // Remove from pool
        for (size_t i = 0; i < size; ++i) {
            if (pool[i] == res) {
                pool[i] = NULL;
                break;
            }
        }
    }
}
```

