int process_data_with_threading(size_t num_records, size_t num_threads) {
    long* offsets = calloc(num_records, sizeof(long));
    if (offsets == NULL) return 0; // Memory allocation failed

    int* keys = malloc(num_records * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        return 0; // Memory allocation failed
