    record_t* records = calloc(num_records, sizeof(record_t));
    if (records == NULL) {
        free(offsets);
        free(keys);
        return 0; // Memory allocation failed
    }

    pthread_t threads[num_threads];
    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, thread_func, NULL)) {
            // Thread creation failed. Clean up and return 0.
            free(offsets);
            free(keys);
            free(records);
            return 0;
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL); // Wait for all threads to finish.
    }

    int max = find_max(offsets, num_records);
    printf("Max offset: %d\n", max);

    free(offsets);
    free(keys);
    free(records);

    return 1; // Success
}
