    assert(table->records != NULL && table->metadatas != NULL);

    table->capacity = initial_capacity;
    table->count = 0;

    return table;
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        free(table->records[i]);
        free(table->metadatas[i]);
    }

    free(table->records);
    free(table->metadatas);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

void insert_record(HashTable* table, Record* record) {
    assert(record != NULL);

    if (table->count >= table->capacity / 2) {
        // Resize the hash table when it's half full.
        pthread_mutex_lock(&table->lock);

        size_t new_capacity = table->capacity * 2;
        Record** new_records = calloc(new_capacity, sizeof(Record*));
        Metadata** new_metadatas = calloc(new_capacity, sizeof(Metadata*));

        // Copy the old records to the new table.
        for (size_t i = 0; i < table->capacity; ++i) {
            size_t hash = record->key % new_capacity;

            while (new_records[hash] != NULL) {
                hash = (hash + 1) % new_capacity;
            }

            new_records[hash] = table->records[i];
            new_metadatas[hash] = table->metadatas[i];
        }

        free(table->records);
        free(table->metadatas);
        table->records = new_records;
        table->metadatas = new_metadatas;
        table->capacity = new_capacity;

        pthread_mutex_unlock(&table->lock);
    }

    size_t hash = record->key % table->capacity;

    while (table->records[hash] != NULL) {
        hash = (hash + 1) % table->capacity;
    }

    pthread_mutex_lock(&table->lock);
    table->records[hash] = record;
    table->metadatas[hash] = malloc(sizeof(Metadata));
    assert(table->metadatas[hash] != NULL);
    ++table->count;
    pthread_mutex_unlock(&table->lock);
}
```
