```c
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    int key;
    int value;
    struct Record *next;
} Record;

Record **hash_table = NULL;
int table_size = 0;

void init(int size) {
    hash_table = (Record**)calloc(size, sizeof(Record*));
    table_size = size;
}

unsigned int hash(int key) {
    return key % table_size;
}

void insert(int key, int value) {
    unsigned int index = hash(key);
    Record *record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->value = value;
    record->next = hash_table[index];
    hash_table[index] = record;
}

int lookup(int key) {
    unsigned int index = hash(key);
    Record *record = hash_table[index];
    while (record != NULL) {
        if (record->key == key) return record->value;
        record = record->next;
    }
    return -1;  // Return -1 for not found.
}

void delete(int key) {
    unsigned int index = hash(key);
    Record *record = hash_table[index];
    Record *prev = NULL;
    while (record != NULL) {
        if (record->key == key) {
            if (prev == NULL) {  // If the record is at the head of list.
                hash_table[index] = record->next;
            } else {
                prev->next = record->next;
            }
            free(record);
            return;
        }
        prev = record;
        record = record->next;
    }
}

void cleanup() {
    for (int i = 0; i < table_size; ++i) {
        Record *record = hash_table[i];
        while (record != NULL) {
            Record *temp = record;
            record = record->next;
            free(temp);
        }
    }
    free(hash_table);
}
```
This code implements a basic hash table with chaining for collision resolution. The `insert`, `lookup` and `delete` operations are implemented as per the requirements. 

