        free(session->recentURLs[0].url);
        for (size_t i = 0; i < 9; ++i) {
            session->recentURLs[i] = session->recentURLs[i+1];
        }
        --session->numRecentURLs;
    }

    URLRecord newRecord;
    newRecord.url = strdup(url);
    time(&newRecord.timestamp);

    session->recentURLs[session->numRecentURLs++] = newRecord;
}

void destroySession(Session* session) {
    for (size_t i = 0; i < session->numRecentURLs; ++i) {
        free(session->recentURLs[i].url);
