}

int add_to_memory_pool(MemoryPool* pool, long offset, int key, Record* record) {
    pthread_mutex_lock(&pool->lock);

    if (pool->size == pool->capacity && !allocate_memory(pool, pool->capacity)) {
        pthread_mutex_unlock(&pool->lock);
