    int* keys;
    record** records;
    size_t capacity;
    pthread_mutex_t lock;
} DataPipeline;

DataPipeline* init_pipeline(size_t capacity) {
    srand(time(NULL));

    DataPipeline* pipeline = malloc(sizeof(DataPipeline));
    if (pipeline == NULL) return NULL;

    pipeline->offsets = malloc(capacity * sizeof(long));
    pipeline->keys = malloc(capacity * sizeof(int));
    pipeline->records = malloc(capacity * sizeof(record*));
    if (pipeline->offsets == NULL || pipeline->keys == NULL || pipeline->records == NULL) {
        free_pipeline(pipeline);
        return NULL;
    }

    for (size_t i = 0; i < capacity; ++i) {
        pipeline->offsets[i] = rand();
        pipeline->keys[i] = rand();

        record* rec = malloc(sizeof(record));
        if (rec == NULL) {
            free_pipeline(pipeline);
            return NULL;
        }

        rec->value = rand();
        rec->timestamp = time(NULL);
        rec->status = 'A';
        rec->version = 1;

        pipeline->records[i] = rec;
    }

    pthread_mutex_init(&pipeline->lock, NULL);
    return pipeline;
}

void free_pipeline(DataPipeline* pipeline) {
    if (pipeline == NULL) return;

    for (size_t i = 0; i < pipeline->capacity; ++i) {
        free(pipeline->records[i]);
    }

    free(pipeline->offsets);
    free(pipeline->keys);
    free(pipeline->records);
