```c++
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <unordered_map>

struct Node {
    std::string string;
    int frequency;
};

class NodeList {
private:
    std::unordered_map<std::string, Node*> nodeMap;
public:
    ~NodeList() {
        for (auto& pair : nodeMap) {
            delete pair.second;
        }
    }

    void addSubstring(const std::string& substring) {
        if (nodeMap.find(substring) == nodeMap.end()) {
            Node* newNode = new Node{substring, 1};
            nodeMap[substring] = newNode;
        } else {
            nodeMap[substring]->frequency++;
        }
    }

    int getFrequency(const std::string& substring) const {
        auto it = nodeMap.find(substring);
        if (it != nodeMap.end()) {
            return it->second->frequency;
        } else {
            return 0;
        }
    }
};
```

