void logMessage(const char* message) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char buffer[80];
    strftime(buffer, 80, "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(logFile, "[%s] Thread ID: %ld - %s\n", buffer, pthread_self(), message);
}

void* allocateMemory(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        logMessage("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void* retryAllocateMemory(size_t size, int retries) {
    void *ptr = NULL;
    for (int i = 0; i < retries; ++i) {
        ptr = allocateMemory(size);
        if (ptr != NULL) break;
        sleep((1 << i)); // Exponential backoff
    }
    return ptr;
}

void validateAndAllocateArray(int size, int maxSize) {
    if (size > maxSize || size < 0) {
        logMessage("Invalid array size");
        exit(EXIT_FAILURE);
    }

    while (memoryUsage + size*sizeof(record) > 0.75 * MAX_MEMORY) {
        logMessage("Memory usage exceeds 75% of total available memory");
        sleep(1); // Wait for some time before retrying
    }

    records = retryAllocateMemory(size*sizeof(record), 3);
    memoryUsage += size*sizeof(record);
}

