#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

typedef struct record {
    int value;
    struct record *next;
} Record;

typedef struct hash_map_entry {
    long key;
    atomic_long offset;
    struct hash_map_entry *next;
} HashMapEntry;

HashMapEntry **hash_map = NULL;
size_t hash_map_capacity = 0;
pthread_mutex_t hash_map_lock = PTHREAD_MUTEX_INITIALIZER;
Record *linked_list = NULL;
long *offsets = NULL;
size_t offsets_limit = 0;
atomic_ullong record_count = 0;
pthread_mutex_t linked_list_lock = PTHREAD_MUTEX_INITIALIZER;
int value_range = 0;

long hash(long key) {
    return abs((key * 2654435761) % hash_map_capacity);
}

void insert_into_hash_map(HashMapEntry *entry) {
    long index = hash(entry->key);
    pthread_mutex_lock(&hash_map_lock);
    entry->next = hash_map[index];
    hash_map[index] = entry;
    pthread_mutex_unlock(&hash_map_lock);
}

void insert_into_linked_list(Record *record) {
    pthread_mutex_lock(&linked_list_lock);
    record->next = linked_list;
    linked_list = record;
    pthread_mutex_unlock(&linked_list_lock);
}

void *initialize(size_t capacity, size_t limit, int range) {
    srand(time(NULL));
    hash_map_capacity = capacity;
    offsets_limit = limit;
    value_range = range;

    // Allocate memory for the hash map and linked list.
    hash_map = calloc(hash_map_capacity, sizeof(HashMapEntry *));
    if (hash_map == NULL) {
        return NULL;
    }

    offsets = malloc(offsets_limit * sizeof(long));
    if (offsets == NULL) {
        free(hash_map);
        hash_map = NULL;
        return NULL;
    }

    // Initialize the linked list.
    for (size_t i = 0; i < offsets_limit; ++i) {
        Record *record = malloc(sizeof(Record));
        if (record == NULL) {
            free(offsets);
            offsets = NULL;
            return NULL;
        }

        record->value = rand() % value_range;
        insert_into_linked_list(record);
    }

    // Initialize the hash map.
    for (size_t i = 0; i < offsets_limit; ++i) {
        HashMapEntry *entry = malloc(sizeof(HashMapEntry));
        if (entry == NULL) {
            return NULL;
        }

        entry->key = rand() % value_range;
        atomic_init(&entry->offset, i);
        insert_into_hash_map(entry);
    }

    // Return the number of successfully initialized records.
    return &record_count;
}
```
