void insert(BSTNode** root, int key, Record record) {
    if (*root == NULL) {
        *root = (BSTNode*)malloc(sizeof(BSTNode));
        (*root)->key = key;
        (*root)->record = record;
        (*root)->left = (*root)->right = NULL;
    } else if (key < (*root)->key) {
        insert(&((*root)->left), key, record);
    } else if (key > (*root)->key) {
        insert(&((*root)->right), key, record);
    } else { // Update existing entry
        (*root)->record = record;
    }
}

int initializeComponents() {
    srand(time(NULL));

