#include <glib.h>
#include <time.h>
#include <unistd.h>

typedef struct record {
    int value;
    long offset;
} Record;

GHashTable* hashmap;
Record** records;
int num_records = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init() {
    // Initialize the hash map and array of records
    long total_memory = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE);
    long max_memory = total_memory / 2;
    int num_elements = max_memory / sizeof(long); // Assuming each element is a long

    hashmap = g_hash_table_new(g_direct_hash, g_direct_equal);
    records = malloc(num_elements * sizeof(Record*));
}

void insert(int key) {
    pthread_mutex_lock(&lock);

    // Check if the hash map is full
    if (g_hash_table_size(hashmap) >= num_records) {
        // Handle error, e.g., by reassigning a new unique value and updating all associated offsets in the linked list
        pthread_mutex_unlock(&lock);
        return;
    }

    // Insert into hash map
    gpointer old = NULL;
    if (!g_hash_table_insert(hashmap, GINT_TO_POINTER(key), &old)) {
        // Handle error, e.g., by retrying with exponential backoff
        pthread_mutex_unlock(&lock);
        return;
    }

    // Insert into linked list and array of records
    Record* record = malloc(sizeof(Record));
    record->value = rand() % 1000 + 1; // Assuming values are within the range [1, 1000]
    record->offset = num_records++;

    int i = 0;
    while (i < num_records - 1 && records[i]->value < record->value) {
        i++;
    }

    for (int j = num_records - 1; j > i; j--) {
        records[j] = records[j - 1];
    }

    records[i] = record;

    pthread_mutex_unlock(&lock);
}

Record* get(int key) {
    pthread_mutex_lock(&lock);

    // Retrieve from hash map
    gpointer value = g_hash_table_lookup(hashmap, GINT_TO_POINTER(key));

    if (value == NULL) {
        // Handle error, e.g., by logging and returning NULL
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    Record* record = value;

    pthread_mutex_unlock(&lock);

    return record;
}
```

