    Metadata* metadata;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DataStructures;

DataStructures* createDataStructures(size_t initialCapacity) {
    DataStructures* ds = malloc(sizeof(DataStructures));
    ds->offsets = calloc(initialCapacity, sizeof(OffsetArray));
    ds->keys = calloc(initialCapacity, sizeof(KeyArray));
    ds->entries = calloc(initialCapacity, sizeof(EntryArray));
    ds->metadata = calloc(initialCapacity, sizeof(Metadata));
    ds->capacity = initialCapacity;
    ds->size = 0;
    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

void destroyDataStructures(DataStructures* ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->entries);
    free(ds->metadata);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

void resizeDataStructures(DataStructures* ds, size_t newCapacity) {
    assert(newCapacity > ds->capacity);

    OffsetArray* newOffsets = calloc(newCapacity, sizeof(OffsetArray));
    KeyArray* newKeys = calloc(newCapacity, sizeof(KeyArray));
    EntryArray* newEntries = calloc(newCapacity, sizeof(EntryArray));
    Metadata* newMetadata = calloc(newCapacity, sizeof(Metadata));

    memcpy(newOffsets, ds->offsets, ds->capacity * sizeof(OffsetArray));
    memcpy(newKeys, ds->keys, ds->capacity * sizeof(KeyArray));
    memcpy(newEntries, ds->entries, ds->capacity * sizeof(EntryArray));
    memcpy(newMetadata, ds->metadata, ds->capacity * sizeof(Metadata));

    free(ds->offsets);
    free(ds->keys);
    free(ds->entries);
    free(ds->metadata);

    ds->offsets = newOffsets;
    ds->keys = newKeys;
    ds->entries = newEntries;
    ds->metadata = newMetadata;
    ds->capacity = newCapacity;
}

void updateEntry(DataStructures* ds, size_t index, double (*func)(double)) {
    assert(index < ds->size);

    pthread_mutex_lock(&ds->lock);
    ds->entries[index].value = func(ds->entries[index].value);
    validateEntry(ds, index);
    pthread_mutex_unlock(&ds->lock);
}

void sortEntriesByKey(DataStructures* ds) {
    // Implement your own sorting algorithm here. This is a simple bubble sort for demonstration purposes.
    int i, j;
    for (i = 0; i < ds->size - 1; i++) {
        for (j = 0; j < ds->size - i - 1; j++) {
            if (ds->keys[j].key > ds->keys[j + 1].key) {
                // Swap elements.
                KeyArray tempKey = ds->keys[j];
                ds->keys[j] = ds->keys[j + 1];
                ds->keys[j + 1] = tempKey;

                OffsetArray tempOffset = ds->offsets[j];
                ds->offsets[j] = ds->offsets[j + 1];
                ds->offsets[j + 1] = tempOffset;

                EntryArray tempEntry = ds->entries[j];
                ds->entries[j] = ds->entries[j + 1];
                ds->entries[j + 1] = tempEntry;

                Metadata tempMetadata = ds->metadata[j];
                ds->metadata[j] = ds->metadata[j + 1];
                ds->metadata[j + 1] = tempMetadata;
            }
        }
    }
}

void validateEntry(DataStructures* ds, size_t index) {
