void manageMemory(long n_offsets, long max_offsets, int n_keys, int max_keys, 
                  int min_value, int max_value, size_t memory_limit) {

    srand((unsigned int)time(NULL)); // seed the random number generator

    long* offsets = (long*)calloc(max_offsets, sizeof(long));
    if (!offsets) {
        printf("Memory allocation failed for offsets\n");
        return;
    }

