    if (!keys) {
        free(offsets);
        printf("Memory allocation failed for keys\n");
        return;
    }

    record* records = (record*)malloc(memory_limit / sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        printf("Memory allocation failed for records\n");
        return;
    }

    // Initialize offsets and keys arrays with -1 and 0 respectively
    for (long i = 0; i < n_offsets; ++i) {
        offsets[i] = -1;
    }
    for (int i = 0; i < n_keys; ++i) {
        keys[i] = 0;
    }

    // Initialize records with random values and key pointers
    size_t record_count = memory_limit / sizeof(record);
    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        if (i < n_keys) {
            records[i].key_pointer = &keys[i];
        } else {
            records[i].key_pointer = NULL;
        }
    }

    // Print summary of current state
    printf("Offsets: %ld elements\n", n_offsets);
    printf("Keys: %d elements\n", n_keys);
    printf("Records: %zu elements, with values ranging from %d to %d\n", 
