typedef struct {
    double d;
    char* str;
    long flag;
} element;

element* array = NULL;
int size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *errorLogFile = NULL;

void logError(const char* errorMessage) {
    if (errorLogFile == NULL) {
        errorLogFile = fopen("error.log", "a");
    }

    if (errorLogFile != NULL) {
        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char date[64];
        strftime(date, sizeof(date), "%c", tm);
        fprintf(errorLogFile, "[%s] %s\n", date, errorMessage);
    }
}

void* initializeArray(int count, double min, double max, int stringLength) {
    if (count < 500 || count > 10000) {
        logError("Invalid array size");
        return NULL;
    }

    pthread_mutex_lock(&mutex);

    srand(time(NULL));

    element* newArray = (element*)malloc(count * sizeof(element));
    if (newArray == NULL) {
        logError("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        newArray[i].d = min + ((double)rand() / RAND_MAX) * (max - min);

        newArray[i].str = malloc(stringLength + 1);
        if (newArray[i].str == NULL) {
            logError("Memory allocation failed");
            return NULL;
        }

        for (int j = 0; j < stringLength; ++j) {
            newArray[i].str[j] = 'a' + rand() % 26; // Generate random alphanumeric character
        }
        newArray[i].str[stringLength] = '\0';

        newArray[i].flag = i % 2;
    }

    if (array != NULL) {
        free(array);
    }

    array = newArray;
    size = count;

    pthread_mutex_unlock(&mutex);

    return array;
}
```
This code uses a mutex to ensure that only one thread can access the shared `array` at any given time, preventing race conditions. It also logs errors to a file named "error.log". The function `initializeArray` initializes an array of `struct element` with random values and returns it.
