#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Edge {
    int weight;
    struct Vertex* vertex;
} Edge;

typedef struct Vertex {
    int id;
    float x, y;
    Edge** edges;
    size_t edgeCount;
} Vertex;

Vertex* createVertex(int id, float x, float y) {
    Vertex* vertex = malloc(sizeof(Vertex));
    if (vertex == NULL) return NULL;

    vertex->id = id;
    vertex->x = x;
    vertex->y = y;
    vertex->edgeCount = 0;
    vertex->edges = malloc(sizeof(Edge*));
    if (vertex->edges == NULL) {
        free(vertex);
        return NULL;
    }

    return vertex;
}

void addVertex(Vertex** vertices, size_t* count, Vertex* newVertex) {
    *vertices = realloc(*vertices, (*count + 1) * sizeof(Vertex*));
    if (*vertices == NULL) exit(-1); // Log error and free all allocated memory

    (*vertices)[*count] = newVertex;
    (*count)++;
}

void deleteVertex(Vertex** vertices, size_t* count, int id) {
    for (size_t i = 0; i < *count; ++i) {
        if ((*vertices)[i]->id == id) {
            free((*vertices)[i]);

            (*count)--;
            memmove(&(*vertices)[i], &(*vertices)[i + 1], (*count - i) * sizeof(Vertex*));

            *vertices = realloc(*vertices, (*count) * sizeof(Vertex*));
            if (*vertices == NULL && *count != 0) exit(-1); // Log error and free all allocated memory
        }
    }
}

int main() {
    Vertex** vertices = malloc(sizeof(Vertex*));
    size_t vertexCount = 0;

    int ids[] = {1, 2, 3};
    float coords[] = {1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f};

    for (size_t i = 0; i < 3; ++i) {
        Vertex* newVertex = createVertex(ids[i], coords[2 * i], coords[2 * i + 1]);
        if (newVertex == NULL) exit(-1); // Log error and free all allocated memory

        addVertex(&vertices, &vertexCount, newVertex);
    }

    deleteVertex(&vertices, &vertexCount, 2);

    for (size_t i = 0; i < vertexCount; ++i) {
        printf("ID: %d, Coords: (%f, %f)\n", vertices[i]->id, vertices[i]->x, vertices[i]->y);
    }

    free(vertices);

    return 0;
}
```
