    if (*ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 0;
    }
    return 1;
}

int initialize_task(Task* task, const char* description, int priority_level, time_t deadline) {
    if (description == NULL || strlen(description) == 0) {
        fprintf(stderr, "Invalid task description\n");
        return 0;
    }

    task->description = malloc((strlen(description) + 1) * sizeof(char));
    if (task->description == NULL) {
        fprintf(stderr, "Memory allocation failed for task description\n");
        return 0;
    }
    strcpy(task->description, description);

    task->priority_level = priority_level;
    task->deadline = deadline;

    return 1;
}

int initialize_project(Project* project, Task** tasks, size_t task_count, double budgets[3]) {
    if (tasks == NULL || task_count == 0) {
        fprintf(stderr, "Invalid tasks\n");
        return 0;
    }

    project->task_count = task_count;

    if (!allocate_memory((void**)&project->tasks, task_count, sizeof(Task*))) {
        return 0;
    }

    for (size_t i = 0; i < task_count; ++i) {
        project->tasks[i] = tasks[i];
    }

    memcpy(project->budgets, budgets, sizeof(double) * 3);

    return 1;
}

void print_task(Task* task) {
