    printf("Priority level: %d\n", task->priority_level);
    printf("Deadline: %ld\n", (long)task->deadline);
}

void print_project(Project* project) {
    for (size_t i = 0; i < project->task_count; ++i) {
        printf("Task #%zu:\n", i + 1);
        print_task(project->tasks[i]);
    }

    printf("Budgets: small=%.2f, medium=%.2f, large=%.2f\n", project->budgets[0], project->budgets[1], project->budgets[2]);
}

int main() {
    Task task;
    if (!initialize_task(&task, "Test task", 5, time(NULL))) {
        return EXIT_FAILURE;
    }

