#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

typedef struct {
    char filename[256];
    time_t lastModified;
    double fileSize;
} FileMetadata;

int initializeArrays(double **doubles, char ***paths, FileMetadata ***metadata) {
    *doubles = malloc(sizeof(double) * 3); // Allocate memory for three doubles
    if (*doubles == NULL) return -1;

    *paths = malloc(sizeof(char *) * 3); // Allocate memory for three char pointers
    if (*paths == NULL) {
        free(*doubles);
        return -1;
    }

    for (int i = 0; i < 3; ++i) {
        (*paths)[i] = malloc(sizeof(char) * 256); // Allocate memory for each string
        if ((*paths)[i] == NULL) {
            for (--i; i >= 0; --i) free((*paths)[i]); // Free all previously allocated strings
            free(*doubles);
            return -1;
        }
    }

    *metadata = malloc(sizeof(FileMetadata) * 3); // Allocate memory for three FileMetadata structs
    if (*metadata == NULL) {
        for (int i = 0; i < 3; ++i) free((*paths)[i]); // Free all previously allocated strings
        free(*doubles);
        return -1;
    }

    return 0;
}

void deallocateArrays(double *doubles, char **paths, FileMetadata **metadata) {
    for (int i = 0; i < 3; ++i) free(paths[i]); // Free all strings
    free(doubles); // Free doubles array
    free(metadata); // Free metadata structs
}

int readFiles(double *doubles, char **paths, FileMetadata **metadata) {
    for (int i = 0; i < 3; ++i) {
        if (scanf("%lf %255s", &doubles[i], paths[i]) != 2) return -1; // Read a double and a string from stdin

        struct stat st;
        if (stat(paths[i], &st) == -1) return -1; // Get file metadata

        strncpy((*metadata)[i].filename, paths[i], sizeof((*metadata)[i].filename)); // Copy filename to FileMetadata struct
        (*metadata)[i].lastModified = st.st_mtime; // Set last modified time in FileMetadata struct
        (*metadata)[i].fileSize = (double)st.st_size; // Set file size in FileMetadata struct
    }

    return 0;
}

int main() {
    double *doubles;
    char **paths;
    FileMetadata **metadata;

    if (initializeArrays(&doubles, &paths, &metadata) == -1) {
        // Log error and return false
        deallocateArrays(doubles, paths, metadata);
        return 0;
    }

    if (readFiles(doubles, paths, metadata) == -1) {
        // Log error and return false
        deallocateArrays(doubles, paths, metadata);
        return 0;
    }

    // Find file with largest size
    double maxSize = 0.0;
    int maxIndex = -1;
    for (int i = 0; i < 3; ++i) {
        if ((*metadata)[i].fileSize > maxSize) {
            maxSize = (*metadata)[i].fileSize;
            maxIndex = i;
        }
    }

    if (maxIndex != -1) printf("Largest file: %s\n", paths[maxIndex]); // Print filename of largest file

    deallocateArrays(doubles, paths, metadata);
    return 1;
}
```
This code assumes that the filenames are less than 256 characters long and that the doubles can be read from stdin. It also uses `stat` to get file size and last modified time, which might not be available on all systems or configurations. If you're using a logging library, replace the printf calls with calls to your library's logging functions.
