Record* create_record(long li, double fp, const char* str) {
    Record* record = malloc(sizeof(Record));
    if (record == NULL) return NULL;

    record->large_integer = li;
    record->floating_point = fp;
    record->string_buffer = malloc(strlen(str) + 1);
    if (record->string_buffer == NULL) {
        free(record);
        return NULL;
    }

    strcpy(record->string_buffer, str);
    return record;
}

void delete_record(Record* record) {
    if (record != NULL) {
        free(record->string_buffer);
        free(record);
    }
}

typedef struct Node {
    Record* record;
    struct Node* next;
} Node;

Node** hash_table = NULL;
size_t table_size = 0;

void init_hash_table(size_t size) {
    if (hash_table != NULL) free(hash_table);

    hash_table = calloc(size, sizeof(Node*));
    table_size = size;
}

unsigned long hash(long key) {
    return key % table_size;
}

void add_record(Record* record) {
    unsigned long index = hash(record->large_integer);

    Node* node = malloc(sizeof(Node));
    if (node == NULL) return;

    node->record = record;
    node->next = hash_table[index];
    hash_table[index] = node;
}

Record* get_record(long key) {
    unsigned long index = hash(key);

    Node* node = hash_table[index];
    while (node != NULL && node->record->large_integer != key) {
        node = node->next;
    }

    return node == NULL ? NULL : node->record;
}

void remove_record(long key) {
    unsigned long index = hash(key);

    Node* prev = NULL;
    Node* node = hash_table[index];
    while (node != NULL && node->record->large_integer != key) {
        prev = node;
        node = node->next;
    }

    if (node == NULL) return;

    if (prev == NULL) {
        hash_table[index] = node->next;
    } else {
        prev->next = node->next;
    }

    delete_record(node->record);
    free(node);
}
```
This code assumes that the large integer is unique for each record, which allows it to use a hash table for efficient lookup. It also assumes that the string buffer length will not exceed the maximum size of a `char*`, and that the hash function will distribute keys evenly across the table. 

The performance of this code under high load depends on the quality of the hash function and the distribution of large integers in the records. If the hash function is poor or if the large integers are not well distributed, the hash table may become unbalanced and operations could degrade to O(n) time complexity instead of O(1). 

This code does not handle thread safety. To make it thread-safe, you would need to add locks around any critical sections (e.g., when adding or removing records), which could significantly slow down the function under high load. However, this will also increase memory usage and potentially introduce other concurrency issues. 

This code does not include logging. To implement logging, you could replace `printf` statements with calls to a logging library or system. The specifics of how to do this would depend on your chosen logging mechanism. 

Finally, this code assumes that the string buffer length will not exceed the maximum size of a `char*`. If this is not true, you may need to use a different data type for the string buffer. This could involve using a dynamically resizing array or other similar data structure.
