['Here's an example of how you might implement such a library in C. This code does not include all the features you requested (like garbage collection or logging), but it provides a basic structure for managing memory for different types of elements. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    INT,
    FLOAT,
    STRING,
    CUSTOM_DATA,
    FILE_DESCRIPTOR
} DataType;

typedef struct Node {
    void* data;
    size_t size;
    DataType type;
    struct Node* next;
    struct Node* prev;
} Node;

Node* head = NULL;

void* allocateMemory(size_t size, DataType type) {
    void* ptr = malloc(size);

    if (ptr == NULL) {
        fprintf(stderr, "Failed to allocate memory.\n");
        exit(EXIT_FAILURE);
    }

    Node* node = malloc(sizeof(Node));

    if (node == NULL) {
        free(ptr);
        fprintf(stderr, "Failed to create list node.\n");
        exit(EXIT_FAILURE);
    }

    node->data = ptr;
    node->size = size;
    node->type = type;
    node->next = NULL;
    node->prev = NULL;

    if (head == NULL) {
        head = node;
    } else {
        Node* current = head;

        while (current->next != NULL) {
            current = current->next;
        }

        current->next = node;
        node->prev = current;
    }

    return ptr;
}

void freeMemory() {
    Node* current = head;

    while (current != NULL) {
        Node* next = current->next;

        free(current->data);
        free(current);

        current = next;
    }

    head = NULL;
}
```
This code provides a basic linked list structure for managing memory. Each node in the list contains a pointer to the allocated memory, its size, and its type. The `allocateMemory` function allocates memory of a specified size and type, creates a new node for it, and adds it to the end of the list. The `freeMemory` function traverses the list and frees all allocated memory, as well as cleaning up the list nodes.

