#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    long timestamp;
    int status;
} NICB;

NICB* nicb_array[10000];
int nicb_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_nicb(int id, long timestamp, int status) {
    pthread_mutex_lock(&lock);
    if (nicb_count < 10000) {
        NICB* nicb = malloc(sizeof(NICB));
        nicb->id = id;
        nicb->timestamp = timestamp;
        nicb->status = status;
        nicb_array[nicb_count++] = nicb;
    } else {
        printf("Error: Maximum NICBs reached\n");
    }
    pthread_mutex_unlock(&lock);
}

void remove_nicb(int index) {
    pthread_mutex_lock(&lock);
    if (index < nicb_count) {
        free(nicb_array[index]);
        nicb_array[index] = NULL;
        for (int i = index; i < nicb_count - 1; ++i) {
            nicb_array[i] = nicb_array[i + 1];
        }
        --nicb_count;
    } else {
        printf("Error: Index out of bounds\n");
    }
    pthread_mutex_unlock(&lock);
}

int find_largest() {
    int max = -1;
    for (int i = 0; i < nicb_count; ++i) {
        if (nicb_array[i]->id > max) {
            max = nicb_array[i]->id;
        }
    }
    return max;
}

void read_and_find() {
    int n, i;
    scanf("%d", &n);
    if (n <= 0) {
        printf("Error: Zero-sized array\n");
        return;
    }
    int* arr = malloc(sizeof(int) * n);
    for (i = 0; i < n; ++i) {
        scanf("%d", &arr[i]);
    }
    printf("Largest number: %d\n", find_largest(arr, n));
    free(arr);
}
```
