#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <errno.h>

typedef struct file_metadata {
    time_t timestamp;
    off_t size;
} file_metadata;

typedef struct directory_entry {
    char *path;
    file_metadata metadata;
} directory_entry;

int read_directory(const char* path, directory_entry** entries) {
    FILE *fp = fopen(path, "r");
    if (fp == NULL) {
        printf("Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp)) {
        // Assuming each line is in the format "path timestamp size"
        char *token = strtok(line, " ");
        if (token == NULL) continue;

        directory_entry* entry = malloc(sizeof(directory_entry));
        entry->path = strdup(token);

        token = strtok(NULL, " ");
        if (token != NULL) {
            errno = 0;
            char *endptr;
            entry->metadata.timestamp = strtol(token, &endptr, 10);
            if (*endptr != '\0' || errno != 0) {
                printf("Invalid timestamp: %s\n", token);
                free(entry->path);
                free(entry);
                continue;
            }
        }

        token = strtok(NULL, " ");
        if (token != NULL) {
            errno = 0;
            char *endptr;
            entry->metadata.size = strtol(token, &endptr, 10);
            if (*endptr != '\0' || errno != 0) {
                printf("Invalid size: %s\n", token);
                free(entry->path);
                free(entry);
                continue;
            }
        }

        *entries = realloc(*entries, (count + 1) * sizeof(directory_entry));
        (*entries)[count++] = entry;
    }

    fclose(fp);
    return count;
}
```
