        if (records[i]->num > max->num) {
            max = records[i];
        }
    }

    return max;
}

void read_input() {
    double nums[50000];
    int count = 0;
    double min, max;

    while (scanf("%lf", &nums[count]) != EOF && count < 50000) {
        ++count;
    }

    if (count == 0) {
        printf("No input\n");
        return;
    }

    min = max = nums[0];

    for (int i = 1; i < count; ++i) {
        if (nums[i] > max) {
            max = nums[i];
        } else if (nums[i] < min) {
            min = nums[i];
        }
    }

    printf("Smallest: %.2lf\n", min);
    printf("Largest: %.2lf\n", max);
}

int main() {
    logfile = fopen("log.txt", "w");
    pthread_mutex_init(&lock, NULL);

    // Initialize records in a separate thread to demonstrate thread safety
    pthread_t thread;
    pthread_create(&thread, NULL, thread_func, (void*)50000);

    read_input();

    Record *max = find_largest();
    printf("Largest record: %s\n", max->str);

    pthread_join(thread, NULL);
    free_records();
    fclose(logfile);

    return 0;
}
```
