#include <string.h>
#include <sys/stat.h>
#include <stdbool.h>

typedef struct {
    int value;
} Record;

void* allocate_and_initialize(size_t size, bool isRecord) {
    if (size == 0) return NULL;

    void* data = malloc(size * (isRecord ? sizeof(Record) : sizeof(int)));
    if (!data) exit(EXIT_FAILURE); // Handle memory allocation failure

    srand((unsigned int) time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < size; ++i) {
        if (isRecord) ((Record*)data)[i].value = rand();
        else ((int*)data)[i] = rand();
    }

    return data;
}

void persist(const char* filename, Record* records, size_t recordCount) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);

    if (fd == -1) {
        // Handle file I/O error
        return;
    }

    ssize_t bytesWritten = write(fd, records, recordCount * sizeof(Record));

    if (bytesWritten == -1 || (size_t)bytesWritten != recordCount * sizeof(Record)) {
        // Handle file I/O error
        close(fd);
        return;
    }

    close(fd);
}

void* load(const char* filename, size_t* recordCount) {
    int fd = open(filename, O_RDONLY);

    if (fd == -1) {
        // Handle file I/O error
        return NULL;
    }

    struct stat st;
    if (fstat(fd, &st) == -1) {
        // Handle file I/O error
        close(fd);
        return NULL;
    }

    *recordCount = st.st_size / sizeof(Record);
    Record* records = malloc(*recordCount * sizeof(Record));

    if (!records) {
        // Handle memory allocation failure
        close(fd);
        return NULL;
    }

    ssize_t bytesRead = read(fd, records, st.st_size);

    if (bytesRead == -1 || (size_t)bytesRead != st.st_size) {
        // Handle file I/O error
        free(records);
        close(fd);
        return NULL;
    }

    close(fd);

    return records;
}
```
