#include <string.h>

typedef struct Node {
    double value;
    struct Node* next;
} Node;

Node* createList() {
    Node *head = NULL, *tail = NULL;
    char buffer[256];

    while (fgets(buffer, sizeof(buffer), stdin)) {
        if (strcmp(buffer, "\n") == 0) break;  // termination token

        double value = strtod(buffer, NULL);
        Node* node = malloc(sizeof(Node));
        if (!node) {
            fprintf(stderr, "Memory allocation failed\n");
            freeList(head);
            return NULL;
        }

        node->value = value;
        node->next = NULL;

        if (tail) {
            tail->next = node;
            tail = node;
        } else {
            head = tail = node;
        }
    }

    return head;
}

void freeList(Node* head) {
    while (head) {
        Node* next = head->next;
        free(head);
        head = next;
    }
}

double calculateAverage(Node* head) {
    double sum = 0.0;
    int count = 0;

    while (head) {
        sum += head->value;
        ++count;
        head = head->next;
    }

    return count ? sum / count : 0.0;
}
```
This code creates a linked list of nodes, each containing a double value and a pointer to the next node. It reads floating point numbers from standard input until it encounters a newline character followed by EOF. If memory allocation fails during this process, it frees all previously allocated memory and returns NULL. The function `calculateAverage` calculates the average of all values in the list.

