#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct Record {
    int value;
    int* key;
    size_t refCount;
    pthread_mutex_t lock;
} Record;

Record** records = NULL;
size_t recordCount = 0;
pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;
FILE* logFile = NULL;
int errorCode = 0;

void initLogging() {
    logFile = fopen("log.txt", "a");
}

void logOperation(const char* operation, Record* record) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char buffer[80];
    strftime(buffer, 80, "%Y-%m-%d %H:%M:%S", timeinfo);

    pthread_mutex_lock(&globalLock);
    fprintf(logFile, "[%s] Operation: %s, Value: %d, Key: %p\n", buffer, operation, record->value, record->key);
    fflush(logFile);
    pthread_mutex_unlock(&globalLock);
}

Record* createRecord(int value, int* key) {
    Record* newRecord = malloc(sizeof(Record));
    if (newRecord == NULL) {
        errorCode = 1; // Memory allocation failure
        return NULL;
    }

    newRecord->value = value;
    newRecord->key = key;
    newRecord->refCount = 0;
    pthread_mutex_init(&newRecord->lock, NULL);

    logOperation("Create", newRecord);

    return newRecord;
}

void accessRecord(Record* record) {
    pthread_mutex_lock(&record->lock);
    record->refCount++;
    pthread_mutex_unlock(&record->lock);

    logOperation("Access", record);
}

void deleteRecord(Record* record) {
    pthread_mutex_lock(&globalLock);
    for (size_t i = 0; i < recordCount; ++i) {
        if (records[i] == record) {
            records[i] = NULL;
            break;
        }
    }

    pthread_mutex_unlock(&globalLock);
    logOperation("Delete", record);
    free(record);
}
```
