#include <string.h>
#include <uuid/uuid.h>

typedef enum {
    TODO,
    IN_PROGRESS,
    DONE
} Status;

typedef struct {
    int priority;
    Status status;
    char* description;
    uuid_t id;
} Task;

typedef struct Node {
    Task task;
    struct Node* next;
} Node;

Node* head = NULL; // Priority queue
Task** tasks = NULL; // Dynamic array for tasks
int size = 0, capacity = 10;

void add_task(Task task) {
    if (size == capacity) {
        capacity *= 2;
        tasks = realloc(tasks, sizeof(Task*) * capacity);
    }

    Task* new_task = malloc(sizeof(Task));
    memcpy(new_task, &task, sizeof(Task));
    tasks[size++] = new_task;

    Node* node = malloc(sizeof(Node));
    node->task = task;
    node->next = NULL;

    if (head == NULL || head->task.priority < task.priority) {
        node->next = head;
        head = node;
    } else {
        Node* current = head;
        while (current->next != NULL && current->next->task.priority >= task.priority) {
            current = current->next;
        }
        node->next = current->next;
        current->next = node;
    }
}

Task* get_task(uuid_t id) {
    for (int i = 0; i < size; ++i) {
        if (uuid_compare(id, tasks[i]->id) == 0) {
            return tasks[i];
        }
    }

    return NULL;
}

void update_task(Task task) {
    Task* existing = get_task(task.id);
    if (existing != NULL) {
        memcpy(existing, &task, sizeof(Task));
    } else {
        add_task(task);
    }
}

void print_tasks() {
    Node* current = head;
    while (current != NULL) {
