#include <string.h>

typedef struct {
    int key;
    long offset;
} record;

record* records = NULL;
size_t num_records = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *file = NULL;
const char *filename = "data.bin";

void* allocate_memory(size_t size) {
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_records() {
    int min = 1, max = 100; // example range, should be user input
    num_records = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE); // total system memory

    records = allocate_memory(num_records * sizeof(record));

    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = min + rand() % ((max + 1) - min); // random value within range
        records[i].offset = i * sizeof(record);
    }
}

void* read_records(size_t index) {
    pthread_mutex_lock(&mutex);

    if (index >= num_records) {
        printf("Index out of bounds\n");
        return NULL;
    }

    record *r = &records[index];

    pthread_mutex_unlock(&mutex);

    return r;
}

void write_records(size_t index, int key) {
    pthread_mutex_lock(&mutex);

    if (index >= num_records) {
        printf("Index out of bounds\n");
        return;
    }

    records[index].key = key;

    pthread_mutex_unlock(&mutex);
}

void serialize() {
    file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&mutex);

    size_t elements_written = fwrite(records, sizeof(record), num_records, file);
    if (elements_written != num_records) {
        printf("Failed to write all records\n");
    }

    pthread_mutex_unlock(&mutex);

    fclose(file);
}

void deserialize() {
    file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }

    pthread_mutex_lock(&mutex);

    size_t elements_read = fread(records, sizeof(record), num_records, file);
    if (elements_read != num_records) {
        printf("Failed to read all records\n");
    }

    pthread_mutex_unlock(&mutex);

    fclose(file);
}
```
