```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    int* key;
    size_t refCount;
} Record;

typedef struct Collection {
    Record** records;
    size_t count;
    pthread_mutex_t lock;
} Collection;

void initCollection(Collection* collection) {
    collection->records = NULL;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

int addRecord(Collection* collection, int value, int* key) {
    Record* record = malloc(sizeof(Record));
    if (record == NULL) return -1; // Memory allocation failure

    record->value = value;
    record->key = key;
    record->refCount = 0;

    pthread_mutex_lock(&collection->lock);
    collection->records = realloc(collection->records, (collection->count + 1) * sizeof(Record*));
    if (collection->records == NULL) return -1; // Memory allocation failure

    collection->records[collection->count] = record;
    collection->count++;
    pthread_mutex_unlock(&collection->lock);

    return 0; // Success
}

Record* getRecord(Collection* collection, int index) {
    if (index < 0 || index >= collection->count) return NULL; // Index out of bounds

    pthread_mutex_lock(&collection->lock);
    Record* record = collection->records[index];
    record->refCount++;
    pthread_mutex_unlock(&collection->lock);

    return record;
}

void removeRecord(Collection* collection, int index) {
    if (index < 0 || index >= collection->count) return; // Index out of bounds

    pthread_mutex_lock(&collection->lock);
    Record* record = collection->records[index];
    free(record);

    for (int i = index; i < collection->count - 1; i++) {
        collection->records[i] = collection->records[i + 1];
    }

    collection->count--;
    pthread_mutex_unlock(&collection->lock);
}
```
