#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    STATE_OK,
    STATE_ERROR
} state;

typedef struct {
    char* name;
    double value;
    state status;
} config;

config* configurations = NULL;
size_t numConfigurations = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
const char* CONFIG_FILENAME = "config.dat";
double MEMORY_USAGE_LIMIT = 0.9; // 90% of available memory
size_t MAX_CONFIGURATIONS = (size_t)(MEMORY_USAGE_LIMIT * sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGESIZE)) / sizeof(config);

void* allocateMemoryForConfigurations() {
    if (numConfigurations >= MAX_CONFIGURATIONS) {
        fprintf(stderr, "Error: Memory limit exceeded.\n");
        return NULL;
    }

    configurations = realloc(configurations, sizeof(config) * ++numConfigurations);
    if (configurations == NULL) {
        numConfigurations--;
        fprintf(stderr, "Error: Failed to allocate memory.\n");
    }

    return configurations + numConfigurations - 1;
}

void updateConfiguration(size_t index, const char* name, double value, state status) {
    if (index >= numConfigurations) {
        fprintf(stderr, "Error: Invalid configuration index.\n");
        return;
    }

    pthread_mutex_lock(&mutex);
    configurations[index].name = strdup(name);
    configurations[index].value = value;
    configurations[index].status = status;
    pthread_mutex_unlock(&mutex);
}

void saveConfigurationsToDisk() {
    FILE* file = fopen(CONFIG_FILENAME, "wb");
    if (file == NULL) {
        fprintf(stderr, "Error: Failed to open file for writing.\n");
        return;
    }

    pthread_mutex_lock(&mutex);
    size_t numWritten = fwrite(configurations, sizeof(config), numConfigurations, file);
    pthread_mutex_unlock(&mutex);

    if (numWritten != numConfigurations) {
        fprintf(stderr, "Error: Failed to write all configurations.\n");
    }

    fclose(file);
}

void loadConfigurationsFromDisk() {
    FILE* file = fopen(CONFIG_FILENAME, "rb");
    if (file == NULL) {
        fprintf(stderr, "Error: Failed to open file for reading.\n");
        return;
    }

    pthread_mutex_lock(&mutex);
    size_t numRead = fread(configurations, sizeof(config), numConfigurations, file);
    pthread_mutex_unlock(&mutex);

    if (numRead != numConfigurations) {
        fprintf(stderr, "Error: Failed to read all configurations.\n");
    }

    fclose(file);
}
