#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long* offset;
} Record;

int allocate_memory(long** offsets, int** keys, Record*** records, size_t count) {
    if (count > INT_MAX / 2 || count * 2 > INT_MAX) {
        return -1; // Error: count exceeds maximum key count
    }

    srand(time(NULL));

    *offsets = malloc(sizeof(long) * count);
    if (*offsets == NULL) {
        return -2; // Error: memory allocation failed for offsets
    }

    *keys = malloc(sizeof(int) * (count / 2));
    if (*keys == NULL) {
        free(*offsets);
        return -3; // Error: memory allocation failed for keys
    }

    *records = malloc(sizeof(Record) * count / 2);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -4; // Error: memory allocation failed for records
    }

    int last_value = 0;
    for (size_t i = 0; i < count / 2; ++i) {
        int value = rand();
        while (value == last_value) {
            value = rand();
        }

        (*records)[i].value = value;
        (*records)[i].offset = &(*offsets)[i];

        last_value = value;
    }

    return 0; // Success
}
