int manage_memory(long maxSize, int minValue, int maxValue) {
    // Validate inputs
    if (maxSize <= 0 || minValue >= maxValue) return -1;

    srand(time(NULL));  // Seed the random number generator

    long* offsets = malloc(sizeof(long) * maxSize);
    if (!offsets) return -2;  // Memory allocation failed

    int numKeys = maxSize / 2;
    int* keys = calloc(numKeys, sizeof(int));
    if (!keys) {
        free(offsets);
        return -3;  // Memory allocation failed
    }

    Record* records = malloc(sizeof(Record) * numKeys);
    if (!records) {
        free(offsets);
        free(keys);
        return -4;  // Memory allocation failed
    }

    int lastValue = 0;
    for (int i = 0; i < numKeys; ++i) {
        int value = rand() % (maxValue - minValue + 1) + minValue;
        while (value == lastValue) {  // Ensure no duplicate values
            value = rand() % (maxValue - minValue + 1) + minValue;
        }
        records[i].value = value;
        records[i].offset = &offsets[i];
        keys[i] = value;
    }

    // Use the allocated memory...

    free(records);
    free(keys);
    free(offsets);

    return 0;  // Success
}
