void* flush_data(void* arg) {
    while (1) {
        sleep(60); // Flush data every minute
        pthread_mutex_lock(&lock);
        // Write to disk here...
        fprintf(logfile, "Flushing data to disk\n");
        pthread_mutex_unlock(&lock);
    }
}

int load_config() {
    FILE* file = fopen("config.txt", "r");
    if (file == NULL) {
        return -1; // Error opening file
    }

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        int key;
        double value;
        char string[256];
        float score;

        if (sscanf(buffer, "%d %lf %s %f", &key, &value, string, &score) != 4) {
            return -1; // Error parsing line
        }

        Node* new_node = malloc(sizeof(Node));
        if (new_node == NULL) {
            return -1; // Memory allocation error
        }
        new_node->key = key;
        new_node->value = value;
        new_node->next = head_node;
        head_node = new_node;

        Record* new_record = malloc(sizeof(Record));
        if (new_record == NULL) {
            return -1; // Memory allocation error
        }
        new_record->string = strdup(string);
        new_record->score = score;
        new_record->next = head_record;
        head_record = new_record;
    }

    fclose(file);
    return 0; // Success
}

int verify_data() {
    Node* node = head_node;
    Record* record = head_record;
    while (node != NULL && record != NULL) {
        if (node->key < 0 || node->value < 0.0 || strlen(record->string) == 0 || record->score < 0.0f) {
            return -1; // Invalid data
        }
        node = node->next;
        record = record->next;
    }

    if (node != NULL || record != NULL) {
        return -1; // Different number of nodes and records
    }

    return 0; // Success
}

int export_to_json() {
    json_t* root = json_object();
    json_t* array = json_array();

    Node* node = head_node;
    Record* record = head_record;
    while (node != NULL && record != NULL) {
        json_t* obj = json_pack("{sisd}", "key", node->key, "value", node->value, "string", record->string, "score", record->score);
        json_array_append(array, obj);

        node = node->next;
        record = record->next;
