    double value;
    struct Node* next;
} Node;

Node* create_list(int size, double min, double max) {
    if (size <= 0) return NULL;

    srand((unsigned int)time(NULL)); // seed the random number generator
    Node *head = malloc(sizeof(Node));
    assert(head != NULL); // check for memory allocation failure

    head->value = min + (max - min) * ((double)rand() / RAND_MAX);
    Node *current = head;

    for (int i = 1; i < size; ++i) {
        current->next = malloc(sizeof(Node));
        assert(current->next != NULL); // check for memory allocation failure

        current = current->next;
        current->value = min + (max - min) * ((double)rand() / RAND_MAX);
    }

    current->next = NULL;
    return head;
}

void free_list(Node* list) {
    Node* next;
    for (Node* current = list; current != NULL; current = next) {
        next = current->next;
        free(current);
    }
}
