    // Open the file and read records
    fileData->fileHandle = fopen(fileData->filePath, "r");
    if (!fileData->fileHandle) {
        return NULL;
    }

    // Allocate memory for records
    fileData->records = malloc(sizeof(Record*) * 1024); // Assuming a maximum of 1024 records per file
    if (!fileData->records) {
        return NULL;
    }

    int key;
    long offset;
    while (fscanf(fileData->fileHandle, "%d %ld", &key, &offset) == 2) {
        Record* record = malloc(sizeof(Record));
        if (!record) {
            return NULL;
        }

        record->key = key;
        record->offset = offset;

        fileData->records[fileData->recordCount++] = record;
    }

    // Sort records by key
    qsort(fileData->records, fileData->recordCount, sizeof(Record*), compareRecords);

    // Calculate MD5 hash of the file
    calculateMD5Hash(fileData->fileHandle, fileData->md5Digest);

