    init_random(seed);

    // Calculate the memory usage per record.
    const size_t record_size = sizeof(Record);
    if (record_size > max_memory_kb * 1024) {
        log_memory_allocation_failure("Not enough memory to allocate records.");
        return NULL;
    }

    // Allocate the array of records.
    Record* records = malloc(num_records * record_size);
    if (records == NULL) {
        log_memory_allocation_failure("Failed to allocate memory for records.");
        return NULL;
    }

    // Allocate the array of keys.
    int* keys = malloc(num_records * sizeof(int));
    if (keys == NULL) {
        log_memory_allocation_failure("Failed to allocate memory for keys.");
        free(records);
        return NULL;
    }

    // Initialize the records and keys.
    int* used_keys = calloc(max_key - min_key + 1, sizeof(int));
    if (used_keys == NULL) {
        log_memory_allocation_failure("Failed to allocate memory for used keys.");
        free(records);
        free(keys);
        return NULL;
    }

    int key;
    *records_allocated = 0;
    for (int i = 0; i < num_records; ++i) {
        // Generate a unique random key.
        do {
            key = rand() % (max_key - min_key + 1) + min_key;
        } while (used_keys[key - min_key]);

        used_keys[key - min_key] = 1;
        keys[i] = key;

        // Initialize the record.
        records[i].offset = i;
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    free(used_keys);
    *records_allocated = num_records;
    return records;
}
