```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Define your LTE_ENB_RRC_MESSAGE_T, ENB_RRC_CONFIG_DCI_T and RRC_CONNECTION_RECONFIGURATION_TAG structures here
} LTE_ENB_RRC_MESSAGE_T;

typedef struct {
    int key;
    LTE_ENB_RRC_MESSAGE_T record;
} Record;

typedef struct {
    pthread_mutex_t mutex;
    long* offsets;
    Record* records;
    size_t capacity;
    size_t count;
} NetworkConfigSystem;

int initNetworkConfigSystem(NetworkConfigSystem* system, size_t initialCapacity) {
    if (pthread_mutex_init(&system->mutex, NULL) != 0) {
        return -1; // Failed to initialize mutex
    }

    system->offsets = malloc(initialCapacity * sizeof(long));
    if (system->offsets == NULL) {
        pthread_mutex_destroy(&system->mutex);
        return -1; // Failed to allocate memory for offsets
    }

    system->records = malloc(initialCapacity * sizeof(Record));
    if (system->records == NULL) {
        free(system->offsets);
        pthread_mutex_destroy(&system->mutex);
        return -1; // Failed to allocate memory for records
    }

    system->capacity = initialCapacity;
    system->count = 0;

    return 0; // Successfully initialized the network configuration system
}
```
This code defines a `NetworkConfigSystem` struct that contains a mutex for thread safety, an array of offset values, and an array of records. The `initNetworkConfigSystem` function initializes this structure with a given initial capacity. It also handles memory allocation errors by freeing any previously allocated memory before returning an error code.

