void addToArray(DynamicArray* array, Record* record) {
    pthread_mutex_lock(&array->lock);

    if (atomic_load(&array->size) % 10 == 0 && atomic_load(&array->size) != 0) { // If size is a multiple of 10, resize the array
        array->records = realloc(array->records, (atomic_load(&array->size) + 10) * sizeof(Record*));
    }

