typedef struct {
    // LTE_ENB_RRC_MESSAGE_T, ENB_RRC_CONFIG_DCI_T and RRC_CONNECTION_RECONFIGURATION_TAG fields here
} record;

typedef enum { ADD, REMOVE, MODIFY } change_type;

typedef struct change_node {
    int timestamp;
    change_type type;
    record* affected_record;
    struct change_node* next;
} change_node;

typedef struct {
    long* offsets;
    atomic_int* keys;
    record** records;
    pthread_mutex_t mutex;
    change_node* changes_head;
    // Other fields here...
} network_config_system;

network_config_system* init_network_config_system(size_t size) {
    network_config_system* system = malloc(sizeof(network_config_system));
    if (system == NULL) return NULL;

    system->offsets = calloc(size, sizeof(long));
    system->keys = calloc(size, sizeof(atomic_int));
    system->records = calloc(size, sizeof(record*));
    if (system->offsets == NULL || system->keys == NULL || system->records == NULL) {
        free(system->offsets);
        free(system->keys);
        free(system->records);
        free(system);
        return NULL;
    }

    pthread_mutex_init(&system->mutex, NULL);
    system->changes_head = NULL;
    // Other initialization here...

    return system;
}

void destroy_network_config_system(network_config_system* system) {
    pthread_mutex_lock(&system->mutex);

    free(system->offsets);
    free(system->keys);
    for (size_t i = 0; i < size; ++i) {
        if (system->records[i] != NULL) {
            // Free record and its contents...
            free(system->records[i]);
        }
    }
    free(system->records);

    change_node* node = system->changes_head;
    while (node != NULL) {
        change_node* next = node->next;
        // Free change_node...
        free(node);
        node = next;
    }

    pthread_mutex_unlock(&system->mutex);
    pthread_mutex_destroy(&system->mutex);
    free(system);
}
```
