    public List<Object> processByteArray(byte[] compressedData, String compressionAlgorithm) throws Exception {
        byte[] decompressedData = decompress(compressedData, compressionAlgorithm);

        ByteArrayInputStream bais = new ByteArrayInputStream(decompressedData);
        ObjectInputStream ois = new ObjectInputStream(bais);

        List<Object> objects = new ArrayList<>();
        while (true) {
            try {
                Object obj = ois.readObject();

