    private byte[] decompress(byte[] compressedData, String compressionAlgorithm) throws Exception {
        ByteArrayInputStream bais = new ByteArrayInputStream(compressedData);
        InflaterInputStream iis = null;

        if (compressionAlgorithm.equals("gzip")) {
            iis = new GZIPInputStream(bais);
        } else if (compressionAlgorithm.equals("deflate")) {
            iis = new InflaterInputStream(bais);
        } else {
