} Record;

int initRecords(Record** records, size_t numRecords) {
    srand((unsigned int)time(NULL)); // seed the random number generator

    *records = (Record*)calloc(numRecords, sizeof(Record));
    if (*records == NULL) {
        return -1; // allocation failed
    }

    for (size_t i = 0; i < numRecords; ++i) {
        (*records)[i].entry = (StructEntry*)malloc(sizeof(StructEntry));
        if ((*records)[i].entry == NULL) {
            // allocation failed, clean up and return error
            for (size_t j = 0; j < i; ++j) {
                free((*records)[j].entry);
            }
            free(*records);
            *records = NULL;
            return -1;
        }

        (*records)[i].entry->value = (float)(rand() % 100) / 10.0f; // random float value between 0 and 9.9
        (*records)[i].entry->flag = rand() % 2 == 0 ? true : false; // random bool value

        size_t keyLength = 1 + (rand() % 10); // random string length between 1 and 10
        for (size_t j = 0; j < keyLength; ++j) {
            (*records)[i].CharKey[j] = 'A' + rand() % ('Z' - 'A'); // random ASCII character
        }
        (*records)[i].CharKey[keyLength] = '\0'; // null terminator
    }

    return 0; // success
}
