    atomic_int refcount;
    pthread_mutex_t lock;
} record;

typedef struct {
    int param1;
    char* param2;
} config;

config* init_config(int param1, const char* param2) {
    config* c = malloc(sizeof(config));
    if (c == NULL) return NULL;

    c->param1 = param1;
    c->param2 = strdup(param2);
    if (c->param2 == NULL) {
        free(c);
        return NULL;
    }

    return c;
}

void destroy_config(config* c) {
    free(c->param2);
    free(c);
}

record* init_record(float value, entry* e, config* c) {
    record* r = malloc(sizeof(record));
    if (r == NULL) return NULL;

    r->value = value;
    r->e = e;
    atomic_init(&r->refcount, 1);
    pthread_mutex_init(&r->lock, NULL);

    return r;
}

void destroy_record(record* r) {
    free(r->e);
    pthread_mutex_destroy(&r->lock);
    free(r);
}

int add_ref(record* r) {
    return atomic_fetch_add(&r->refcount, 1);
}

int release(record* r) {
    int count = atomic_fetch_sub(&r->refcount, 1) - 1;

    if (count == 0) {
        destroy_record(r);
    }

    return count;
}
```
