void allocate_and_initialize(long *offsets, int *keys, Record **records, size_t limit) {
    srand(time(NULL)); // seed the random number generator

    long total_size = 0;
    int num_records = 0;

    while (total_size < limit && num_records < INT_MAX) {
        long offset = rand() % limit; // generate a random offset within the limit

        if (offset + sizeof(Record) > limit) { // check if adding this record would exceed the limit
            break;
        }

