        record->value = rand() % 100 + 1; // initialize the record with a random value between 1 and 100

        offsets[num_records] = offset;
        keys[num_records] = key;
        records[num_records] = record;

        total_size += sizeof(Record); // update the total size of allocated memory
        num_records++; // increment the number of records created
    }

