#include <stdlib.h>
#include <time.h>

typedef struct data_item {
    float value;
    int ref_count;
    struct data_item *next;
} data_item;

typedef struct node {
    int key;
    data_item *list;
} node;

node* create_nodes(int num_nodes, int num_items) {
    srand((unsigned int)time(NULL));

    // Allocate memory for nodes
    node *nodes = (node*)malloc(num_nodes * sizeof(node));
    if (!nodes) return NULL;

    for (int i = 0; i < num_nodes; ++i) {
        nodes[i].key = i; // Set key

        data_item **tail = &(nodes[i].list);
        for (int j = 0; j < num_items; ++j) {
            *tail = malloc(sizeof(data_item));
            if (!(*tail)) return NULL; // Handle allocation failure

            (*tail)->value = ((float)rand()/(float)(RAND_MAX)) * 1.0f; // Set random float value
            (*tail)->ref_count = 0; // Initialize reference count

            tail = &((*tail)->next); // Move to next item in list
        }
        *tail = NULL; // End of list
    }

    return nodes;
}

void free_nodes(node *nodes, int num_nodes) {
    for (int i = 0; i < num_nodes; ++i) {
        data_item *next;

        // Free all items in list
        for (data_item *curr = nodes[i].list; curr != NULL; curr = next) {
            next = curr->next;
            free(curr);
        }
    }

    free(nodes); // Free node array
}
```
This code creates an array of `node` structures, each containing a linked list of `data_item` structures. The `create_nodes` function allocates memory for the nodes and initializes them with random float values in their lists. It also sets the reference count to zero. 

