typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
} NICB;

// Global variables for thread safety and memory management
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
long totalMemoryUsed = 0;
int numRecordsCreated = 0;

NICB* initializeNICBs(int num, int minValue, int maxValue) {
    srand(time(NULL)); // Seed the random number generator

    NICB *nicbs = (NICB*) malloc(num * sizeof(NICB));
    if (nicbs == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < num; i++) {
        nicbs[i].offset = rand(); // Initialize offset with a random value

        if (nicbs[i].offset > maxValue || nicbs[i].offset < minValue) {
            printf("Invalid offset detected. Aborting initialization.\n");
            free(nicbs);
            return NULL;
        }

        nicbs[i].key = rand(); // Initialize key with a random value

        nicbs[i].record.value = minValue + (rand() % (maxValue - minValue + 1)); // Initialize record value within the given range
    }

    pthread_mutex_lock(&lock);
    totalMemoryUsed += num * sizeof(NICB);
    numRecordsCreated += num;
    printf("Total memory used: %ld bytes\n", totalMemoryUsed);
    printf("Number of records created: %d\n", numRecordsCreated);
    pthread_mutex_unlock(&lock);

    return nicbs;
}

void freeNICBs(NICB *nicbs) {
    if (nicbs != NULL) {
        free(nicbs);

        pthread_mutex_lock(&lock);
        totalMemoryUsed -= numRecordsCreated * sizeof(NICB);
        numRecordsCreated = 0;
        printf("Total memory used: %ld bytes\n", totalMemoryUsed);
        printf("Number of records created: %d\n", numRecordsCreated);
        pthread_mutex_unlock(&lock);
    }
}
```
This code initializes an array of NICBs with random offsets and keys, each containing a record with a value within the given range. It also handles thread safety for memory management and logging total memory used and number of records created. 

