    if(!config_read_file(cf, "settings.conf")) {
        fprintf(stderr, "%s:%d - %s\n", config_error_file(cf),
                config_error_line(cf), config_error_text(cf));
        config_destroy(cf);
        return;
    }

    // Read configuration settings from the file
    int max_queue_size, num_threads;
    if(!config_lookup_int(cf, "max_queue_size", &max_queue_size) ||
       !config_lookup_int(cf, "num_threads", &num_threads)) {
        fprintf(stderr, "No 'max_queue_size' or 'num_threads' setting in configuration file.\n");
