        enqueue(&queue, packet);

        if(atomic_load(&pool.count) < pool.capacity && atomic_load(&queue.count) > 0) {
            add_worker(&pool);
        }
    }

    // Cleanup
    for(size_t i = 0; i < queue.capacity; ++i) {
        custom_free(queue.packets[i]);
    }
    custom_free(queue.packets);

    for(size_t i = 0; i < pool.count; ++i) {
        pthread_join(pool.threads[i], NULL);
