    char source_ip[16];
    char destination_ip[16];
    int payload_size;
} NetworkEvent;

NetworkEvent* events = NULL;
int eventCount = 0, maxEvents = 0, largePayloadThreshold = 0;
pthread_mutex_t lock;

void readConfigFile(char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open config file.\n");
        return;
    }

    char line[100];
    while (fgets(line, sizeof(line), file)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (strcmp(key, "maxEvents") == 0) maxEvents = atoi(value);
        else if (strcmp(key, "largePayloadThreshold") == 0) largePayloadThreshold = atoi(value);
    }

    fclose(file);
}

void allocateMemory() {
    events = malloc(maxEvents * sizeof(NetworkEvent));
    if (events == NULL) {
        printf("Failed to allocate memory.\n");
        exit(-1);
    }
}

void deallocateMemory() {
    free(events);
}

void addEvent(char* timestamp, char* source_ip, char* destination_ip, int payload_size) {
    pthread_mutex_lock(&lock);

    if (eventCount >= maxEvents) {
        printf("Maximum number of events reached.\n");
        return;
    }

    strcpy(events[eventCount].timestamp, timestamp);
    strcpy(events[eventCount].source_ip, source_ip);
    strcpy(events[eventCount].destination_ip, destination_ip);
    events[eventCount].payload_size = payload_size;

    eventCount++;

    pthread_mutex_unlock(&lock);
}
