typedef struct {
    int value;
} record;

typedef struct {
    long offset;
    int key;
    record rec;
} data_structure;

// Function to initialize a single structure
data_structure* init_single(long seed, int min, int max) {
    srand(seed); // Seed the random number generator

    data_structure* ds = malloc(sizeof(data_structure));
    if (ds == NULL) {
        loglib_error("Memory allocation failed");
        return NULL;
    }

    ds->offset = rand();
    ds->key = rand() % max + min; // Random number within specified range
    ds->rec.value = rand();

    return ds;
}

// Function to initialize an array of structures
data_structure** init_array(int n, long seed, int min, int max) {
    data_structure** arr = malloc(n * sizeof(data_structure*));
    if (arr == NULL) {
        loglib_error("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        data_structure* ds = init_single(seed + i, min, max); // Use different seed for each structure
        if (ds == NULL) {
            loglib_error("Structure initialization failed");

            // Deallocate previously allocated memory in case of failure
            for (int j = 0; j < i; j++) {
                free(arr[j]);
            }
            free(arr);

            return NULL;
        }

        arr[i] = ds;
    }

    return arr;
}

// Function to find the structure with the largest key value
data_structure* find_largest(data_structure** arr, int n) {
    data_structure* max = arr[0];

    for (int i = 1; i < n; i++) {
        if (arr[i]->key > max->key) {
            max = arr[i];
        }
    }

    return max;
}

// Function to verify the integrity of the data
bool verify_data(data_structure** arr, int n) {
    for (int i = 0; i < n - 1; i++) {
        if (arr[i]->key > arr[i + 1]->key) {
            loglib_warning("Data integrity check failed");
            return false;
        }
    }

    return true;
}

// Function to handle dynamic workloads and scaling
bool handle_workload(int n, long seed, int min, int max) {
    data_structure** arr = init_array(n, seed, min, max);
    if (arr == NULL) {
        loglib_error("Array initialization failed");
        return false;
    }

    bool success = verify_data(arr, n);
    if (!success) {
        loglib_warning("Data integrity check failed");

        // Deallocate memory in case of failure
        for (int i = 0; i < n; i++) {
            free(arr[i]);
        }
        free(arr);

        return false;
    }

    data_structure* max = find_largest(arr, n);
    loglib_info("Structure with largest key: offset=%ld, key=%d, value=%d", max->offset, max->key, max->rec.value);

    // Deallocate memory after use
    for (int i = 0; i < n; i++) {
        free(arr[i]);
    }
    free(arr);

    return true;
}
