HashNode* create_hash_node(char* key, FileStats value) {
    HashNode* node = malloc(sizeof(HashNode));
    if (node == NULL) {
        // Handle allocation failure
        return NULL;
    }
    node->key = strdup(key);
    node->value = value;
    node->next = NULL;
    return node;
}

// Function to create a new hash table
