    HashTable* ht = malloc(sizeof(HashTable));
    if (ht == NULL) {
        // Handle allocation failure
        return NULL;
    }
    ht->size = size;
    ht->count = 0;
    ht->nodes = calloc(size, sizeof(HashNode*));
    if (ht->nodes == NULL) {
        // Handle allocation failure
        free(ht);
        return NULL;
    }
    return ht;
}

