        // Handle collision by chaining
        node->next = ht->nodes[index];
        ht->nodes[index] = node;
    }
    ht->count++;
}

// Function to read filenames and their metadata from a directory
void read_directory(HashTable* ht, char* dirname) {
    DIR* dir = opendir(dirname);
    if (dir == NULL) {
        // Handle I/O error
        return;
    }
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char* filename = entry->d_name;
        FileStats* fs = create_file_stats();
        if (fs == NULL) {
            // Handle allocation failure
            continue;
        }
        insert_into_hash_table(ht, filename, *fs);
    }
}

