import requests
import json
from time import sleep

def FetchAndParseData(url, fields_to_extract, timeout):
    for i in range(3):  # Retry logic up to three times
        try:
            response = requests.get(url, timeout=timeout)
            data = json.loads(response.text)

            filtered_data = {field: data[field] for field in fields_to_extract if field in data}

            # Check if all requested fields are present
            if len(filtered_data) != len(fields_to_extract):
                raise ValueError("Some requested fields were not found")

            return filtered_data
        except requests.exceptions.RequestException as e:
            print(f"Failed to fetch data from {url}. Attempt {i+1} of 3. Error: {str(e)}")
            sleep(timeout)  # Wait for timeout before next attempt

    raise Exception("Failed to fetch and parse data after three attempts")
```

