```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* name;
    int age;
    double balance;
} entry;

typedef struct {
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
    entry** entries;
} collection;

collection* create_collection() {
    collection* c = malloc(sizeof(collection));
    if (c == NULL) return NULL;

    pthread_mutex_init(&c->lock, NULL);
    c->count = 0;
    c->capacity = 10000;
    c->entries = malloc(sizeof(entry*) * c->capacity);

    return c;
}

void destroy_collection(collection* c) {
    for (size_t i = 0; i < c->count; ++i) {
        free(c->entries[i]->name);
        free(c->entries[i]);
    }

    free(c->entries);
    pthread_mutex_destroy(&c->lock);
    free(c);
}

int add_entry(collection* c, const char* name, int age, double balance) {
    if (c->count >= c->capacity) return -1; // out of memory

    entry* e = malloc(sizeof(entry));
    if (e == NULL) return -2; // out of memory

    e->name = strdup(name);
    if (e->name == NULL) {
        free(e);
        return -2; // out of memory
    }

    e->age = age;
    e->balance = balance;

    pthread_mutex_lock(&c->lock);
    c->entries[c->count++] = e;
    pthread_mutex_unlock(&c->lock);

    return 0; // success
}

void update_ages(collection* c, int factor) {
    for (size_t i = 0; i < c->count; ++i) {
        pthread_mutex_lock(&c->lock);
        c->entries[i]->age *= factor;
        pthread_mutex_unlock(&c->lock);
    }
}
