        container->records[i].value = rand() % 256; // generate a random value for the record
    }

    return container;
}

void destroy_data_container(DataContainer* container) {
    if (container != NULL) {
        free(container->offsets);
        free(container->keys);
        free(container->records);
        free(container);
    }
}

int contains(const int* array, int value, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        if (array[i] == value) {
            return 1; // found the value in the array
        }
    }

    return 0; // did not find the value in the array
}
```
This code creates a `DataContainer` struct that contains three arrays: offsets, keys, and records. It generates random values for each of these arrays while ensuring uniqueness constraints are met. The function returns a pointer to this data structure, which can be used by other parts of the system. When it's no longer needed, the `destroy_data_container` function should be called to free up the memory allocated for the struct and its contents.
