void deleteEntry(char* name) {
    pthread_mutex_lock(&lock);

    Node *temp = head, *prev;

    if (temp != NULL && strcmp(temp->data.name, name) == 0) {
        head = temp->next;  
        free(temp->data.name);
        free(temp);            
        return;
    }

    while (temp != NULL && strcmp(temp->data.name, name) != 0) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;

    prev->next = temp->next;

    free(temp->data.name);
    free(temp); 

    size--;

    pthread_mutex_unlock(&lock);
}
