typedef struct node {
    double data;
    char *str;
    struct node *next;
} Node;

int verify_list(Node *head, int n) {
    if (n == 0 || head == NULL) return 1; // Empty list is valid

    Node *current = head;
    for (int i = 0; i < n; ++i) {
        if (current->next == NULL) return 0; // Pointer to next node is null
        current = current->next;
    }

    return (current == head); // List should loop back to the start
}

int initialize_list(Node **head, int n) {
    if (n <= 0) {
        fprintf(stderr, "Error: Invalid input size.\n");
        return 0;
    }

    double *numbers = malloc(sizeof(double) * n);
    if (!numbers) {
        fprintf(stderr, "Error: Memory allocation failed for numbers array.\n");
        return 0;
    }

    // Read input from standard input
    for (int i = 0; i < n; ++i) {
        if (scanf("%lf", &numbers[i]) != 1) {
            fprintf(stderr, "Error: Invalid data encountered.\n");
            free(numbers);
            return 0;
        }
    }

    // Find maximum value
    double max_value = -DBL_MAX;
    for (int i = 0; i < n; ++i) {
        if (numbers[i] > max_value) max_value = numbers[i];
    }
    printf("Maximum value: %.2lf\n", max_value);

    // Initialize circular linked list
    *head = malloc(sizeof(Node));
    if (!(*head)) {
        fprintf(stderr, "Error: Memory allocation failed for head node.\n");
        free(numbers);
        return 0;
    }

    (*head)->data = numbers[0];
    (*head)->str = NULL; // No string data in this example
    Node *current = *head;

    for (int i = 1; i < n; ++i) {
        current->next = malloc(sizeof(Node));
        if (!current->next) {
            fprintf(stderr, "Error: Memory allocation failed for node %d.\n", i);
            free(numbers);
            return 0;
        }

        current = current->next;
        current->data = numbers[i];
        current->str = NULL; // No string data in this example
    }

    current->next = *head; // Make list circular

    free(numbers);

    if (!verify_list(*head, n)) {
        fprintf(stderr, "Error: List verification failed.\n");
        return 0;
    }

    return 1;
}
```
