public class PokemonWeaknessGenerator {
    private static final Logger logger = LoggerFactory.getLogger(PokemonWeaknessGenerator.class);
    private static final Gson gson = new Gson(); // JSON serializer

    private Map<String, String> weaknessCache = new HashMap<>(); // Caching mechanism
    private ExternalLibrary externalLib; // Assume this is an interface for the external library

    public PokemonWeaknessGenerator(ExternalLibrary lib) {
        this.externalLib = lib;
    }

    public String generatePokemonWeaknesses(List<Pokemon> pokemons) {
        List<Map<String, Object>> result = new ArrayList<>(); // JSON structure

        for (Pokemon p : pokemons) {
            Map<String, Object> weaknessData = new HashMap<>();

            String weakness;
            if (weaknessCache.containsKey(p.getType())) {
                weakness = weaknessCache.get(p.getType()); // Use cached data
            } else {
                try {
                    weakness = externalLib.fetchWeaknessData(p.getType()); // Fetch from library
                    weaknessCache.put(p.getType(), weakness); // Cache the result
                } catch (ExternalLibraryException e) {
                    logger.error("Failed to fetch weakness data for type: " + p.getType(), e);
                    weakness = "Unknown"; // Fallback value
                }
            }

            weaknessData.put("pokemonName", p.getName());
            weaknessData.put("weakness", weakness);

            result.add(weaknessData);
        }

        return gson.toJson(result); // Serialize to JSON
    }
}
