    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    record* records;
} RecordCollection;

RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection* collection = malloc(sizeof(RecordCollection));
    if (collection == NULL) return NULL;

    pthread_mutex_init(&collection->lock, NULL);
    collection->records = malloc(initial_capacity * sizeof(record));
    if (collection->records == NULL) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    return collection;
}

void destroy_collection(RecordCollection* collection) {
    pthread_mutex_destroy(&collection->lock);
    free(collection->records);
    free(collection);
}

int add_record(RecordCollection* collection, record rec) {
    if (pthread_mutex_lock(&collection->lock)) return -1;

    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        record* new_records = realloc(collection->records, new_capacity * sizeof(record));
        if (new_records == NULL) return -1;

        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->size++] = rec;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int delete_record(RecordCollection* collection, size_t index) {
    if (pthread_mutex_lock(&collection->lock)) return -1;

    if (index >= collection->size) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    memmove(collection->records + index, collection->records + index + 1, 
            (collection->size - index - 1) * sizeof(record));
    --collection->size;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}
