#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

typedef struct item {
    char* name;
    int count;
    float price;
} Item;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Item** allocate_and_initialize(size_t size, int min_count, int max_count, float min_price, float max_price) {
    if (size == 0 || min_count > max_count || min_price > max_price) {
        errno = EINVAL;
        return NULL;
    }

    pthread_mutex_lock(&lock);
    Item** items = malloc(size * sizeof(Item*));
    if (items == NULL) {
        pthread_mutex_unlock(&lock);
        errno = ENOMEM;
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        items[i] = malloc(sizeof(Item));
        if (items[i] == NULL) {
            // Free already allocated memory and unlock mutex before returning.
            while (i-- > 0) free(items[i]);
            free(items);
            pthread_mutex_unlock(&lock);

            errno = ENOMEM;
            return NULL;
        }

        items[i]->name = get_product_name();
        if (items[i]->name == NULL) {
            // Free already allocated memory and unlock mutex before returning.
            while (i-- > 0) free(items[i]);
            free(items);
            pthread_mutex_unlock(&lock);

            errno = ENOMEM;  // Or some other error code depending on the nature of get_product_name failure.
            return NULL;
        }

        items[i]->count = rand() % (max_count - min_count + 1) + min_count;
        items[i]->price = ((float)rand() / RAND_MAX) * (max_price - min_price) + min_price;
    }

    pthread_mutex_unlock(&lock);
    return items;
}
