For the MD5 hash computation, we use OpenSSL's `MD5` function to compute the hash of a large binary file in chunks. This approach dynamically adjusts the chunk size based on system resources and file characteristics:

```c
#define CHUNK_SIZE 1024*1024 // Adjust this value as needed

void computeMD5(const char* filename, unsigned char** md5) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) exit(-1); // Handle file opening failure

    MD5_CTX context;
    MD5_Init(&context);

    size_t bytesRead = 0;
    unsigned char buffer[CHUNK_SIZE];
    while ((bytesRead = fread(buffer, 1, CHUNK_SIZE, file)) > 0) {
        MD5_Update(&context, buffer, bytesRead);
    }

    *md5 = (unsigned char*)malloc(MD5_DIGEST_LENGTH);
    if (*md5 == NULL) exit(-1); // Handle memory allocation failure

    MD5_Final(*md5, &context);

    fclose(file);
}
