["Here's a basic implementation of the function in C using POSIX threads for thread safety and pthread_mutex_t for synchronization. This code does not include error handling or logging, which would be necessary for a production-level application. 

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int key;
    double timestamp;
    char status;
} record_t;

typedef struct {
    long* offsets;
    int* keys;
    record_t** records;
    size_t capacity;
    pthread_mutex_t lock;
} dataset_t;

dataset_t* init_dataset(size_t initial_capacity) {
    srand((unsigned int)time(NULL)); // seed the random number generator

    dataset_t* ds = malloc(sizeof(dataset_t));
    if (ds == NULL) return NULL;

    ds->offsets = calloc(initial_capacity, sizeof(long));
    ds->keys = calloc(initial_capacity, sizeof(int));
    ds->records = malloc(initial_capacity * sizeof(record_t*));
    if (ds->offsets == NULL || ds->keys == NULL || ds->records == NULL) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        ds->records[i] = malloc(sizeof(record_t));
        if (ds->records[i] == NULL) {
            // clean up previously allocated records
            for (--i; i >= 0; --i) free(ds->records[i]);
            free(ds->offsets);
            free(ds->keys);
            free(ds->records);
            free(ds);
            return NULL;
        }
    }

    ds->capacity = initial_capacity;
    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

void destroy_dataset(dataset_t* ds) {
    for (size_t i = 0; i < ds->capacity; ++i) free(ds->records[i]);

    pthread_mutex_destroy(&ds->lock);
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds);
}

void set_record(dataset_t* ds, size_t index, int key, char status) {
    pthread_mutex_lock(&ds->lock);

    if (index >= ds->capacity) {
        // reallocate records array with twice the capacity
        record_t** new_records = realloc(ds->records, 2 * ds->capacity * sizeof(record_t*));
        if (new_records == NULL) goto unlock;

        for (size_t i = ds->capacity; i < 2 * ds->capacity; ++i) {
            new_records[i] = malloc(sizeof(record_t));
            if (new_records[i] == NULL) goto cleanup;
        }

        ds->records = new_records;
        ds->capacity *= 2;
    }

    record_t* rec = ds->records[index];
    rec->key = key;
    rec->timestamp = time(NULL);
    rec->status = status;

unlock:
    pthread_mutex_unlock(&ds->lock);
    return;

cleanup:
    // clean up newly allocated records
    for (size_t i = 2 * ds->capacity - 1; i >= ds->capacity; --i) free(new_records[i]);
    free(new_records);
    goto unlock;
}
```
This code uses a mutex to ensure thread safety. It also dynamically allocates memory for the records array, doubling its size whenever it runs out of space. This ensures that we don't waste memory on unused slots and can handle an arbitrarily large number of records. 

Please note that this is a basic implementation and may need to be adjusted based on your specific requirements and constraints. For example, you might want to use a more efficient data structure for the records array if performance is a concern. Similarly, you might want to replace the random number generator with a better one or a hardware-based source of entropy if security is a concern.
