["This task is quite complex and involves multiple aspects such as thread management, memory allocation, error handling, data integration, and monitoring. Here's a simplified version of how you might implement some of these features in C. Please note that this code does not cover all the points mentioned above due to its complexity and length.

```c
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int priority;
    void* payload;
    void (*callback)(void*);
} Task;

typedef struct {
    pthread_t thread;
    sem_t semaphore;
    Task** tasks;
    size_t taskCount;
    size_t maxTasks;
} WorkerThread;

typedef struct {
    int workerCount;
    int minPriority;
    int maxPriority;
    size_t payloadSize;
} Config;

WorkerThread* threads = NULL;
Config config;
pthread_mutex_t taskMutex = PTHREAD_MUTEX_INITIALIZER;
sem_t threadSemaphore;

void* workerFunc(void* arg) {
    WorkerThread* thread = (WorkerThread*)arg;
    while (1) {
        sem_wait(&thread->semaphore);
        pthread_mutex_lock(&taskMutex);
        Task* task = thread->tasks[--thread->taskCount];
        pthread_mutex_unlock(&taskMutex);

        // Process the task...
        task->callback(task->payload);
        free(task->payload);
        free(task);
    }
}

void submitTask(int priority, void* payload, void (*callback)(void*)) {
    Task* task = malloc(sizeof(Task));
    if (task == NULL) {
        // Handle allocation failure...
        return;
    }

    task->priority = priority;
    task->payload = payload;
    task->callback = callback;

    pthread_mutex_lock(&taskMutex);
    WorkerThread* thread = &threads[0]; // Choose a worker based on the task's priority...
    if (thread->taskCount == thread->maxTasks) {
        // Handle full queue...
        return;
    }

    thread->tasks[thread->taskCount++] = task;
    pthread_mutex_unlock(&taskMutex);
    sem_post(&thread->semaphore);
}

void init(Config cfg) {
    config = cfg;

    threads = malloc(sizeof(WorkerThread) * cfg.workerCount);
    if (threads == NULL) {
        // Handle allocation failure...
        return;
    }

    for (int i = 0; i < cfg.workerCount; ++i) {
        threads[i].taskCount = 0;
        threads[i].maxTasks = cfg.payloadSize / sizeof(Task); // Assuming each task is the size of a Task struct...
        threads[i].tasks = malloc(sizeof(Task*) * threads[i].maxTasks);
        if (threads[i].tasks == NULL) {
            // Handle allocation failure...
            return;
        }

        sem_init(&threads[i].semaphore, 0, 0);
        pthread_create(&threads[i].thread, NULL, workerFunc, &threads[i]);
    }

    sem_init(&threadSemaphore, 0, 1); // Start with one available thread...
}
```
This code provides a basic framework for managing dynamic lists of worker threads and tasks. It does not include all the features mentioned in your task description such as system metrics monitoring, error handling, data integration, logging and monitoring, etc. You would need to expand this code according to your specific requirements.
