['Here is a basic implementation of your requirements in C using pthreads for thread safety and mutexes for synchronization. This code does not include the functionality for exporting data to persistent storage, merging incoming records with existing ones, or handling external data sources that stream records in real-time from multiple independent sources.

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    record* records;
} RecordCollection;

RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection* collection = malloc(sizeof(RecordCollection));
    if (collection == NULL) return NULL;

    pthread_mutex_init(&collection->lock, NULL);
    collection->records = calloc(initial_capacity, sizeof(record));
    if (collection->records == NULL) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;

    return collection;
}

void destroy_collection(RecordCollection* collection) {
    pthread_mutex_destroy(&collection->lock);
    free(collection->records);
    free(collection);
}

int add_record(RecordCollection* collection, record rec) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        record* new_records = realloc(collection->records, new_capacity * sizeof(record));
        if (new_records == NULL) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Failed to resize array
        }

        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->count++] = rec;

    pthread_mutex_unlock(&collection->lock);

    return 0; // Success
}

int delete_record(RecordCollection* collection, size_t index) {
    pthread_mutex_lock(&collection->lock);

    if (index >= collection->count) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Index out of bounds
    }

    for (size_t i = index; i < collection->count - 1; ++i) {
        collection->records[i] = collection->records[i + 1];
    }

    --collection->count;

    pthread_mutex_unlock(&collection->lock);

    return 0; // Success
}
```
This code provides a basic implementation of a thread-safe dynamic array for `record` structures. It uses a mutex to ensure that only one thread can modify the collection at a time, preventing race conditions and ensuring thread safety. The capacity of the array is doubled each time it needs to be resized, which ensures amortized O(1) complexity for add operations while minimizing memory usage and avoiding frequent reallocations.
']

