#include <time.h>

typedef struct {
    time_t timestamp;
    int statusFlag;
    char* stringData;
    float randomFloatValue;
} Event;

Event** allocateAndInitializeEvents(size_t numOfEvents, float minRandomVal, float maxRandomVal) {
    if (numOfEvents == 0) return NULL;

    srand((unsigned int)time(NULL)); // seed the random number generator

    Event** events = malloc(numOfEvents * sizeof(Event*));
    if (!events) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (size_t i = 0; i < numOfEvents; ++i) {
        events[i] = malloc(sizeof(Event));
        if (!events[i]) {
            fprintf(stderr, "Memory allocation failed.\n");
            // Free previously allocated memory and return NULL on failure
            for (--i; i >= 0; --i) free(events[i]);
            free(events);
            return NULL;
        }

        events[i]->timestamp = time(NULL);
        events[i]->statusFlag = 0; // Initialize status flag to 0
        events[i]->stringData = malloc(256 * sizeof(char));
        if (!events[i]->stringData) {
            fprintf(stderr, "Memory allocation failed.\n");
            free(events[i]); // Free current event memory on failure
            for (--i; i >= 0; --i) free(events[i]); // Free previously allocated events
            free(events); // Free main array memory
            return NULL;
        }

        float randomFloat = minRandomVal + static_cast <float> (rand()) / (static_cast <float> (RAND_MAX/(maxRandomVal-minRandomVal)));
        events[i]->randomFloatValue = randomFloat;
    }

    return events;
}
```
