['Here is an example of how you might implement this in C. This code does not include all the features mentioned as it would be quite complex to fully implement. However, it provides a basic structure for managing dynamic collections and includes some error handling, thread safety, and memory management. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    pthread_mutex_t lock;
    Record* records;
    size_t capacity;
    size_t count;
} Collection;

Collection* create_collection(size_t initial_capacity) {
    Collection* collection = malloc(sizeof(Collection));
    if (collection == NULL) return NULL;

    pthread_mutex_init(&collection->lock, NULL);
    collection->records = malloc(initial_capacity * sizeof(Record));
    if (collection->records == NULL) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;

    return collection;
}

void destroy_collection(Collection* collection) {
    pthread_mutex_destroy(&collection->lock);
    free(collection->records);
    free(collection);
}

int add_record(Collection* collection, Record record) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record* new_records = realloc(collection->records, new_capacity * sizeof(Record));
        if (new_records == NULL) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Failed to resize collection
        }

        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->count++] = record;

    pthread_mutex_unlock(&collection->lock);

    return 0; // Success
}

// Similar functions for delete and update records can be implemented.
```
This code creates a `Collection` struct that holds an array of `Record`s, along with a mutex to ensure thread safety when adding or removing records. The `create_collection` function initializes the collection with a given capacity, while the `destroy_collection` function frees all allocated memory. 

The `add_record` function adds a record to the collection and resizes the array if necessary. It uses a mutex to ensure that only one thread can add or remove records at a time, preventing race conditions. If the allocation of new memory fails when resizing the array, it returns -1 indicating failure; otherwise, it returns 0.
