```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    long offset;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int generateRandom(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void insertRecord(int value) {
    pthread_mutex_lock(&lock);

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        // Handle memory allocation failure gracefully.
        pthread_mutex_unlock(&lock);
        return;
    }

    newNode->record.value = value;
    newNode->record.offset = generateRandom(0, LONG_MAX);
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void deleteRecord(int value) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    Node* prev = NULL;

    while (current != NULL && current->record.value != value) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&lock);
        return; // Record not found
    }

    if (prev == NULL) {
        head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_mutex_unlock(&lock);
}

Record* getRecord(int value) {
    pthread_mutex_lock(&lock);

    Node* current = head;

    while (current != NULL && current->record.value != value) {
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&lock);
        return NULL; // Record not found
    }

    Record* recordCopy = malloc(sizeof(Record));
    *recordCopy = current->record;

    pthread_mutex_unlock(&lock);

    return recordCopy;
}
```
