['Here is a basic implementation in C using pthreads for thread safety and pool allocator for efficient memory management. This example does not include the actual data source reading or validation function as they are complex and depend on specific requirements. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <assert.h>

typedef struct {
    int value;
} Record;

typedef struct {
    size_t capacity;
    size_t count;
    Record* records;
    pthread_mutex_t lock;
} PoolAllocator;

PoolAllocator* create_pool(size_t initialCapacity) {
    PoolAllocator* pool = malloc(sizeof(PoolAllocator));
    if (pool == NULL) return NULL;

    pool->records = malloc(initialCapacity * sizeof(Record));
    if (pool->records == NULL) {
        free(pool);
        return NULL;
    }

    pool->capacity = initialCapacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_pool(PoolAllocator* pool) {
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

Record* allocate_record(PoolAllocator* pool) {
    Record* record;

    pthread_mutex_lock(&pool->lock);

    if (pool->count == pool->capacity) {
        size_t newCapacity = pool->capacity * 2;
        Record* newRecords = realloc(pool->records, newCapacity * sizeof(Record));

        if (newRecords == NULL) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }

        pool->capacity = newCapacity;
        pool->records = newRecords;
    }

    record = &pool->records[pool->count++];

    pthread_mutex_unlock(&pool->lock);

    return record;
}

bool validate(int value) {
    // Implement your validation logic here.
    return true;
}

bool init_and_process_records() {
    PoolAllocator* pool = create_pool(1024);
    if (pool == NULL) return false;

    int value;
    while ((value = read_next()) != EOF) { // Assuming read_next is a function that reads the next integer from your data source.
        if (!validate(value)) {
            fprintf(stderr, "Validation failed for value: %d\n", value);
            continue;
        }

        Record* record = allocate_record(pool);
        if (record == NULL) {
            fprintf(stderr, "Failed to allocate memory for record.\n");
            destroy_pool(pool);
            return false;
        }

        record->value = value;
    }

    // Process records...

    destroy_pool(pool);
    return true;
}
```
This code uses a pool allocator to manage memory efficiently. It also uses a mutex for thread safety when allocating new records, ensuring that only one thread can modify the record count at a time. The validation function is implemented as `validate` and should be replaced with your own logic. 

