        metadata->buffer = record;
        metadata->modified = key % 7 == 0 && key % 5 != 0 ? 1 : 0;

        manager->records[i] = record;
        manager->metadata[i] = metadata;
    }

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void freeRecords(RecordsManager* manager) {
    if (manager == NULL) return;

    for (int i = 0; i < numRecords; ++i) {
        free(manager->records[i]->buffer);
        free(manager->records[i]);
        free(manager->metadata[i]);
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager->metadata);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
