void initArray(ArrayManager *manager) {
    manager->size = 0;
    manager->capacity = 10;
    manager->array = malloc(manager->capacity * sizeof(LTE_ENB_RRC_MESSAGE_T));
    pthread_mutex_init(&manager->mutex, NULL);
}

void addElement(ArrayManager *manager, LTE_ENB_RRC_MESSAGE_T element) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size == manager->capacity) {
        manager->capacity *= 2;
        manager->array = realloc(manager->array, manager->capacity * sizeof(LTE_ENB_RRC_MESSAGE_T));
    }

    manager->array[manager->size++] = element;

    pthread_mutex_unlock(&manager->mutex);
}

void removeElement(ArrayManager *manager, int cellId) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < manager->size; ++i) {
        if (manager->array[i].cellId == cellId) {
            memmove(manager->array + i, manager->array + i + 1, (manager->size - i - 1) * sizeof(LTE_ENB_RRC_MESSAGE_T));
            --manager->size;
            break;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

void iterateOverArray(ArrayManager *manager, void (*func)(LTE_ENB_RRC_MESSAGE_T*)) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < manager->size; ++i) {
