#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    int value;
} Record;

typedef struct node {
    long offset;
    int key;
    Record *record;
    struct node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert(long offset, int key, Record *record) {
    pthread_mutex_lock(&lock);

    Node *newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        // Log error and return
        pthread_mutex_unlock(&lock);
        return;
    }

    newNode->offset = offset;
    newNode->key = key;
    newNode->record = record;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void delete(int key) {
    pthread_mutex_lock(&lock);

    Node *prev = NULL;
    for (Node *curr = head; curr != NULL; prev = curr, curr = curr->next) {
        if (curr->key == key) {
            if (prev == NULL) {
                head = curr->next;
            } else {
                prev->next = curr->next;
            }

            free(curr);
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

Record *get(int key) {
    pthread_mutex_lock(&lock);

    for (Node *curr = head; curr != NULL; curr = curr->next) {
        if (curr->key == key) {
            Record *record = curr->record;

            pthread_mutex_unlock(&lock);
            return record;
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}
```
