using System;
using System.Threading;

public class DynamicValueGenerator
{
    private float minFloat;
    private float maxFloat;
    private int minInt;
    private int maxInt;

    public DynamicValueGenerator(float min, float max)
    {
        this.minFloat = min;
        this.maxFloat = max;

        // Convert the range to integer values
        this.minInt = (int)Math.Ceiling(min);
        this.maxInt = (int)Math.Floor(max);
    }

    public float GenerateRandomFloat()
    {
        Random rand = new Random();
        double val = minFloat + (rand.NextDouble() * (maxFloat - minFloat));

        return (float)val;
    }

    public int GenerateRandomInt()
    {
        Random rand = new Random();
        return rand.Next(minInt, maxInt + 1);
    }

    public override string ToString()
    {
        return $"Range: [{this.minFloat}, {this.maxFloat}]";
    }
}
