void* initializeRecord(void* arg) {
    long offset = (long)arg;
    Record* record = malloc(sizeof(Record));
    if (!record) {
        // Handle error here.
        return NULL;
    }

    // Generate a random value within the specified range.
    int min = 0, max = 100;
    record->value = rand() % (max - min + 1) + min;

    return record;
}

void processData(long* offsets, size_t numOffsets, GHashTable* hashTable) {
    pthread_t threads[numOffsets];
    void* results[numOffsets];

    // Start a thread for each offset.
    for (size_t i = 0; i < numOffsets; ++i) {
        int ret = pthread_create(&threads[i], NULL, initializeRecord, (void*)offsets[i]);
        if (ret != 0) {
            // Handle error here.
            return;
        }
    }

    // Wait for all threads to complete and store the results in the hash table.
    for (size_t i = 0; i < numOffsets; ++i) {
        pthread_join(threads[i], &results[i]);

        if (!results[i]) {
            // Handle error here.
            continue;
        }

        Record* record = (Record*)results[i];
        g_hash_table_insert(hashTable, GINT_TO_POINTER(record->value), record);
    }
}

int main() {
    // Allocate memory for the offsets and keys arrays.
    long* offsets = malloc(sizeof(long) * 1000000);
    int* keys = malloc(sizeof(int) * 1000000);

    // Initialize the offsets array with some values.
