```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
    char **identifiers;
    size_t capacity;
    size_t count;
} record;

record *create_record(size_t initial_capacity) {
    record *r = malloc(sizeof(record));
    r->value = 0;
    r->identifiers = calloc(initial_capacity, sizeof(char*));
    r->capacity = initial_capacity;
    r->count = 0;
    return r;
}

void add_identifier(record *r, const char *id) {
    if (r->count == r->capacity) {
        r->identifiers = realloc(r->identifiers, 2 * r->capacity * sizeof(char*));
        r->capacity *= 2;
    }
    r->identifiers[r->count] = strdup(id);
    r->count++;
}

void destroy_record(record *r) {
    for (size_t i = 0; i < r->count; ++i) {
        free(r->identifiers[i]);
    }
    free(r->identifiers);
    free(r);
}

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t count;
    pthread_mutex_t lock;
} data_structures;

data_structures *create_data_structures(size_t initial_capacity) {
    data_structures *ds = malloc(sizeof(data_structures));
    ds->offsets = calloc(initial_capacity, sizeof(long));
    ds->keys = calloc(initial_capacity, sizeof(int));
    ds->records = calloc(initial_capacity, sizeof(record*));
    ds->count = 0;
    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

void add_data(data_structures *ds, long offset, int key, record *r) {
    pthread_mutex_lock(&ds->lock);
    ds->offsets[ds->count] = offset;
    ds->keys[ds->count] = key;
    ds->records[ds->count] = r;
    ds->count++;
    pthread_mutex_unlock(&ds->lock);
}

void destroy_data_structures(data_structures *ds) {
    for (size_t i = 0; i < ds->count; ++i) {
        destroy_record(ds->records[i]);
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}
```
This code provides a basic structure for managing multiple data structures in a thread-safe manner. It uses mutexes to ensure that only one thread can modify the data at any given time, which helps prevent race conditions and other concurrency issues. The memory management is efficient, with minimal fragmentation and proper deallocation of resources upon function exit.
