["Here is an example of how you might implement such a function using C with pthreads for thread safety and a simple hash table structure for efficient storage and retrieval operations. This code does not include all the features mentioned in your request, but it provides a starting point for further development. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

typedef struct HashTable {
    pthread_mutex_t lock;
    Node **buckets;
    size_t bucketCount;
    size_t (*hashFunction)(int);
} HashTable;

HashTable* createHashTable(size_t bucketCount, size_t (*hashFunction)(int)) {
    HashTable *table = malloc(sizeof(HashTable));
    table->bucketCount = bucketCount;
    table->hashFunction = hashFunction;
    table->buckets = calloc(bucketCount, sizeof(Node*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void insertRecord(HashTable *table, Record *record) {
    size_t bucketIndex = table->hashFunction(record->key) % table->bucketCount;
    pthread_mutex_lock(&table->lock);
    Node *node = malloc(sizeof(Node));
    node->record = record;
    node->next = table->buckets[bucketIndex];
    table->buckets[bucketIndex] = node;
    pthread_mutex_unlock(&table->lock);
}

Record* getRecord(HashTable *table, int key) {
    size_t bucketIndex = table->hashFunction(key) % table->bucketCount;
    pthread_mutex_lock(&table->lock);
    Node *node = table->buckets[bucketIndex];
    while (node != NULL && node->record->key != key) {
        node = node->next;
    }
    pthread_mutex_unlock(&table->lock);
    return node ? node->record : NULL;
}

void deleteRecord(HashTable *table, int key) {
    size_t bucketIndex = table->hashFunction(key) % table->bucketCount;
    pthread_mutex_lock(&table->lock);
    Node **ppNode = &table->buckets[bucketIndex];
    while (*ppNode != NULL && (*ppNode)->record->key != key) {
        ppNode = &(*ppNode)->next;
    }
    if (*ppNode != NULL) {
        Node *nodeToDelete = *ppNode;
        *ppNode = nodeToDelete->next;
        free(nodeToDelete);
    }
    pthread_mutex_unlock(&table->lock);
}
```
This is a basic implementation and does not include many features mentioned in your request. For example, it doesn't handle memory leaks or logging system. Also, the hash function used here is very simple and may not provide good distribution for large data sets. You would need to implement more advanced techniques like dynamic resizing of the hash table when load factor exceeds a certain threshold, using a better hash function, etc.
