['Here is an example implementation in C using pthreads for thread safety and a simple timestamp mechanism. This code does not include network updates or error handling which would be necessary to fully implement this task. 

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct entry {
    double value;
    time_t timestamp;
    struct entry *prev, *next;
} Entry;

typedef struct list {
    pthread_mutex_t lock;
    Entry *head, *tail;
    int maxSize;
    int size;
} List;

List* createList(int maxSize) {
    List* list = malloc(sizeof(List));
    list->maxSize = maxSize;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

Entry* createEntry(double value) {
    Entry* entry = malloc(sizeof(Entry));
    entry->value = value;
    entry->timestamp = time(NULL);
    entry->prev = entry->next = NULL;
    return entry;
}

void addHead(List* list, Entry* entry) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->maxSize) {
        removeTail(list);
    }
    entry->next = list->head;
    if (list->head != NULL) {
        list->head->prev = entry;
    } else {
        list->tail = entry;
    }
    list->head = entry;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void addTail(List* list, Entry* entry) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->maxSize) {
        removeHead(list);
    }
    entry->prev = list->tail;
    if (list->tail != NULL) {
        list->tail->next = entry;
    } else {
        list->head = entry;
    }
    list->tail = entry;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void removeEntry(List* list, Entry* entry) {
    pthread_mutex_lock(&list->lock);
    if (entry->prev != NULL) {
        entry->prev->next = entry->next;
    } else {
        list->head = entry->next;
    }
    if (entry->next != NULL) {
        entry->next->prev = entry->prev;
    } else {
        list->tail = entry->prev;
    }
    free(entry);
    list->size--;
    pthread_mutex_unlock(&list->lock);
}

void removeHead(List* list) {
    if (list->head != NULL) {
        removeEntry(list, list->head);
    }
}

void removeTail(List* list) {
    if (list->tail != NULL) {
        removeEntry(list, list->tail);
    }
}

void clearList(List* list) {
    while (list->head != NULL) {
        removeHead(list);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
```
This code provides a basic implementation of the requirements. It uses a doubly linked list with a maximum size limit, and each entry contains a timestamp for ordering. The list is thread safe using mutex locks to prevent race conditions. Memory leaks are handled by always freeing memory when an entry is removed from the list.
