['Here is a basic implementation of a binary search tree in C with some of the functionalities you requested. This is a simplified version and does not include all the features you mentioned due to space constraints. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct node {
    char* key;
    struct node *left, *right;
} Node;

Node* newNode(char* item) {
    Node* temp = (Node*)malloc(sizeof(Node));
    temp->key = malloc(strlen(item) + 1);
    strcpy(temp->key, item);
    temp->left = temp->right = NULL;
    return temp;
}

Node* insert(Node* node, char* key) {
    if (node == NULL) 
        return newNode(key);

    if (strcmp(key, node->key) < 0)
        node->left  = insert(node->left, key);
    else if (strcmp(key, node->key) > 0)
        node->right = insert(node->right, key);

    return node;
}

Node* minValueNode(Node* node) {
    Node* current = node;
    while (current && current->left != NULL)
        current = current->left;

    return current;
}

Node* deleteNode(Node* root, char* key) {
    if (root == NULL) 
        return root;

    if (strcmp(key, root->key) < 0)
        root->left = deleteNode(root->left, key);
    else if(strcmp(key, root->key) > 0)
        root->right = deleteNode(root->right, key);

    else {
        if (root->left == NULL) {
            Node* temp = root->right;
            free(root->key);
            free(root);
            return temp;
        } 
        else if (root->right == NULL) {
            Node* temp = root->left;
            free(root->key);
            free(root);
            return temp;
        }

        Node* temp = minValueNode(root->right);
        root->key = realloc(root->key, strlen(temp->key) + 1);
        strcpy(root->key, temp->key);
        root->right = deleteNode(root->right, temp->key);
    }

    return root;
}

void inorder(Node* root) {
    if (root != NULL) {
        inorder(root->left);
        printf("%s \n", root->key);
        inorder(root->right);
    }
}

int main() {
    Node* root = NULL;
    root = insert(root, "test1");
    insert(root, "test2");
    insert(root, "test3");

    printf("Inorder traversal of the given tree \n");
