void insert_end(Node** head, int val) {
    Node* new_node = create_node(val);
    if (*head == NULL) {
        *head = new_node;
        return;
    }
    Node* last = *head;
    while (last->next != NULL)
        last = last->next;
    last->next = new_node;
    new_node->prev = last;
}

void insert_beginning(Node** head, int val) {
    Node* new_node = create_node(val);
    if (*head != NULL)
        (*head)->prev = new_node;
    new_node->next = *head;
    *head = new_node;
}

void delete_end(Node** head) {
    if (*head == NULL) return;
    Node* last = *head;
    while (last->next != NULL)
        last = last->next;
    if (last->prev != NULL)
        last->prev->next = NULL;
    else
        *head = NULL;
    free(last);
}

void delete_beginning(Node** head) {
    if (*head == NULL) return;
    Node* temp = *head;
    *head = (*head)->next;
    if (*head != NULL)
