        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < initialCapacity; ++i) {
        list->nodes[i] = NULL;
    }

    return list;
}

void addNode(List* list, int key, const char* value) {
    if (list->size == list->capacity) {
        size_t newCapacity = 2 * list->capacity;
        if (newCapacity < list->capacity) {  // handle overflow
            fprintf(stderr, "Integer overflow during capacity calculations.\n");
            exit(EXIT_FAILURE);
        }

        Node** newNodes = realloc(list->nodes, newCapacity * sizeof(Node*));
        if (newNodes == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }

        list->capacity = newCapacity;
        list->nodes = newNodes;
    }

    Node* node = malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    node->key = key;
    node->value = strdup(value);  // deep copy to avoid memory leaks
