typedef struct Item {
    int id;
    char* description;
} Item;

GHashTable *item_table = NULL;
pthread_mutex_t lock;
char* descriptions[] = {"desc1", "desc2", "desc3"}; // replace with your actual descriptions
int num_items = 0;

void* allocate_memory(void* arg) {
    pthread_mutex_lock(&lock);

    if (num_items >= 10000) {
        printf("Maximum number of items reached.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    Item* item = malloc(sizeof(Item));
    if (!item) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    item->id = num_items + 1;
    item->description = strdup(descriptions[num_items % 3]); // replace with your actual logic for description assignment

    g_hash_table_insert(item_table, GINT_TO_POINTER(item->id), item);
    num_items++;

    pthread_mutex_unlock(&lock);

    return item;
}

void verify_memory() {
    gpointer key, value;
    GHashTableIter iter;
    g_hash_table_iter_init (&iter, item_table); 

    while (g_hash_table_iter_next (&iter, &key, &value)) {
        Item* item = (Item*) value;

        if (!item || !item->description) {
            printf("Memory verification failed: invalid item or description.\n");
            return;
        }
    }

    printf("Memory verified successfully.\n");
}
