#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct node_t {
    int key;
    char* value;
    record rec;
    struct node_t *next;
} node;

typedef struct list_t {
    node *head;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} list;

list* createList(size_t initialCapacity) {
    list *l = malloc(sizeof(list));
    if (l == NULL) return NULL; // handle allocation failure

    l->head = NULL;
    l->capacity = 0;
    l->size = 0;
    pthread_mutex_init(&l->lock, NULL);

    for(int i=0; i<initialCapacity; ++i) {
        node *n = malloc(sizeof(node));
        if (n == NULL) return NULL; // handle allocation failure

        n->key = 0;
        n->value = strdup("default");
        n->rec.value = 0;
        n->next = l->head;
        l->head = n;
    }

    l->capacity += initialCapacity;
    return l;
}

void addNode(list *l, int key, char* value, record rec) {
    pthread_mutex_lock(&l->lock);

    if (l->size == l->capacity) {
        node *n = malloc(sizeof(node));
        if (n == NULL) return; // handle allocation failure

        n->key = 0;
        n->value = strdup("default");
        n->rec.value = 0;
        n->next = l->head;
        l->head = n;
        l->capacity++;
    } else {
        node *n = l->head;
        for(int i=0; i<l->size; ++i) n = n->next;

        n->key = key;
        free(n->value);
        n->value = strdup(value);
        n->rec = rec;
    }

    l->size++;
    pthread_mutex_unlock(&l->lock);
}
```
