    size_t used;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray *a, size_t initialSize) {
    a->array = (LTE_ENB_RRC_MESSAGE_T*)malloc(initialSize * sizeof(LTE_ENB_RRC_MESSAGE_T));
    a->used = 0;
    a->size = initialSize;
