#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>

typedef struct point {
    double x;
    double y;
} Point;

double rand_range(double min, double max) {
    return min + ((double)rand() / RAND_MAX) * (max - min);
}

void seed_random(int seed) {
    srand(seed);
}

char** generate_strings(int count) {
    char **strings = malloc(count * sizeof(char*));
    for (int i = 0; i < count; ++i) {
        strings[i] = malloc(21); // 20 characters + null terminator
        scanf("%s", strings[i]);
    }
    return strings;
}

double* generate_doubles(int count, double min, double max) {
    double *numbers = malloc(count * sizeof(double));
    for (int i = 0; i < count; ++i) {
        numbers[i] = rand_range(min, max);
    }
    return numbers;
}

Point* generate_points(int count, double min, double max) {
    Point *points = malloc(count * sizeof(Point));
    for (int i = 0; i < count; ++i) {
        points[i].x = rand_range(min, max);
        points[i].y = rand_range(min, max);
    }
    return points;
}

double euclidean_distance(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return sqrt(dx*dx + dy*dy);
}

void find_max_distance(int count, Point *points, char **strings) {
    double max_dist = 0;
    int i1, i2;
    for (int i = 0; i < count; ++i) {
        for (int j = i + 1; j < count; ++j) {
            double dist = euclidean_distance(points[i], points[j]);
            if (dist > max_dist) {
                max_dist = dist;
                i1 = i;
                i2 = j;
            }
        }
    }
    printf("Max distance is between %s and %s\n", strings[i1], strings[i2]);
}

int main() {
    seed_random(time(NULL)); // Seed the random number generator with current time

    int count = 5; // Number of points to generate
    double min = -10.0, max = 10.0; // Range for coordinates

    char **strings = generate_strings(count);
    Point *points = generate_points(count, min, max);

    find_max_distance(count, points, strings);

    free(strings);
    free(points);

    return 0;
}
```
This code generates a specified number of random points and identifiers. It then calculates the Euclidean distance between each pair of points and prints the pair with the maximum distance. The memory for the strings and points is freed at the end to prevent leaks. Note that this code does not include error handling or logging, which would be necessary in a real-world application.
