#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NICB {
    int id;
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
    enum status {UP, DOWN} state;
} NICB;

NICB *nicb_pool = NULL;
pthread_mutex_t lock;
int nicb_count = 0;

void init_nicb_pool() {
    pthread_mutex_init(&lock, NULL);
    nicb_pool = (NICB*) malloc(10000 * sizeof(NICB));
}

void add_nicb(char* ip, char* mask, char* gateway) {
    if (nicb_count >= 10000) {
        printf("Pool is full\n");
        return;
    }

    pthread_mutex_lock(&lock);
    NICB *new_nicb = &nicb_pool[nicb_count++];
    new_nicb->id = nicb_count - 1;
    strncpy(new_nicb->ip_address, ip, sizeof(new_nicb->ip_address) - 1);
    strncpy(new_nicb->subnet_mask, mask, sizeof(new_nicb->subnet_mask) - 1);
    strncpy(new_nicb->gateway, gateway, sizeof(new_nicb->gateway) - 1);
    new_nicb->state = UP;
    pthread_mutex_unlock(&lock);
}

void update_status(int id, enum status state) {
    if (id < 0 || id >= nicb_count) {
        printf("Invalid NICB ID\n");
        return;
    }

    pthread_mutex_lock(&lock);
    NICB *nicb = &nicb_pool[id];
    if (nicb->state != state) {
        nicb->state = state;
        // Logging to external system goes here.
    }
    pthread_mutex_unlock(&lock);
}
```
