pthread_mutex_t mutexes[100];
int isRunning[100];

void* manageDataStream(void* arg) {
    int streamId = (int)arg;

    while (isRunning[streamId]) {
        pthread_mutex_lock(&mutexes[streamId]);

        // Simulate network latency and packet loss
        usleep((rand() % 1000) * 1000);

        if ((rand() % 100) < 5) { // 5% chance of packet loss
            continue;
        }

        // Your data processing logic here

        pthread_mutex_unlock(&mutexes[streamId]);
    }

    return NULL;
}

void startDataStream(int streamId) {
    if (!isRunning[streamId]) {
        isRunning[streamId] = 1;

        pthread_t thread;
        pthread_create(&thread, NULL, manageDataStream, (void*)streamId);
    }
}

void stopDataStream(int streamId) {
    if (isRunning[streamId]) {
        isRunning[streamId] = 0;

        // Wait for the thread to finish
        pthread_join((pthread_t)dataStreams[streamId], NULL);
    }
}

void pauseDataStream(int streamId) {
    if (isRunning[streamId]) {
        isRunning[streamId] = 0;

        // Wait for the thread to finish
        pthread_join((pthread_t)dataStreams[streamId], NULL);
    }
}

void resumeDataStream(int streamId) {
    if (!isRunning[streamId]) {
        isRunning[streamId] = 1;

        pthread_create(&dataStreams[streamId], NULL, manageDataStream, (void*)streamId);
    }
}

int main() {
    srand(time(NULL));

    // Initialize mutexes and data streams
    for (int i = 0; i < 100; ++i) {
        pthread_mutex_init(&mutexes[i], NULL);

        NFAPI_CRC_INDICATION_PDU_T *dataStream = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        // Initialize data stream here

        dataStreams[i] = dataStream;
    }

    // Start, pause, resume, and stop data streams randomly
    while (1) {
        int streamId = rand() % 100;

        switch (rand() % 4) {
            case 0: startDataStream(streamId); break;
            case 1: pauseDataStream(streamId); break;
            case 2: resumeDataStream(streamId); break;
            case 3: stopDataStream(streamId); break;
        }

        usleep((rand() % 500) * 1000); // Sleep for a random interval between actions
    }

    return 0;
}
```
