    handle->records = calloc(num_records, sizeof(Record*));
    handle->offsets = malloc(num_records * sizeof(long));
    handle->keys = malloc(num_records * sizeof(int));

    if (handle->records == NULL || handle->offsets == NULL || handle->keys == NULL) {
        free(handle->records);
        free(handle->offsets);
        free(handle->keys);
        free(handle);
        pthread_mutex_unlock(&lock);
        return NULL;
