    handle->num_records = num_records;

    for (size_t i = 0; i < num_records; ++i) {
        Record* record = malloc(sizeof(Record));

        if (record == NULL || (data_source != NULL && data_source() == NULL)) {
            free(handle->records);
            free(handle->offsets);
            free(handle->keys);
            free(handle);
            pthread_mutex_unlock(&lock);
            return NULL;
