["Here's a basic outline of how you might implement this in C. This is a complex task that requires careful consideration of many factors including thread safety, memory management, logging, error handling, and performance optimization. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <assert.h>

typedef struct {
    int value;
    size_t keyIndex;
} Record;

typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t count;
    long* offsets;
    int* keys;
    Record** records;
} Pool;

Pool* createPool(size_t initialOffsetCapacity, size_t initialKeyCapacity) {
    assert(initialOffsetCapacity > 0 && initialKeyCapacity > 0);

    Pool* pool = malloc(sizeof(Pool));
    if (pool == NULL) return NULL;

    pthread_mutex_init(&pool->mutex, NULL);
    pool->capacity = 1;
    pool->count = 0;

    pool->offsets = malloc(sizeof(long) * initialOffsetCapacity);
    if (pool->offsets == NULL) {
        free(pool);
        return NULL;
    }

    pool->keys = malloc(sizeof(int) * initialKeyCapacity);
    if (pool->keys == NULL) {
        free(pool->offsets);
        free(pool);
        return NULL;
    }

    pool->records = malloc(sizeof(Record*) * initialOffsetCapacity);
    if (pool->records == NULL) {
        free(pool->keys);
        free(pool->offsets);
        free(pool);
        return NULL;
    }

    return pool;
}

void destroyPool(Pool* pool) {
    assert(pool != NULL);

    pthread_mutex_destroy(&pool->mutex);
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->records[i]);
    }
    free(pool->records);
    free(pool->keys);
    free(pool->offsets);
    free(pool);
}
```
