#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct node {
    long offset;
    int key;
    struct node* next;
} Node;

Node** hash_table;
int table_size = 10000; // You can adjust this based on your needs.
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

long custom_seed() {
    return time(NULL);
}

void init_hash_table() {
    hash_table = malloc(sizeof(Node*) * table_size);
    for (int i = 0; i < table_size; i++) {
        hash_table[i] = NULL;
    }
}

long insert(int key, long offset) {
    pthread_mutex_lock(&lock);

    int index = abs(key % table_size);
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle memory allocation failure.
        return -1;
    }
    newNode->key = key;
    newNode->offset = offset;
    newNode->next = hash_table[index];
    hash_table[index] = newNode;

    pthread_mutex_unlock(&lock);
    return 0; // Success.
}

long lookup(int key) {
    int index = abs(key % table_size);
    Node* temp = hash_table[index];
    while (temp != NULL && temp->key != key) {
        temp = temp->next;
    }

    if (temp == NULL || temp->key != key) {
        // Key not found.
        return -1;
    } else {
        return temp->offset;
    }
}

void free_hash_table() {
    for (int i = 0; i < table_size; i++) {
        Node* node = hash_table[i];
        while (node != NULL) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(hash_table);
}

int main() {
    srand(custom_seed());

    init_hash_table();

    long* offsets = malloc(sizeof(long) * 100); // Allocate memory for offsets.
    if (offsets == NULL) {
        return -1; // Handle memory allocation failure.
    }

    int* keys = malloc(sizeof(int) * 100); // Allocate memory for keys.
    if (keys == NULL) {
        free(offsets);
        return -1; // Handle memory allocation failure.
    }

    record* records = malloc(sizeof(record) * 100); // Allocate memory for records.
    if (records == NULL) {
        free(offsets);
        free(keys);
        return -1; // Handle memory allocation failure.
    }

    // Initialize offsets, keys and records.
    for (int i = 0; i < 100; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 10000;
        records[i].value = rand();

        if (insert(keys[i], offsets[i]) != 0) {
            // Handle insertion failure.
            free_hash_table();
            free(offsets);
            free(keys);
            free(records);
            return -1;
        }
    }

    // Verify data integrity.
    for (int i = 0; i < 100; i++) {
        long offset = lookup(keys[i]);
        if (offset != offsets[i]) {
            // Handle discrepancy.
            free_hash_table();
            free(offsets);
            free(keys);
            free(records);
            return -1;
        }
    }

    free_hash_table();
    free(offsets);
    free(keys);
    free(records);

    return 0; // Success.
}
