```c
#include <stdio.h>
#include <time.h>
#include <pthread.h>
#include <glib.h>

typedef struct {
    char* description;
    int priority;
    time_t deadline;
} Task;

GHashTable *task_table = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void createTask(char* id, char* description, int priority, time_t deadline) {
    pthread_mutex_lock(&lock);

    Task *task = malloc(sizeof(Task));
    task->description = strdup(description);
    task->priority = priority;
    task->deadline = deadline;

    g_hash_table_insert(task_table, id, task);

    pthread_mutex_unlock(&lock);
}

Task* getTask(char* id) {
    pthread_mutex_lock(&lock);

    Task *task = g_hash_table_lookup(task_table, id);

    pthread_mutex_unlock(&lock);

    return task;
}

void updateTask(char* id, char* description, int priority, time_t deadline) {
    pthread_mutex_lock(&lock);

    Task *task = g_hash_table_lookup(task_table, id);
    if (task != NULL) {
        free(task->description);
        task->description = strdup(description);
        task->priority = priority;
        task->deadline = deadline;
    }

    pthread_mutex_unlock(&lock);
}

void deleteTask(char* id) {
    pthread_mutex_lock(&lock);

    Task *task = g_hash_table_lookup(task_table, id);
    if (task != NULL) {
        free(task->description);
        g_hash_table_remove(task_table, id);
        free(task);
    }

    pthread_mutex_unlock(&lock);
}
```
