MyStructure* allocateAndInitialize(int size, int min, int max) {
    srand(time(NULL)); // seed the random number generator

    MyStructure* structures = malloc(sizeof(MyStructure)*size);
    if (structures == NULL) return NULL; // handle memory allocation failure

    for (int i = 0; i < size; ++i) {
        structures[i].offsets = malloc(sizeof(long));
        structures[i].keys = malloc(sizeof(int));
        structures[i].records = malloc(sizeof(Record));
        structures[i].list = NULL; // initialize linked list pointer to NULL

        if (structures[i].offsets == NULL || structures[i].keys == NULL || structures[i].records == NULL) {
            // handle memory allocation failure
            for (int j = 0; j < i; ++j) {
                free(structures[j].offsets);
                free(structures[j].keys);
                free(structures[j].records);

                Node* current = structures[j].list;
                while (current != NULL) {
                    Node* temp = current;
                    current = current->next;
                    free(temp);
                }
            }

            free(structures); // free previously allocated memory
            return NULL;
        }

        structures[i].keys[0] = rand() % (max - min + 1) + min; // initialize with random integer within range
    }

    return structures;
}
