int num_records, min_value, max_value;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void seed() {
    srand(time(NULL));
}

int random_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

Record *initialize_record(int id, char *key) {
    Record *record = malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Failed to allocate memory for record %d\n", id);
        return NULL;
    }

    record->id = id;
    record->key = key;
    record->value = random_in_range(min_value, max_value);
    return record;
}

void *initialize_records(void *arg) {
    int thread_id = (int)(long long)arg;
    int start = num_records / omp_get_num_threads() * thread_id;
    int end = start + num_records / omp_get_num_threads();

    for (int i = start; i < end; ++i) {
        pthread_mutex_lock(&mutex);
        records[i] = initialize_record(i, keys[i]);
        pthread_mutex_unlock(&mutex);

        if (!records[i]) {
            return NULL; // Error occurred during initialization.
        }
    }

    return NULL;
}

int verify_data() {
    for (int i = 0; i < num_records; ++i) {
        if (records[i]->value < min_value || records[i]->value > max_value) {
            fprintf(stderr, "Record %d has an invalid value\n", i);
            return 0; // Data verification failed.
        }
    }

    return 1; // Data verified successfully.
}

int initialize() {
    seed();

    #pragma omp parallel num_threads(omp_get_num_procs())
    {
        int thread_id = omp_get_thread_num();
        initialize_records((void*)(long long)thread_id);
    }

    return verify_data(); // Return the result of data verification.
}
