Record* create_records(size_t array_size, size_t memory_budget, int min_value, int max_value) {
    assert(min_value <= max_value);
    assert(array_size * sizeof(long) + array_size * sizeof(int) + array_size * sizeof(Record) <= memory_budget);

    long* offsets = malloc(array_size * sizeof(long));
    int* keys = malloc(array_size * sizeof(int));
    Record* records = calloc(array_size, sizeof(Record));

    if (offsets == NULL || keys == NULL || records == NULL) {
        free(records);
        free(keys);
        free(offsets);
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < array_size; ++i) {
        generate_random(min_value, max_value, &keys[i]);

        records[i].offset = &offsets[i];
        records[i].key = &keys[i];
    }

    return records;
}

void serialize_records(Record* records, size_t array_size, char** buffer) {
    *buffer = malloc(array_size * sizeof(long) + array_size * sizeof(int));
    if (*buffer == NULL) {
