        exit(EXIT_FAILURE);
    }

    memcpy(*buffer, records[0].offset, array_size * sizeof(long));
    memcpy(*buffer + array_size * sizeof(long), records[0].key, array_size * sizeof(int));
}

void free_records(Record* records) {
    free(records);
}
