#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int32_t *amount;
    uint16_t status;
} TransactionDetails;

typedef struct {
    uint64_t timestamp;
    uint32_t transactionID;
    TransactionDetails details;
} TransactionLog;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
TransactionLog *logs = NULL;
int logCount = 0, maxLogs = 0;

void addLog(uint32_t transactionID, int32_t amount) {
    pthread_mutex_lock(&lock);

    if (logCount < maxLogs) {
        logs[logCount].timestamp = time(NULL);
        logs[logCount].transactionID = transactionID;
        logs[logCount].details.amount = malloc(sizeof(int32_t));
        *(logs[logCount].details.amount) = amount;
        logs[logCount].details.status = 0; // default status
        ++logCount;
    }

    pthread_mutex_unlock(&lock);
}

void removeLog(int index) {
    pthread_mutex_lock(&lock);

    if (index >= 0 && index < logCount) {
        free(logs[index].details.amount);

        for (int i = index; i < logCount - 1; ++i) {
            logs[i] = logs[i + 1];
        }

        --logCount;
    }

    pthread_mutex_unlock(&lock);
}

TransactionLog *initialize(int maxSize, int amountRange) {
    srand(time(NULL));
    maxLogs = maxSize;
    logs = malloc(maxLogs * sizeof(TransactionLog));

    for (uint32_t i = 0; i < maxLogs; ++i) {
        addLog(i, rand() % amountRange);
    }

    return logs;
}

void cleanup() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < logCount; ++i) {
        free(logs[i].details.amount);
    }

    free(logs);
    logs = NULL;
    logCount = maxLogs = 0;

    pthread_mutex_unlock(&lock);
}
