    free(rec);
}

int validate(const record* rec, int range_min, int range_max) {
    if (rec == NULL || rec->key < range_min || rec->key > range_max) return 0;

    for (size_t i = 0; i < rec->num_items; ++i) {
        const item* it = &rec->items[i];
        if (it->product_id <= 0 || it->quantity < 1 || it->price <= 0.0f) return 0;
    }

    return 1;
}

void* retry_with_backoff(void (*func)(void), int max_retries, double initial_delay) {
    for (int i = 0; i < max_retries; ++i) {
        pthread_mutex_lock(&lock);

        func();

        pthread_mutex_unlock(&lock);

        if (validate(rec, range_min, range_max)) return rec;

        sleep(initial_delay * pow(2.0, i)); // exponential backoff
    }

    return NULL;
}
