#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int* values;
} record;

void seed_rand(unsigned int seed) {
    srand(seed);
}

int initialize_records(record** records, size_t num_records, size_t max_values, unsigned int seed) {
    if (num_records == 0 || max_values == 0) {
        fprintf(stderr, "Error: Cannot initialize zero-sized arrays.\n");
        return 0;
    }

    *records = calloc(num_records, sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records array.\n");
        return 0;
    }

    seed_rand(seed);

    int* used_values = calloc(max_values * num_records, sizeof(int));
    if (used_values == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for used values array.\n");
        free(*records);
        return 0;
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].values = calloc(max_values, sizeof(int));
        if ((*records)[i].values == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for values array in record %zu.\n", i);
            free(*records);
            free(used_values);
            return 0;
        }

        (*records)[i].offset = rand();
        (*records)[i].key = rand();

        for (size_t j = 0; j < max_values; ++j) {
            int value;
            do {
                value = rand() % (max_values * num_records);
            } while (used_values[value]);

            used_values[value] = 1;
            (*records)[i].values[j] = value;
        }
    }

    free(used_values);
    return 1;
}
```
