        free(offsets);
        return;
    }

    record *records = malloc(num_records * sizeof(record));
    if (records == NULL) {
        printf("Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        return;
    }

    srand(time(NULL)); // seed the random number generator

    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand();

        keys[i] = rand() % 1000 + 1; // generate a random integer between 1 and 1000

        records[i].id = keys[i];
        records[i].value = (double)rand() / RAND_MAX; // generate a random double between 0 and 1

        records[i].str = malloc(max_str_len + 1);
        if (records[i].str == NULL) {
            printf("Memory allocation failed for string in record %d\n", i);
            // free all previously allocated memory before returning
            for (int j = 0; j < i; j++) {
                free(records[j].str);
            }
            free(offsets);
            free(keys);
            free(records);
            return;
        }

        // generate a random alphanumeric string of length max_str_len
        for (int j = 0; j < max_str_len; j++) {
            int char_type = rand() % 3;
            if (char_type == 0) {
                records[i].str[j] = 'A' + rand() % 26; // uppercase letter
            } else if (char_type == 1) {
                records[i].str[j] = 'a' + rand() % 26; // lowercase letter
            } else {
                records[i].str[j] = '0' + rand() % 10; // digit
            }
        }
        records[i].str[max_str_len] = '\0'; // null-terminate the string
    }

    // free all allocated memory when done
    for (int i = 0; i < num_records; i++) {
        free(records[i].str);
    }
    free(offsets);
    free(keys);
    free(records);
}
