#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    double value;
    int ref_count;
    time_t expiration_timestamp;
} record;

record* records = NULL;
int num_records = 0;
pthread_mutex_t lock;

void init_records(int size) {
    srand(time(NULL));
    records = malloc(sizeof(record) * size);
    for (int i = 0; i < size; i++) {
        records[i].offset = rand() % 1000 + 1; // Random offset between 1 and 1000
        records[i].key = rand() % 1000 + 1;    // Random key between 1 and 1000
        records[i].value = 0.0;
        records[i].ref_count = 0;
        records[i].expiration_timestamp = time(NULL) + rand() % 3600 + 1; // Random expiration within an hour
    }
    num_records = size;
}

void free_records() {
    if (records != NULL) {
        free(records);
        records = NULL;
    }
}

int find_largest() {
    int max = 0;
    for (int i = 0; i < num_records; i++) {
        if (records[i].key > max) {
            max = records[i].key;
        }
    }
    return max;
}

void* read_and_find(void* arg) {
    int size = *((int*)arg);
    init_records(size);

    pthread_mutex_lock(&lock);
    int largest = find_largest();
    printf("Largest key: %d\n", largest);
    free_records();
    pthread_mutex_unlock(&lock);

    return NULL;
}

int main() {
    srand(time(NULL));
    int size = 10; // Size of the record array
    pthread_t thread[size];
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < size; i++) {
        if (pthread_create(&thread[i], NULL, read_and_find, &size)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < size; i++) {
        if (pthread_join(thread[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            return 2;
        }
    }

    pthread_mutex_destroy(&lock);
    return 0;
}
```
This code creates a dynamic array of records and finds the largest key in it. It uses threads to simulate concurrent data processing requests, each thread initializing its own record array and finding the largest key. The mutex is used to ensure that only one thread can access the records at a time. 

