#include <string.h>

typedef struct {
    char ip[16];
    char subnet_mask[16];
    char gateway[16];
} NetworkConfig;

typedef struct Node {
    char* dnsServer;
    struct Node* next;
} DNSNode;

DNSNode* createDNSEntry(char* server) {
    DNSNode* newNode = (DNSNode*) malloc(sizeof(DNSNode));
    if(newNode == NULL) return NULL;

    newNode->dnsServer = strdup(server);
    newNode->next = NULL;
    return newNode;
}

void addDNSEntry(NetworkConfig* config, char* server) {
    DNSNode** current = &config->dnsServers;

    while(*current != NULL) {
        if(strcmp((*current)->dnsServer, server) == 0) return;
        current = &(*current)->next;
    }

    *current = createDNSEntry(server);
}

NetworkConfig* configure_network_settings(int size) {
    NetworkConfig* configs = (NetworkConfig*) malloc(sizeof(NetworkConfig) * size);
    if(configs == NULL) return NULL;

    for(int i = 0; i < size; ++i) {
        // Initialize each configuration with default values or user input
        strcpy(configs[i].ip, "192.168.0.1");
        strcpy(configs[i].subnet_mask, "255.255.255.0");
        strcpy(configs[i].gateway, "192.168.0.254");

        // Add DNS servers to each configuration
        addDNSEntry(&configs[i], "8.8.8.8");
        addDNSEntry(&configs[i], "8.8.4.4");
    }

    return configs;
}
```
