use std::thread;
use std::env;
use log::info;
use failure::Error;
use serde_json::Value as JsonValue;
use reqwest::Client;

#[derive(Debug)]
struct SensorEvent {
    timestamp: SystemTime,
    value: f64,
    identifier: String,
}

type EventMap = HashMap<String, Arc<Mutex<SensorEvent>>>;

pub struct DataPipeline {
    events: Mutex<EventMap>,
    client: Client,
    api_url: String,
}

impl DataPipeline {
    pub fn new() -> Self {
        let api_url = env::var("API_URL").unwrap_or_else(|_| "http://localhost:8080".to_string());
        info(&format![Connecting to API at {}", &api_url]);
        DataPipeline {
            events: Mutex::new(HashMap::new()),
            client: Client::new(),
            api_url,
        }
    }

    pub fn add_event(&self, event: SensorEvent) -> Result<(), Error> {
        let mut events = self.events.lock().unwrap();
        if !events.contains_key(&event.identifier) {
            info![Adding new event {}", &event.identifier);
            events.insert(event.identifier.clone(), Arc::new(Mutex::new(event)));
        } else {
            info![Updating existing event {}", &event.identifier];
            *events.get_mut(&event.identifier).unwrap() = Arc::new(Mutex::new(event));
        }
        Ok(())
    }

    pub fn process_data(&self) -> Result<(), Error> {
        let events = self.events.lock().unwrap();
        for (_, event) in &events {
            let event = event.lock().unwrap();
            // Process data here...
        }
        Ok(())
    }

    pub fn send_data(&self) -> Result<(), Error> {
        let events = self.events.lock().unwrap();
        let json: JsonValue = serde_json::to_value(events)?;
        self.client.post(&self.api_url).send_json(&json).map(|_| ()).map_err(failure::Error::from)
    }
}
```
