#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int *amount;
    short status_flags;
} TransactionDetails;

typedef struct transactionLogEntry {
    uint64_t timestamp;
    uint32_t transactionID;
    TransactionDetails details;
    struct transactionLogEntry *next;
} TransactionLogEntry;

TransactionLogEntry *first = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

uint32_t generateUniqueID() {
    static uint32_t id = 0;
    pthread_mutex_lock(&lock);
    uint32_t uniqueID = ++id;
    pthread_mutex_unlock(&lock);
    return uniqueID;
}

uint64_t getCurrentTime() {
    struct timespec ts;
    timespec_get(&ts, TIME_UTC);
    return (uint64_t)ts.tv_sec * 1000000000 + ts.tv_nsec;
}

int seedRand(int min, int max) {
    srand(time(NULL));
    return rand() % (max - min + 1) + min;
}

TransactionLogEntry* createNewLogEntry() {
    TransactionLogEntry *newEntry = malloc(sizeof(TransactionLogEntry));
    if (!newEntry) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    newEntry->timestamp = getCurrentTime();
    newEntry->transactionID = generateUniqueID();
    newEntry->details.amount = malloc(sizeof(int));
    if (!newEntry->details.amount) {
        fprintf(stderr, "Memory allocation failed\n");
        free(newEntry);
        return NULL;
    }

    *(newEntry->details.amount) = seedRand(100, 500);
    newEntry->next = first;
    first = newEntry;
    return newEntry;
}

void removeLogEntry(uint32_t transactionID) {
    pthread_mutex_lock(&lock);

    TransactionLogEntry **indirect = &first;
    while (*indirect) {
        if ((*indirect)->transactionID == transactionID) {
            TransactionLogEntry *toRemove = *indirect;
            *indirect = toRemove->next;

            free(toRemove->details.amount);
            free(toRemove);
            break;
        }

        indirect = &(*indirect)->next;
    }

    pthread_mutex_unlock(&lock);
}
```
This code creates a linked list of transaction log entries, each with a unique ID and timestamp. It also includes functions to generate a unique ID and set the current time. The `createNewLogEntry` function allocates memory for a new entry and sets its timestamp and ID. The `removeLogEntry` function removes an entry from the list based on its transaction ID.

Please note that this is a very basic implementation and does not include all the features you mentioned, such as logging system integration or configuration parameters for tuning memory allocation strategies and logging levels. Also, it doesn't handle fragmentation or optimize memory usage in any way. It also doesn't support frequent additions and deletions efficiently. You would need to implement these features yourself based on your specific requirements.
