['Here is an example of how you might implement this in C. This code does not include all the features you requested such as dynamic scaling based on system metrics or integration with third-party libraries. However, it provides a basic structure for managing worker threads and tasks. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int priority;
    void* payload;
    void (*callback)(void*);
} Task;

typedef struct {
    pthread_t thread;
    int id;
    Task** tasks;
    int taskCount;
} WorkerThread;

WorkerThread* threads = NULL;
int threadCount = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* worker(void* arg) {
    WorkerThread* thread = (WorkerThread*)arg;

    for (int i = 0; i < thread->taskCount; ++i) {
        Task* task = thread->tasks[i];

        // Process the task...
        if (task->callback != NULL) {
            task->callback(task->payload);
        }
    }

    return NULL;
}

int createWorkerThreads(int count, int defaultPayloadSize) {
    threads = malloc(count * sizeof(WorkerThread));
    if (threads == NULL) {
        return 0;
    }

    for (int i = 0; i < count; ++i) {
        WorkerThread* thread = &threads[i];

        // Initialize the worker thread...
        thread->id = i + 1;
        thread->taskCount = 0;
        thread->tasks = malloc(defaultPayloadSize * sizeof(Task*));
    }

    threadCount = count;
    return 1;
}

void submitTask(int priority, void* payload, void (*callback)(void*)) {
    pthread_mutex_lock(&lock);

    // Find the worker thread with the lowest task count...
    WorkerThread* thread = &threads[0];
    for (int i = 1; i < threadCount; ++i) {
        if (threads[i].taskCount < thread->taskCount) {
            thread = &threads[i];
        }
    }

    // Add the task to the worker thread...
    Task* task = malloc(sizeof(Task));
    task->priority = priority;
    task->payload = payload;
    task->callback = callback;

    thread->tasks[thread->taskCount++] = task;

    pthread_mutex_unlock(&lock);
}
```
This code creates a fixed number of worker threads and assigns tasks to them based on their priority. It uses a mutex for synchronization, which can lead to contention if there are many threads or high contention among the threads. You might want to consider using a lock-free data structure or other concurrency control mechanisms depending on your specific requirements.
']

