#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Task {
    char* command;
    int priority;
    float execution_time;
} Task;

typedef struct Node {
    Task task;
    struct Node *next;
} Node;

Node *head = NULL;

int addTask(char* command, int priority, float execution_time) {
    if (command == NULL || strlen(command) == 0) {
        printf("Error: Empty command\n");
        return -1;
    }

    Node *newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        return -2;
    }

    newNode->task.command = strdup(command);
    if (newNode->task.command == NULL) {
        free(newNode);
        printf("Memory allocation failed for command\n");
        return -3;
    }

    newNode->task.priority = priority;
    newNode->task.execution_time = execution_time;
    newNode->next = NULL;

    if (head == NULL || head->task.priority < priority) {
        newNode->next = head;
        head = newNode;
    } else {
        Node *current = head;
        while (current->next != NULL && current->next->task.priority >= priority) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }

    return 0;
}

void printTasks() {
    Node *current = head;
    while (current != NULL) {
        printf("Command: %s, Priority: %d, Execution Time: %.2f\n", current->task.command, current->task.priority, current->task.execution_time);
        current = current->next;
    }
}

void freeTasks() {
    Node *current = head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp->task.command);
        free(temp);
    }
    head = NULL;
}
```
This code creates a linked list of tasks sorted by priority in descending order. It also includes functions to print all the tasks and free all allocated memory when done. Note that this is a very basic implementation and does not include error handling for edge cases, logging, or exporting tasks to a string. You would need to add these features as needed based on your specific requirements.
