    char* command;
    int priority;
    float execution_time;
} Task;

// Comparator function for sorting tasks based on their priority
int compare(const void *a, const void *b) {
    return ((Task *)a)->priority - ((Task *)b)->priority;
}

void add_task(Task **tasks, int *size, char* command, int priority, float execution_time) {
    Task *new_task = malloc(sizeof(Task));
    if (new_task == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    new_task->command = strdup(command);
    if (new_task->command == NULL) {
        printf("Memory allocation failed for command.\n");
        free(new_task);
        return;
    }

    new_task->priority = priority;
    new_task->execution_time = execution_time;

    *tasks = realloc(*tasks, (*size + 1) * sizeof(Task));
    if (*tasks == NULL) {
        printf("Memory allocation failed for tasks.\n");
        free(new_task);
        return;
    }

    (*tasks)[*size] = *new_task;
    (*size)++;

    qsort(*tasks, *size, sizeof(Task), compare);
}
```
