    char* command;
    int priority;
    float execution_time;
} Task;

Task** tasks = NULL;
int taskCount = 0;
const int MAX_TASKS = 100000;

void addTask(char* command, int priority) {
    if (taskCount >= MAX_TASKS) {
        printf("Maximum number of tasks reached.\n");
        return;
    }

    Task* newTask = malloc(sizeof(Task));
    if (!newTask) {
        printf("Memory allocation failed.\n");
        return;
    }

    newTask->command = strdup(command);
    if (!newTask->command) {
        free(newTask);
        printf("Memory allocation failed.\n");
        return;
    }

    newTask->priority = priority;
    srand((unsigned int) time(NULL));
    newTask->execution_time = (float)(rand() % 1000 + 1); // Random execution time for demonstration purposes.

    tasks[taskCount++] = newTask;
}

int compareTasks(const void* a, const void* b) {
    Task** taskA = (Task**)a;
    Task** taskB = (Task**)b;
    return (*taskB)->priority - (*taskA)->priority; // Descending order for stable sort.
}

void sortTasks() {
    qsort(tasks, taskCount, sizeof(Task*), compareTasks);
}

int main() {
    tasks = malloc(MAX_TASKS * sizeof(Task*));
    if (!tasks) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    addTask("Command1", 5);
    addTask("Command2", 3);
    addTask("Command3", 7);

