#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
    time_t lastAccessed;
} Record;

typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* cleanupThread(void *arg) {
    time_t now = time(NULL);
    while (1) {
        sleep(24 * 60 * 60); // Sleep for 24 hours.
        pthread_mutex_lock(&lock);
        Node *currentNode = head;
        Node *previousNode = NULL;
        while (currentNode != NULL) {
            if (now - currentNode->record->lastAccessed > 24 * 60 * 60) { // If record hasn't been accessed in the last 24 hours.
                if (previousNode == NULL) { // If this is the head of the list.
                    head = currentNode->next;
                } else {
                    previousNode->next = currentNode->next;
                }
                free(currentNode);
            }
            previousNode = currentNode;
            currentNode = currentNode->next;
        }
        pthread_mutex_unlock(&lock);
    }
}

void insertRecord(int key, long offset) {
    Record *record = malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;
    record->lastAccessed = time(NULL);

    pthread_mutex_lock(&lock);
    Node *node = malloc(sizeof(Node));
    node->record = record;
    if (head == NULL || head->record->key > key) { // If list is empty or new record should be at the start.
        node->next = head;
        head = node;
    } else {
        Node *currentNode = head;
        while (currentNode->next != NULL && currentNode->next->record->key < key) { // Find correct position in list.
            currentNode = currentNode->next;
        }
        node->next = currentNode->next;
        currentNode->next = node;
    }
    pthread_mutex_unlock(&lock);
}
```
