#include <search.h>

typedef struct Record {
    int key;
    long offset;
    int value;
    struct Record *next;
} Record;

Record *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
ENTRY e, *ep;

void insert(int key, long offset, int value) {
    pthread_mutex_lock(&lock);

    Record *record = malloc(sizeof(Record));
    if (record == NULL) {
        // Handle memory allocation failure
        return;
    }
    record->key = key;
    record->offset = offset;
    record->value = value;

    Record **pp = &head;
    while (*pp != NULL && (*pp)->key < key) {
        pp = &(*pp)->next;
    }
    record->next = *pp;
    *pp = record;

    e.key = (char*)&record->key;
    e.data = (void*)record;
    hsearch(e, FIND|ENTER);

    pthread_mutex_unlock(&lock);
}

Record* find(int key) {
    Record *result = NULL;
    pthread_mutex_lock(&lock);

    e.key = (char*)&key;
    ep = hsearch(e, FIND);
    if (ep != NULL) {
        result = ep->data;
    }

    pthread_mutex_unlock(&lock);
    return result;
}

void delete(int key) {
    pthread_mutex_lock(&lock);

    Record **pp = &head;
    while (*pp != NULL && (*pp)->key < key) {
        pp = &(*pp)->next;
    }
    if (*pp != NULL && (*pp)->key == key) {
        Record *temp = *pp;
        *pp = temp->next;

        e.key = (char*)&key;
        hsearch(e, FIND|DEL);

        free(temp);
    }

    pthread_mutex_unlock(&lock);
}
```
