    if (components == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }

    memcpy(components, &lock, sizeof(pthread_mutex_t));
    memcpy(components + sizeof(pthread_mutex_t), &offsets, sizeof(void*));
    memcpy(components + sizeof(pthread_mutex_t) + sizeof(void*), &keys, sizeof(void*));
