#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

typedef struct {
    int fd;
    size_t maxSize;
} ThreadArgs;

void* readAndProcess(void *args) {
    ThreadArgs *threadArgs = (ThreadArgs*) args;
    int *array = malloc(sizeof(int) * threadArgs->maxSize);
    if (!array) {
        perror("Memory allocation failed");
        pthread_exit(NULL);
    }

    char buffer[20]; // assuming integers are less than 16 digits long
    size_t count = 0;
    int max = INT_MIN;
    long sum = 0;
    while (read(threadArgs->fd, buffer, sizeof(buffer) - 1) > 0) {
        char *endptr;
        errno = 0;
        long val = strtol(buffer, &endptr, 10);

        if (errno == ERANGE || val < 0 || endptr == buffer) continue; // skip invalid input

        array[count++] = val;
        sum += val;
        max = val > max ? val : max;
    }

    printf("Valid integers: %zu\n", count);
    printf("Sum of valid integers: %ld\n", sum);
    printf("Average value: %.2f\n", (double)sum / count);
    printf("Largest integer: %d\n", max);

    free(array);
    pthread_exit(NULL);
}

int main() {
    int fd = open("input.txt", O_RDONLY); // replace with your file descriptor
    if (fd == -1) {
        perror("Failed to open file");
        return 1;
    }

    pthread_t thread;
    ThreadArgs args = { .fd = fd, .maxSize = 10000 }; // replace with your max size
    if (pthread_create(&thread, NULL, readAndProcess, &args)) {
        perror("Failed to create thread");
        return 1;
    }

    pthread_join(thread, NULL);
    close(fd);
    return 0;
}
