#include <limits.h>

// Assume we have an external logging function with this signature
extern void log_error(const char* message);
extern void log_warning(const char* message);

void process_stream() {
    int *array = NULL;
    size_t capacity = 0, length = 0;
    unsigned long long sum = 0;
    int max = INT_MIN;
    int invalidCount = 0;

    while (1) {
        if (length >= capacity) {
            // Double the capacity each time we run out of space
            size_t newCapacity = capacity == 0 ? 1 : capacity * 2;

            // Reallocate memory for the array
            int* tempArray = realloc(array, newCapacity * sizeof(*tempArray));
            if (tempArray == NULL) {
                log_error("Failed to allocate memory");
                free(array);
                return;
            }

            array = tempArray;
            capacity = newCapacity;
        }

        // Read an integer from standard input
        int value;
        if (scanf("%d", &value) != 1 || value < 0) {
            invalidCount++;
            continue;
        }

        array[length] = value;
        length++;

        // Update the sum and max
        sum += value;
        if (value > max) {
            max = value;
        }

        // Check if we've reached the end of input
        if (getchar() == EOF) {
            break;
        }
    }

    double average = length > 0 ? (double)sum / length : 0.0;
    printf("Average: %f\n", average);
    if (average > 100) {
        log_warning("Average exceeds threshold");
    }

    printf("Valid integers processed: %zu\n", length);
    printf("Invalid integers skipped: %d\n", invalidCount);
    printf("Maximum integer found: %d\n", max);

    free(array);
}
