```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long* key_ptr;
} Record;

void manageMemory(int n, int m, int min_val, int max_val) {
    srand(time(NULL)); // seed the random number generator

    // Allocate memory for keys and offsets
    long *offsets = (long*)malloc(n * sizeof(long));
    if (!offsets) exit(-1); // handle allocation failure

    int *keys = (int*)calloc(n, sizeof(int));
    if (!keys) {
        free(offsets);
        exit(-1); // handle allocation failure
    }

    // Allocate memory for records
    Record* records = (Record*)malloc(m * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        exit(-1); // handle allocation failure
    }

    // Initialize records and keys
    for (int i = 0; i < m; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;

        int key_index;
        do {
            key_index = rand() % n;
        } while (keys[key_index] != 0); // ensure no duplicate keys

        records[i].key_ptr = &keys[key_index];
        keys[key_index] = 1; // mark the key as used
    }

    // Update a record's key pointer
    int new_key_index;
    do {
        new_key_index = rand() % n;
    } while (keys[new_key_index] != 0); // ensure no duplicate keys

    Record* record_to_update = &records[rand() % m]; // select a random record to update
    keys[*(record_to_update->key_ptr - offsets)] = 0; // mark the old key as unused
    *(record_to_update->key_ptr) = new_key_index; // update the key pointer

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}
```
