#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    char* data;
} Record;

Record* createTable(int size) {
    // Allocate memory for the table
    Record* table = (Record*)malloc(size * sizeof(Record));

    if (table == NULL) {
        return NULL;  // Handle allocation failure
    }

    // Initialize each record in the table
    for (int i = 0; i < size; ++i) {
        table[i].id = -1;
        table[i].timestamp = 0;
        table[i].data = NULL;
    }

    return table;
}

void setRecord(Record* record, int id, time_t timestamp, const char* data) {
    if (record == NULL || data == NULL) {
        return;  // Handle invalid input
    }

    record->id = id;
    record->timestamp = timestamp;

    // Allocate memory for the string and copy it
    size_t len = strlen(data);
    char* newData = (char*)malloc((len + 1) * sizeof(char));

    if (newData == NULL) {
        return;  // Handle allocation failure
    }

    strcpy(newData, data);

    // Free the old string and set the new one
    free(record->data);
    record->data = newData;
}

void destroyTable(Record* table, int size) {
    if (table == NULL) {
        return;  // Handle invalid input
    }

    // Free each string in the table
    for (int i = 0; i < size; ++i) {
        free(table[i].data);
    }

    // Free the table itself
    free(table);
}
```
