int errno = 0;

// Function to generate a random number within a specified range
long getRandom(long min, long max) {
    pthread_mutex_lock(&lock);
    srand(time(NULL));
    long result = rand() % (max - min + 1) + min;
    pthread_mutex_unlock(&lock);
    return result;
}

// Function to allocate memory for a record array and populate it with random data
Record* generateRecords(int num_records, long offset_range, int key_range, double transaction_amount_range, int value_range) {
    Record* records = malloc(num_records * sizeof(Record));
    assert(records != NULL); // Ensure memory allocation was successful

    for (int i = 0; i < num_records; i++) {
        records[i].offset = getRandom(0, offset_range);
        records[i].key = getRandom(0, key_range);
        records[i].transaction_amount = getRandom(0.0, transaction_amount_range);
        records[i].value = getRandom(0, value_range);
    }

    return records;
}

// Function to serialize the record data into a binary file
void serializeRecords(Record* records, int num_records, const char* path) {
    FILE* fp = fopen(path, "wb");
    assert(fp != NULL); // Ensure file opening was successful

    fwrite(records, sizeof(Record), num_records, fp);

    fclose(fp);
}

// Function to deserialize the record data from a binary file
Record* deserializeRecords(const char* path, int* num_records) {
    FILE* fp = fopen(path, "rb");
    assert(fp != NULL); // Ensure file opening was successful

    struct stat st;
    stat(path, &st);
    *num_records = st.st_size / sizeof(Record);

    Record* records = malloc(*num_records * sizeof(Record));
    assert(records != NULL); // Ensure memory allocation was successful

    fread(records, sizeof(Record), *num_records, fp);

    fclose(fp);

    return records;
}

