        new_node->next = *head;
        *head = new_node;
    } else {
        Node *current = *head;

        while (current->next != NULL && current->next->entry->value < new_node->entry->value) {
            current = current->next;
        }

        new_node->next = current->next;
        current->next = new_node;
    }
}

void delete_list(Node **head) {
    Node *current = *head;

    while (current != NULL) {
        Node *temp = current;
        current = current->next;

        free(temp->entry->str);
        free(temp->entry);
        free(temp);
    }

    *head = NULL;
}

void print_list(Node *head) {
    Node *current = head;

    while (current != NULL) {
        printf("Value: %d, String: %s\n", current->entry->value, current->entry->str);
        current = current->next;
