```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    float value;
    bool flag;
    char* name;
} Config;

typedef struct HashTableNode {
    Config config;
    struct HashTableNode *next;
} HashTableNode;

HashTableNode **hash_table = NULL;
int hash_size = 0;
pthread_mutex_t lock;

unsigned int hash(char* str) {
    unsigned int hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % hash_size;
}

void init_config(Config* config, float value, bool flag, char* name) {
    config->value = value;
    config->flag = flag;
    config->name = malloc(strlen(name) + 1);
    strcpy(config->name, name);
}

void init_hash_table(int size) {
    hash_size = size;
    hash_table = calloc(size, sizeof(HashTableNode*));
    pthread_mutex_init(&lock, NULL);
}

void insert_config(Config config) {
    unsigned int index = hash(config.name);

    pthread_mutex_lock(&lock);
    HashTableNode *node = malloc(sizeof(HashTableNode));
    node->config = config;
    node->next = hash_table[index];
    hash_table[index] = node;
    pthread_mutex_unlock(&lock);
}

Config* get_config(char* name) {
    unsigned int index = hash(name);

    pthread_mutex_lock(&lock);
    HashTableNode *node = hash_table[index];
    while (node != NULL) {
        if (strcmp(node->config.name, name) == 0) {
