['Here is a basic implementation of your requirements in C. Note that this code does not include all the features you mentioned like logging, error handling, database integration, thread safety etc. These are complex topics and would require extensive discussion and additional libraries to implement correctly. 

```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

int initialize_records(size_t size, int min, int max, bool resizeable, size_t additional) {
    if (size == 0 && !resizeable) return -1; // Edge case: zero-sized arrays and no resizing

    long* offsets = malloc(size * sizeof(long));
    if (!offsets) return -2; // Memory allocation failure

    int* keys = calloc(size, sizeof(int));
    if (!keys) {
        free(offsets);
        return -2; // Memory allocation failure
    }

    record* records = malloc(size * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return -2; // Memory allocation failure
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand();
        keys[i] = min + rand() % (max - min + 1);
        records[i].value = keys[i];

        if (records[i].value < min || records[i].value > max) { // Data integrity check
            free(offsets);
            free(keys);
            free(records);
            return -3; // Data integrity failure
        }
    }

    if (resizeable && additional > 0) {
        size += additional;

        offsets = realloc(offsets, size * sizeof(long));
        keys = realloc(keys, size * sizeof(int));
        records = realloc(records, size * sizeof(record));

        if (!offsets || !keys || !records) {
            free(offsets);
            free(keys);
            free(records);
            return -2; // Memory allocation failure
        }
    }

    // Continue with database operations...

    free(offsets);
    free(keys);
    free(records);
    return 0; // Success
}
```
