#include <pthread.h>

typedef struct record {
    long offset;
    int key;
    struct record *next;
} Record;

typedef struct allocator {
    void *memory_pool;
    size_t pool_size;
    pthread_mutex_t lock;
} Allocator;

Allocator allocator;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
Record *head = NULL;
int total = 0, count = 0;
double average = 0.0;

void init_allocator(size_t pool_size) {
    allocator.memory_pool = malloc(pool_size);
    if (allocator.memory_pool == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    allocator.pool_size = pool_size;
    pthread_mutex_init(&allocator.lock, NULL);
}

void *custom_malloc(size_t size) {
    void *block;
    pthread_mutex_lock(&allocator.lock);
    block = allocator.memory_pool;
    allocator.memory_pool += size;
    allocator.pool_size -= size;
    pthread_mutex_unlock(&allocator.lock);
    return block;
}

void add_record(int key) {
    Record *new_node = (Record*) custom_malloc(sizeof(Record));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->key = key;
    pthread_mutex_lock(&list_lock);
    new_node->next = head;
    head = new_node;
    total += key;
    count++;
    average = (double)total / count;
    pthread_mutex_unlock(&list_lock);
}

int find_largest() {
    int max = 0;
    Record *current = head;
    while(current != NULL) {
        if(current->key > max) {
            max = current->key;
        }
        current = current->next;
    }
    return max;
}

